  ('Suspension Row', 'TRX Row', 'bodyweight', 'repdb-trx-row.webp', 'repdb-trx-row-end.webp', ARRAY['Grasp the handles of a suspension trainer with a neutral grip, palms facing each other.', 'Lean back, extending your arms fully, keeping your body straight from head to heels.', 'Engage your core and pull your chest towards your hands, squeezing your shoulder blades together.', 'Pause briefly at the top, then slowly lower yourself back to the starting position with control.', 'Maintain a rigid body throughout the movement, avoiding any sagging in the hips.', 'Tip: Adjust your foot position: the closer your feet are to the anchor point, the harder the exercise.', 'Tip: Keep your elbows close to your body to emphasize the lats, or flare them slightly for more upper back.', 'Tip: Focus on initiating the pull with your back muscles, not just your arms.', 'Tip: Control the eccentric (lowering) phase to maximize muscle engagement.']::text[]),
  ('T-Bar Row', 'T-Bar Row', 'barbell', 'repdb-t-bar-row.webp', 'repdb-t-bar-row-end.webp', ARRAY['Straddle the loaded T-bar with feet shoulder-width apart.', 'Hinge at the hips until your torso is around 45 degrees.', 'Grip the handles and keep your back flat.', 'Pull the bar up toward your chest by driving your elbows back.', 'Squeeze your shoulder blades at the top.', 'Lower the bar under control and repeat.', 'Tip: Keep your hips fixed and avoid heaving the torso upright.', 'Tip: Maintain a soft bend in your knees to protect the lower back.', 'Tip: Let the weight stretch your lats fully at the bottom.']::text[]),
