  ('Close-Grip Lat Pulldown', 'Close Grip Lat Pulldown', 'cable', 'repdb-close-grip-lat-pulldown.webp', 'repdb-close-grip-lat-pulldown-end.webp', ARRAY['Sit at a lat pulldown machine and secure your thighs under the pad.', 'Grip the close-grip handle with palms facing each other.', 'Pull the handle down to your upper chest.', 'Squeeze your lats at the bottom.', 'Return under control and repeat.', 'Tip: Lean back only slightly, not excessively.', 'Tip: Avoid using momentum to pull the handle down.', 'Tip: Drive your elbows down and back, not just your hands.']::text[]),
  ('Dumbbell Row', 'Single-Arm Dumbbell Row', 'dumbbell', 'repdb-single-arm-db-row.webp', 'repdb-single-arm-db-row-end.webp', ARRAY['Place one knee and hand on a bench for support.', 'Hold a dumbbell in the other hand with arm extended.', 'Pull the dumbbell up toward your hip, squeezing your shoulder blade.', 'Lower the dumbbell with control.', 'Repeat on both sides.', 'Tip: Avoid rotating the torso to hoist the weight higher.', 'Tip: Let your arm extend fully at the bottom for a complete stretch.', 'Tip: Keep your back flat from head to hips throughout the set.']::text[]),
  ('Kettlebell Row', 'One Arm Kettlebell Row', 'kettlebell', 'repdb-one-arm-kettlebell-row.webp', 'repdb-one-arm-kettlebell-row-end.webp', ARRAY['Place one hand and knee on a bench for support.', 'Hold a kettlebell in the opposite hand with your arm extended.', 'Pull the kettlebell toward your hip by driving your elbow back.', 'Squeeze your back at the top of the movement.', 'Lower the kettlebell with control.', 'Complete reps on one side, then switch.', 'Tip: Keep your torso square to the floor throughout the set.', 'Tip: Pull with your back muscles rather than just your arm.', 'Tip: Keep your neck neutral, eyes on the floor just ahead.']::text[]),
  ('Lat Pulldown', 'Lat Pulldown', 'cable', 'repdb-lat-pulldown.webp', 'repdb-lat-pulldown-end.webp', ARRAY['Sit at the lat pulldown machine with thighs secured under the pads.', 'Grip the wide bar with an overhand grip.', 'Pull the bar down to your upper chest, squeezing your lats.', 'Slowly return the bar to the starting position.', 'Repeat.', 'Tip: Drive your elbows down and back rather than pulling with your hands.', 'Tip: Avoid leaning far back or using momentum to move the weight.', 'Tip: Keep your chest lifted and shoulders down away from your ears.']::text[]),
  ('Muscle Up', 'Muscle Ups', 'bodyweight', 'repdb-muscle-ups.webp', 'repdb-muscle-ups-end.webp', ARRAY['Hang from a pull-up bar with a false grip.', 'Pull yourself up explosively toward the bar.', 'As your chest reaches the bar, rotate your elbows over and transition into a dip.', 'Press your body up until your arms are fully extended above the bar.', 'Lower back down with control through the same path.', 'Repeat for the desired number of reps.', 'Tip: Use a false grip so your wrists are already over the bar for the transition.', 'Tip: Pull explosively toward your sternum, not just your chin.', 'Tip: Drill the transition on low rings or with bands before full reps.']::text[]),
  ('Pull Up', 'Pull-Up', 'bodyweight', 'repdb-pull-up.webp', 'repdb-pull-up-end.webp', ARRAY['Hang from a bar with an overhand grip, slightly wider than shoulder-width.', 'Pull yourself up until your chin is over the bar.', 'Lower yourself under control to a dead hang.', 'Repeat.', 'Tip: Avoid swinging or kipping.', 'Tip: Engage your lats by pulling your elbows down.']::text[]),
  ('Reverse-Grip Barbell Row', 'Reverse Grip Bent Over Row', 'barbell', 'repdb-reverse-grip-bent-over-row.webp', 'repdb-reverse-grip-bent-over-row-end.webp', ARRAY['Stand with feet shoulder-width apart and grip a barbell underhand.', 'Hinge forward at the hips with a slight knee bend.', 'Let the bar hang with your arms extended.', 'Pull the bar to your lower abdomen by driving your elbows back.', 'Squeeze your back at the top.', 'Lower the bar with control.', 'Repeat for the desired number of reps.', 'Tip: Keep your back flat and your core braced throughout.', 'Tip: Maintain a fixed torso angle instead of heaving upright as you pull.', 'Tip: Keep the bar close to your legs throughout the movement.']::text[]),
  ('Reverse-Grip Lat Pulldown', 'Reverse Grip Lat Pulldown', 'cable', 'repdb-reverse-grip-lat-pulldown.webp', 'repdb-reverse-grip-lat-pulldown-end.webp', ARRAY['Attach a straight bar to a lat pulldown machine.', 'Grip the bar with an underhand grip, shoulder-width apart.', 'Sit and secure your thighs under the pad.', 'Pull the bar down to your upper chest.', 'Squeeze your lats and biceps at the bottom.', 'Return the bar to the starting position with control.', 'Repeat for the desired number of reps.', 'Tip: Keep your chest up and avoid leaning back excessively.', 'Tip: Pull with your elbows, not just your hands.', 'Tip: Squeeze your lats at the bottom of the movement.']::text[]),
  ('Single-Arm Cable Row', 'One-Arm Seated Cable Row', 'cable', 'repdb-one-arm-seated-cable-row.webp', 'repdb-one-arm-seated-cable-row-end.webp', ARRAY['Sit at the cable row station and hold one handle with the working arm extended.', 'Plant the feet, sit tall and brace the trunk without leaning back.', 'Pull the handle towards the lower ribs while drawing the shoulder blade back.', 'Pause briefly without rotating the torso or shrugging the shoulder.', 'Extend the arm under control, finish the set and repeat on the other side.', 'Tip: Keep both shoulders facing forward throughout the repetition.', 'Tip: Drive the elbow back close to the body rather than curling the handle.', 'Tip: Let the shoulder blade reach forward at the start without rounding the lower back.']::text[]),
  ('Single-Arm Lat Pulldown', 'One-Arm Lat Pulldown', 'cable', 'repdb-one-arm-lat-pulldown.webp', 'repdb-one-arm-lat-pulldown-end.webp', ARRAY['Attach a single-handle to the cable pulldown station and sit with your thighs secured under the pad.', 'Reach up and grasp the handle with one hand, arm fully extended.', 'Pull the handle down toward your shoulder, driving your elbow toward your hip.', 'Pause briefly at full contraction, then return to the starting position with control.', 'Complete all reps on one side before switching.', 'Tip: Lean slightly away from the cable to increase lat stretch at the top.', 'Tip: Focus on pulling with your elbow, not your hand, to keep the lat engaged.', 'Tip: Control the eccentric to maximize lat tension throughout the range.']::text[]),
  ('Straight Arm Pulldown', 'Straight-Arm Pulldown', 'cable', 'repdb-straight-arm-pulldown.webp', 'repdb-straight-arm-pulldown-end.webp', ARRAY['Stand facing a cable machine with a straight bar attached to the high pulley.', 'With arms nearly straight, push the bar down in an arc toward your thighs.', 'Squeeze your lats at the bottom.', 'Slowly return the bar to the starting position.', 'Repeat.', 'Tip: Maintain a slight elbow bend without turning the movement into a pressdown.', 'Tip: Hinge slightly at the hips and keep your back flat.', 'Tip: Avoid using body momentum to swing the bar down.']::text[]),
  ('V-Bar Pulldown', 'V-Bar Lat Pulldown', 'machine', 'repdb-v-bar-lat-pulldown.webp', 'repdb-v-bar-lat-pulldown-end.webp', ARRAY['Attach a V-bar (double-D handle) to a lat pulldown cable.', 'Sit with the thighs secured under the pad and grip the handle, palms facing each other.', 'Begin with the arms fully extended overhead.', 'Pull the handle down to the sternum by driving the elbows down and slightly back.', 'Squeeze the lats at the bottom, then return slowly under control.', 'Repeat for the recommended number of repetitions.', 'Tip: The neutral grip is easier on the shoulders than pronated or supinated grips.', 'Tip: Imagine pulling your ribs toward your hips — think lats, not arms.']::text[]),
  ('Weighted Pull Up', 'Weighted Pull-Up', 'bodyweight', 'repdb-weighted-pull-up.webp', 'repdb-weighted-pull-up-end.webp', ARRAY['Attach a plate to a dip belt around your waist so the weight hangs between your legs, or hold the load between your feet.', 'Grip the pull-up bar with an overhand grip slightly wider than shoulder-width and hang at full arm extension with your legs together.', 'Pull your elbows down and back to drive your chest toward the bar until your chin clears it.', 'Lower yourself under control back to the full dead hang, keeping tension on your lats and letting the weight settle before the next rep.', 'Repeat for the desired number of reps.', 'Tip: Add weight only once you can do clean bodyweight pull-ups through a full range — small jumps of 2.5–5 kg are enough, since the load stacks on top of your own bodyweight.', 'Tip: Keep your legs together and your core braced so the hanging plate does not start swinging; a swinging weight turns the rep into a kip.', 'Tip: Do not cut the bottom short — return to a full dead hang each rep, and stop the set when your chin stops clearing the bar rather than grinding out partials.']::text[]),
  ('Arnold Press', 'Arnold Press', 'dumbbell', 'repdb-arnold-press.webp', 'repdb-arnold-press-end.webp', ARRAY['Hold a pair of dumbbells at shoulder height with palms facing you.', 'Press the dumbbells overhead while rotating your palms to face forward.', 'Fully extend your arms at the top without locking the elbows.', 'Reverse the motion and rotate back to the start.', 'Repeat for the desired number of reps.', 'Tip: Time the palm rotation evenly throughout the press, not all at once.', 'Tip: Avoid arching your lower back as the weight goes overhead.', 'Tip: Use a lighter load than a standard press to control the rotation.']::text[]),
  ('Cable Front Raise', 'Cable Front Raise', 'cable', 'repdb-cable-front-raise.webp', 'repdb-cable-front-raise-end.webp', ARRAY['Stand facing away from a low cable pulley with a handle attachment.', 'Hold the handle with arm extended at your thigh.', 'Raise your arm forward to shoulder height keeping it straight.', 'Pause at the top.', 'Lower under control and repeat.', 'Tip: Avoid swinging or using momentum to lift the handle.', 'Tip: Keep your torso upright; do not lean back as the arm rises.', 'Tip: Brace your core and keep your wrist neutral throughout.']::text[]),
  ('Clean and Jerk', 'Clean and Jerk', 'barbell', 'repdb-clean-and-jerk.webp', 'repdb-clean-and-jerk-end.webp', ARRAY['Pull a loaded barbell from the floor to your shoulders as in a clean.', 'Stand fully with the bar racked on your front delts.', 'Dip slightly and drive the bar overhead explosively.', 'Drop into a partial squat under the bar as your arms lock out overhead, feet staying about hip-width apart.', 'Stand up fully and hold the bar steady overhead before lowering it.', 'Tip: Stand fully and reset your position before starting the jerk.', 'Tip: Drive the bar up with your legs, not just your arms.', 'Tip: Lock your arms out as you drop under the bar, then stand and hold the finish briefly.']::text[]),
  ('Front Raise', 'Dumbbell Front Raise', 'dumbbell', 'repdb-dumbbell-front-raise.webp', 'repdb-dumbbell-front-raise-end.webp', ARRAY['Stand with dumbbells at your sides, palms facing your thighs.', 'Raise one or both dumbbells forward to shoulder height.', 'Lower under control.', 'Repeat.', 'Tip: Avoid using momentum.', 'Tip: Slight elbow bend reduces joint stress.']::text[]),
  ('Handstand Push Up', 'Handstand Push Ups', 'bodyweight', 'repdb-handstand-push-ups.webp', 'repdb-handstand-push-ups-end.webp', ARRAY['Set two parallettes shoulder-width apart and kick up into a freestanding handstand on them.', 'Brace your core and keep your body straight, legs together.', 'Bend your elbows to lower your head between the handles.', 'Go down until your head is about level with the handles.', 'Press through the handles back to straight arms, keeping your balance.', 'Repeat for the desired number of reps.', 'Tip: Lower under control instead of dropping into the bottom position.', 'Tip: Keep the ribs down and the body stacked over the hands so the back does not arch.', 'Tip: Learn it against a wall and through pike push-ups before going freestanding.']::text[]),
  ('Kettlebell Press', 'One Arm Kettlebell Shoulder Press', 'kettlebell', 'repdb-one-arm-kettlebell-shoulder-press.webp', 'repdb-one-arm-kettlebell-shoulder-press-end.webp', ARRAY['Hold a kettlebell in the racked position at one shoulder.', 'Stand tall with feet hip-width apart.', 'Press the kettlebell straight overhead until your arm is locked out.', 'Keep your core tight throughout.', 'Lower the kettlebell back to the rack position with control.', 'Complete reps on one side, then switch.', 'Tip: Avoid leaning away from the kettlebell as it travels overhead.', 'Tip: Finish with your biceps close to your ear at lockout.', 'Tip: Squeeze your glutes to keep your ribs from flaring.']::text[]),
  ('Machine Shoulder Press', 'Machine Shoulder Press', 'machine', 'repdb-machine-shoulder-press.webp', 'repdb-machine-shoulder-press-end.webp', ARRAY['Sit in the machine with your back against the pad.', 'Grip the handles at shoulder level.', 'Press the handles overhead until arms are fully extended.', 'Lower with control to the starting position.', 'Repeat.', 'Tip: Keep your lower back pressed into the pad without overarching.', 'Tip: Keep your wrists stacked directly over your elbows as you press.']::text[]),
  ('Overhead Press', 'Barbell Overhead Press', 'barbell', 'repdb-ohp.webp', 'repdb-ohp-end.webp', ARRAY['Stand with feet shoulder-width apart, bar at collarbone level.', 'Brace your core and press the bar overhead.', 'Lock out at the top with the bar over your mid-foot.', 'Lower the bar back to collarbone height.', 'Repeat.', 'Tip: Do not lean back excessively.', 'Tip: Squeeze your glutes for stability.']::text[]),
  ('Push Press', 'Push Press', 'barbell', 'repdb-push-press.webp', 'repdb-push-press-end.webp', ARRAY['Stand with a barbell racked on your front deltoids.', 'Dip slightly at the knees.', 'Drive up with your legs and press the bar overhead.', 'Lock out fully.', 'Lower to the start.', 'Repeat.', 'Tip: Use leg drive only to initiate — finish with the shoulders.', 'Tip: Keep the core braced throughout.']::text[]),
  ('Seated Barbell Press', 'Seated Barbell Overhead Press', 'barbell', 'repdb-seated-barbell-overhead-press.webp', 'repdb-seated-barbell-overhead-press-end.webp', ARRAY['Set an upright bench inside a rack with the pins at about shoulder height when seated.', 'Sit with your back flat against the pad and unrack the barbell at the front of the shoulders.', 'Press the bar overhead until the arms are fully extended, tucking the head through at the top.', 'Lower the bar back to the collarbones under control.', 'Repeat for the recommended number of repetitions.', 'Tip: Keep the ribs down and glutes tight; do not lean back into a bench press.', 'Tip: Drive the bar straight up, not forward.']::text[]),
  ('Seated Dumbbell Press', 'Seated Dumbbell Shoulder Press', 'dumbbell', 'repdb-seated-db-press.webp', 'repdb-seated-db-press-end.webp', ARRAY['Sit on a bench with back support, holding dumbbells at shoulder height.', 'Press the dumbbells overhead until arms are fully extended.', 'Lower the dumbbells back to shoulder level.', 'Repeat.', 'Tip: Keep your lower back against the pad instead of arching excessively.', 'Tip: Avoid clanging the dumbbells together at the top.', 'Tip: Keep your forearms vertical under the dumbbells throughout the press.']::text[]),
  ('Single-Arm Dumbbell Shoulder Press', 'One Arm Dumbbell Shoulder Press', 'dumbbell', 'repdb-one-arm-dumbbell-shoulder-press.webp', 'repdb-one-arm-dumbbell-shoulder-press-end.webp', ARRAY['Stand with the feet hip-width apart and hold a dumbbell at one shoulder with the palm facing forward.', 'Brace the abdominals and keep the free arm relaxed at your side.', 'Press the dumbbell straight overhead until the arm is fully extended.', 'Pause briefly at the top with the upper arm next to the ear.', 'Lower the dumbbell back to the shoulder under control.', 'Complete the repetitions on one arm, then switch sides.', 'Tip: Keep the ribs down and the glutes tight; do not lean sideways to push the weight up.', 'Tip: Press in a straight line close to the head, not out in front.', 'Tip: Start lighter than you would with two dumbbells; the trunk has to stabilise the load.']::text[]),
  ('Single-Arm Landmine Press', 'One-Arm Landmine Press', 'barbell', 'repdb-one-arm-landmine-press.webp', 'repdb-one-arm-landmine-press-end.webp', ARRAY['Anchor one end of a barbell in a landmine attachment and load the free end.', 'Kneel on one knee or stand and grip the sleeve end at shoulder height with one hand.', 'Press the bar upward and forward along its arc until the arm is fully extended.', 'Lower the bar back to shoulder height under control.', 'Complete all reps before switching sides.', 'Tip: Engage your core to prevent the torso from rotating toward the working arm.', 'Tip: The arc motion is more joint-friendly than a vertical overhead press.', 'Tip: Kneeling on the knee on the same side as the pressing arm, with the other foot planted in front, increases the core''s anti-rotation demand.']::text[]),
  ('Smith Machine Shoulder Press', 'Smith Machine Shoulder Press', 'machine', 'repdb-smith-machine-shoulder-press.webp', 'repdb-smith-machine-shoulder-press-end.webp', ARRAY['Stand inside a Smith machine with your feet hip-width apart and the bar at shoulder level.', 'Grip the bar slightly wider than shoulder-width at shoulder level.', 'Unrack the bar and press it overhead until your arms are extended.', 'Lower the bar back to shoulder level under control.', 'Keep your core tight throughout.', 'Repeat for the desired number of reps.', 'Tip: Stand directly under the bar path before unracking.', 'Tip: Tilt your head back slightly as the bar passes your face.', 'Tip: Avoid flaring your ribs as the bar travels overhead.']::text[]),
  ('Standing Dumbbell Press', 'Dumbbell Shoulder Press', 'dumbbell', 'repdb-dumbbell-shoulder-press.webp', 'repdb-dumbbell-shoulder-press-end.webp', ARRAY['Sit or stand holding dumbbells at shoulder height, palms facing forward.', 'Press both dumbbells overhead until arms are fully extended.', 'Keep your core braced and avoid arching your lower back.', 'Lower the dumbbells under control back to shoulder height.', 'Do not let the dumbbells drift behind your head.', 'Repeat for the desired number of reps.', 'Tip: Stack your wrists directly over your elbows throughout the press.', 'Tip: Exhale as you press up and inhale as you lower.', 'Tip: Keep your elbows slightly in front of your shoulders rather than flared wide.']::text[]),
  ('Turkish Get-Up', 'Kettlebell Turkish Get Ups', 'kettlebell', 'repdb-kettlebell-turkish-get-ups.webp', 'repdb-kettlebell-turkish-get-ups-end.webp', ARRAY['Lie on your back holding a kettlebell pressed overhead in one hand.', 'Bend the knee on the same side and plant the foot flat.', 'Roll up onto your opposite elbow, then to your hand.', 'Drive your hips up and sweep your straight leg back into a lunge.', 'Stand up fully while keeping the kettlebell locked out overhead.', 'Reverse the sequence to return to the start.', 'Tip: Keep your eyes on the kettlebell until you are standing, then look forward.', 'Tip: Move slowly through each step — the get-up is a sequence, not one motion.']::text[]),
  ('Cable Lateral Raise', 'Cable Lateral Raise', 'cable', 'repdb-cable-lateral-raise.webp', 'repdb-cable-lateral-raise-end.webp', ARRAY['Stand sideways to a low pulley and grip the handle with the hand farther from the machine.', 'Keep a soft bend in the elbow and let the cable run across the front of your body.', 'Raise the arm out to the side until parallel to the floor.', 'Lower under control. Complete reps per side, then switch.', 'Maintain tension — do not let the weight rest at the bottom.', 'Tip: Lead with the elbow, not the hand.', 'Tip: Pause briefly at the top, do not swing.', 'Tip: Use a lighter load than for dumbbell — cable tension is constant.']::text[]),
  ('Cable Upright Row', 'Cable Upright Row', 'cable', 'repdb-cable-upright-row.webp', 'repdb-cable-upright-row-end.webp', ARRAY['Stand in front of a cable machine and grip a straight bar or rope at thigh height.', 'Pull the bar up toward your chin, leading with your elbows.', 'Lower under control.', 'Repeat.', 'Tip: Keep elbows higher than your wrists.', 'Tip: Avoid shrugging excessively.']::text[]),
  ('Dumbbell Upright Row', 'Dumbbell Upright Row', 'dumbbell', 'repdb-dumbbell-upright-row.webp', 'repdb-dumbbell-upright-row-end.webp', ARRAY['Stand holding two dumbbells in front of your thighs, palms facing your body.', 'Pull the dumbbells straight up along your body, leading with your elbows.', 'Raise until the dumbbells reach chin height and elbows are above the wrists.', 'Pause briefly, then lower with control.', 'Repeat for the desired reps.', 'Tip: Keep the dumbbells close to your body throughout.', 'Tip: Lead with your elbows, not your hands.', 'Tip: Avoid pulling with a very narrow grip to reduce shoulder impingement risk.']::text[]),
  ('Lateral Raise', 'Dumbbell Lateral Raise', 'dumbbell', 'repdb-lateral-raise.webp', 'repdb-lateral-raise-end.webp', ARRAY['Stand holding dumbbells at your sides.', 'Raise the dumbbells out to the sides until arms are parallel to the floor.', 'Lower under control.', 'Repeat.', 'Tip: Slight bend in the elbows.', 'Tip: Lead with your elbows, not your hands.']::text[]),
  ('Seated Lateral Raise', 'Seated Dumbbell Lateral Raise', 'dumbbell', 'repdb-seated-dumbbell-lateral-raise.webp', 'repdb-seated-dumbbell-lateral-raise-end.webp', ARRAY['Sit on a bench with a dumbbell in each hand at your sides.', 'Keep your back upright and core braced.', 'Raise both dumbbells out to the sides until they reach shoulder height.', 'Keep a slight bend in your elbows.', 'Lower the dumbbells with control.', 'Repeat for the desired number of reps.', 'Tip: Use a light weight to keep the raise strict.', 'Tip: Lead with your elbows rather than your hands.', 'Tip: Raise to shoulder height and lower with control.']::text[]),
  ('Upright Row', 'Barbell Upright Row', 'barbell', 'repdb-upright-row.webp', 'repdb-upright-row-end.webp', ARRAY['Stand holding a barbell with a shoulder-width overhand grip.', 'Pull the bar straight up along your body toward your chin.', 'Lead with your elbows, keeping them above your hands.', 'Lower the bar with control.', 'Repeat.', 'Tip: Use a lighter weight if you feel pinching in your shoulders.', 'Tip: Avoid bending your wrists excessively as the bar rises.', 'Tip: Avoid swinging or using your legs to heave the weight up.']::text[]),
  ('Band Pull Apart', 'Band Pull Apart', 'band', 'repdb-band-pull-apart.webp', 'repdb-band-pull-apart-end.webp', ARRAY['Stand holding a light resistance band with both hands, arms extended straight in front at shoulder height.', 'Hands start shoulder-width apart, palms facing down.', 'Keeping arms straight, pull the band apart by driving the hands out to the sides.', 'Finish with the band touching your chest and the shoulder blades squeezed together.', 'Return slowly to the starting position and repeat.', 'Tip: Lead the movement with the little fingers — this externally rotates the shoulders.', 'Tip: Use a band light enough to do 15–30 clean reps; this is a high-rep prehab exercise.']::text[]),
  ('Barbell Rear Delt Row', 'Barbell Rear Delt Row', 'barbell', 'repdb-barbell-rear-delt-row.webp', 'repdb-barbell-rear-delt-row-end.webp', ARRAY['Hinge at the hips with a flat back until your torso is nearly parallel to the floor.', 'Hold a barbell with an overhand, wider-than-shoulder-width grip, arms hanging.', 'Row the bar up toward your upper chest with the elbows flaring out to the sides.', 'Pause and squeeze the rear delts and upper back at the top.', 'Lower the bar under control and repeat.', 'Tip: Pull with the elbows, not the hands — think of driving them up and out.', 'Tip: Use a lighter load than a standard row; the wide grip reduces leverage.']::text[]),
  ('Cable External Rotation', 'Cable External Rotation', 'cable', 'repdb-cable-external-rotation.webp', 'repdb-cable-external-rotation-end.webp', ARRAY['Set a cable pulley to elbow height and grip the handle.', 'Stand side-on to the machine with your working elbow bent at 90 degrees.', 'Keep your elbow glued to your side and rotate your forearm outward.', 'Pause at the end of the movement.', 'Return under control. Complete reps on one side, then switch.', 'Tip: Use a light weight to keep the rotation strict and controlled.', 'Tip: Keep your wrist straight and in line with your forearm.', 'Tip: Avoid shrugging your shoulder or twisting your torso during the movement.']::text[]),
  ('Cable Rear Delt Fly', 'Cable Reverse Fly', 'cable', 'repdb-cable-reverse-fly.webp', 'repdb-cable-reverse-fly-end.webp', ARRAY['Set both pulleys at about shoulder height and stand centred between the two cable towers.', 'Take the left handle in your right hand and the right handle in your left hand, so the cables cross in front of you.', 'Stand tall with your arms reaching forward at shoulder height and a slight bend in the elbows.', 'Sweep your arms out and back in a wide arc, leading with the elbows, until they are in line with your shoulders.', 'Squeeze your shoulder blades together briefly without arching your lower back.', 'Bring the handles back to the crossed start position slowly and repeat for the planned repetitions.', 'Tip: Keep the elbows soft and fixed; bending and straightening them turns the fly into a row.', 'Tip: Keep your shoulders down and your neck relaxed so the rear deltoids do the work, not the upper trapezius.', 'Tip: Use a light weight and a slow return; the cables pull hardest at the end of the arc, so control that position.']::text[]),
  ('Face Pull', 'Cable Face Pull', 'cable', 'repdb-face-pull.webp', 'repdb-face-pull-end.webp', ARRAY['Attach a rope to a high cable pulley.', 'Pull the rope toward your face, separating the ends.', 'Squeeze your rear deltoids and external rotators.', 'Return to the starting position with control.', 'Repeat.', 'Tip: Keep your elbows high, roughly in line with your shoulders.', 'Tip: Choose a light weight and prioritize control over load.', 'Tip: Avoid leaning back or shrugging your shoulders as you pull.']::text[]),
  ('Rear Delt Fly', 'Rear Delt Fly', 'dumbbell', 'repdb-rear-delt-fly.webp', 'repdb-rear-delt-fly-end.webp', ARRAY['Hold dumbbells and hinge forward at the hips.', 'With a slight bend in elbows, raise the dumbbells out to the sides.', 'Squeeze your shoulder blades at the top.', 'Lower with control.', 'Repeat.', 'Tip: Choose a light weight to keep the movement strict.', 'Tip: Avoid using momentum from the torso to swing the weights up.', 'Tip: Lead with your elbows rather than your hands.']::text[]),
  ('Reverse Pec Deck', 'Machine Reverse Fly', 'machine', 'repdb-machine-reverse-fly.webp', 'repdb-machine-reverse-fly-end.webp', ARRAY['Adjust the seat so the handles are at shoulder height, then sit facing the machine with your chest against the pad.', 'Grip the handles with your arms reaching forward and a slight bend in the elbows.', 'Keep your shoulders down and away from your ears and brace your trunk.', 'Sweep the handles out and back in a wide arc, leading with the elbows, until your arms are roughly in line with your shoulders.', 'Squeeze your shoulder blades together briefly without leaning back off the pad.', 'Return the handles forward slowly and repeat for the planned repetitions.', 'Tip: Lead with the elbows rather than pulling with the hands, so the rear deltoids do the work and not the biceps.', 'Tip: Keep the chest on the pad and the neck relaxed; leaning back or shrugging moves the load to the upper trapezius.', 'Tip: Choose a weight you can lower under control; a lighter load with a slow return works the rear deltoids better than a heavy swing.']::text[]),
  ('Barbell Shrug', 'Barbell Shrug', 'barbell', 'repdb-shrug.webp', 'repdb-shrug-end.webp', ARRAY['Stand holding a barbell at arm''s length with an overhand grip.', 'Shrug your shoulders straight up toward your ears.', 'Hold briefly at the top.', 'Lower your shoulders back down with control.', 'Repeat.', 'Tip: Avoid rolling the shoulders forward or backward at the top.', 'Tip: Keep your arms relaxed and let the traps do the work.', 'Tip: Keep your neck neutral instead of jutting the chin forward.']::text[]),
  ('Behind-the-Back Shrug', 'Behind the Back Barbell Shrug', 'barbell', 'repdb-behind-the-back-barbell-shrug.webp', 'repdb-behind-the-back-barbell-shrug-end.webp', ARRAY['Stand holding a barbell behind your back with an overhand grip.', 'Keep your arms straight and chest up.', 'Shrug your shoulders straight up toward your ears.', 'Pause and squeeze at the top.', 'Lower under control and repeat.', 'Tip: Lift straight up and down without rolling the shoulders.', 'Tip: Avoid bending your elbows to heave the weight higher.', 'Tip: Stand tall with a neutral neck and look straight ahead.']::text[]),
  ('Dumbbell Shrug', 'Dumbbell Shrug', 'dumbbell', 'repdb-db-shrug.webp', 'repdb-db-shrug-end.webp', ARRAY['Stand holding dumbbells at your sides.', 'Shrug your shoulders straight up as high as possible.', 'Hold briefly, then lower.', 'Repeat.', 'Tip: Do not roll your shoulders.', 'Tip: Focus on squeezing the traps at the top.']::text[]),
  ('Machine Shrug', 'Plate-Loaded Shrug', 'machine', 'repdb-plate-loaded-shrug.webp', 'repdb-plate-loaded-shrug-end.webp', ARRAY['Load the plate horns evenly and stand on the machine platform, facing away from the frame.', 'Take a handle in each hand with your arms hanging straight down at your sides and your shoulders relaxed.', 'Stand tall with your chest up, your chin level and your knees soft.', 'Shrug your shoulders straight up toward your ears as high as they will go, and hold for a moment at the top.', 'Lower under control until your shoulders are fully down, and repeat for the desired number of repetitions.', 'Tip: Shrug straight up. Rolling the shoulders adds travel but no extra trap work, and it takes the shoulder joint through a loaded circle for nothing.', 'Tip: Keep the arms straight and passive. Bending the elbows turns the movement into a short upright row and takes the load off the traps.', 'Tip: The handles hanging at your sides are what this machine is for -- there is no bar to clear your thighs, so you can stand upright and use a full range without shortening the top.']::text[]),
  ('Barbell Curl', 'Barbell Curl', 'barbell', 'repdb-barbell-curl.webp', 'repdb-barbell-curl-end.webp', ARRAY['Stand holding a barbell with a shoulder-width underhand grip.', 'Curl the bar up toward your shoulders.', 'Squeeze at the top, then lower under control.', 'Repeat.', 'Tip: Avoid swinging the torso.', 'Tip: Keep elbows pinned at your sides.']::text[]),
  ('Barbell Preacher Curl', 'Barbell Preacher Curl', 'barbell', 'repdb-barbell-preacher-curl.webp', 'repdb-barbell-preacher-curl-end.webp', ARRAY['Sit on a preacher bench with your chest against the pad, gripping a barbell with an underhand, shoulder-width grip.', 'Position your upper arms firmly against the pad, ensuring your elbows are slightly bent at the start.', 'Curl the barbell upwards by contracting your biceps, keeping your upper arms stationary on the pad.', 'Squeeze your biceps at the top of the movement, focusing on peak contraction.', 'Slowly lower the barbell back to the starting position, controlling the eccentric phase.', 'Lower until your arms are almost fully extended to get a full stretch in the biceps.', 'Tip: Maintain constant tension on the biceps throughout the entire range of motion.', 'Tip: Avoid lifting your elbows off the pad; this indicates you''re using too much weight or momentum.', 'Tip: Lower the bar slowly and under control; the stretched bottom position is where the elbows are most exposed.', 'Tip: Keep your wrists straight and aligned with your forearms to prevent strain.']::text[]),
  ('Cable Curl', 'Cable Curl', 'cable', 'repdb-cable-curl.webp', 'repdb-cable-curl-end.webp', ARRAY['Stand facing a low cable pulley with a straight bar or EZ-bar attachment.', 'Grip the bar with an underhand grip, elbows at your sides.', 'Curl the bar up toward your shoulders.', 'Lower with control.', 'Repeat.', 'Tip: Keep your elbows from drifting forward as you curl.', 'Tip: Straighten your arms fully at the bottom of each rep.', 'Tip: Avoid leaning back to help lift the weight.']::text[]),
  ('Concentration Curl', 'Concentration Curl', 'dumbbell', 'repdb-concentration-curl.webp', 'repdb-concentration-curl-end.webp', ARRAY['Sit on a bench with legs spread, holding a dumbbell in one hand.', 'Brace your elbow against the inside of your thigh.', 'Curl the dumbbell up toward your shoulder.', 'Lower with control.', 'Repeat on both sides.', 'Tip: Keep your upper arm vertical and let only the forearm move.', 'Tip: Avoid swinging your torso to help the weight up.', 'Tip: Match the reps on each arm to avoid muscle imbalances.']::text[]),
  ('Cross-Body Hammer Curl', 'Cross Body Hammer Curl', 'dumbbell', 'repdb-cross-body-hammer-curl.webp', 'repdb-cross-body-hammer-curl-end.webp', ARRAY['Stand tall holding a dumbbell in each hand with a neutral grip.', 'Curl one dumbbell up across your body toward the opposite shoulder.', 'Keep your elbow stationary at your side.', 'Lower under control and repeat on the other side.', 'Continue alternating for the desired number of reps.', 'Tip: Keep your elbow pinned at your side throughout the curl.', 'Tip: Avoid swinging your torso to lift the weight.', 'Tip: Lower under control rather than letting the dumbbell drop.']::text[]),
  ('Drag Curl', 'Drag Curl', 'barbell', 'repdb-drag-curl.webp', 'repdb-drag-curl-end.webp', ARRAY['Stand holding a barbell with an underhand grip, hands shoulder-width apart.', 'Start with the bar at the thighs and elbows at the sides.', 'Curl the bar by sliding (dragging) it straight up along your body.', 'As the bar rises, let the elbows travel backward so the bar stays in contact with your torso.', 'Stop when the bar reaches mid-chest; the biceps will be fully shortened.', 'Lower under control along the same path and repeat.', 'Tip: Use significantly less weight than a standard curl — the altered mechanics make it much harder.', 'Tip: The bar should never move away from the body.']::text[]),
  ('Dumbbell Curl', 'Dumbbell Bicep Curl', 'dumbbell', 'repdb-bicep-curl.webp', 'repdb-bicep-curl-end.webp', ARRAY['Stand holding dumbbells at your sides, palms forward.', 'Curl the weights up toward your shoulders.', 'Squeeze at the top, then lower under control.', 'Repeat.', 'Tip: Keep your elbows pinned to your sides.', 'Tip: Avoid swinging the weights.']::text[]),
  ('Dumbbell Preacher Curl', 'Dumbbell Preacher Curl', 'dumbbell', 'repdb-db-preacher-curl.webp', 'repdb-db-preacher-curl-end.webp', ARRAY['Adjust the seat so the armpits rest against the top of the pad and the upper arms lie flat along it.', 'Hold a dumbbell in each hand with an underhand grip and let the arms hang down along the pad.', 'Curl both dumbbells up toward the shoulders without lifting the elbows off the pad.', 'Squeeze the biceps briefly at the top.', 'Lower the dumbbells slowly until the arms are almost fully extended, then repeat.', 'Tip: Stop just short of full extension at the bottom to keep tension on the biceps and protect the elbows.', 'Tip: Keep the chest against the pad; leaning back lets the shoulders take over.', 'Tip: Lower the weights slowly; do not let them drop.']::text[]),
  ('EZ-Bar Curl', 'EZ-Bar Curl', 'barbell', 'repdb-ez-bar-curl.webp', 'repdb-ez-bar-curl-end.webp', ARRAY['Stand holding an EZ-bar with an underhand grip on the angled portions.', 'Curl the bar up toward your shoulders, keeping your elbows pinned.', 'Squeeze at the top, then lower under control.', 'Repeat.', 'Tip: Use the inner or outer grip to vary emphasis.', 'Tip: Keep your wrists neutral on the angled grips.']::text[]),
  ('Hammer Curl', 'Dumbbell Hammer Curl', 'dumbbell', 'repdb-hammer-curl.webp', 'repdb-hammer-curl-end.webp', ARRAY['Stand holding dumbbells at your sides with palms facing each other.', 'Curl the weights up while keeping your palms facing inward.', 'Squeeze at the top, then lower under control.', 'Repeat.', 'Tip: Keep your elbows pinned to your sides throughout.', 'Tip: Keep your wrists straight and rigid throughout the curl.', 'Tip: Avoid leaning back or swinging the weights up.']::text[]),
  ('Incline Dumbbell Curl', 'Incline Dumbbell Curl', 'dumbbell', 'repdb-incline-db-curl.webp', 'repdb-incline-db-curl-end.webp', ARRAY['Sit on an incline bench set to 45 degrees, holding dumbbells at your sides.', 'Let your arms hang straight down with palms forward.', 'Curl the dumbbells up toward your shoulders.', 'Lower with control to full extension.', 'Repeat.', 'Tip: Keep your head and shoulders against the bench throughout.', 'Tip: Don''t let your elbows drift forward as you curl.', 'Tip: Avoid shrugging your shoulders forward as you lift the weight.']::text[]),
  ('Incline Hammer Curl', 'Incline Hammer Curl', 'dumbbell', 'repdb-incline-hammer-curl.webp', 'repdb-incline-hammer-curl-end.webp', ARRAY['Sit on an incline bench holding dumbbells with a neutral grip.', 'Allow arms to hang straight.', 'Curl the dumbbells up in a hammer motion.', 'Lower slowly.', 'Repeat.', 'Tip: The incline provides a greater stretch.', 'Tip: Avoid swinging.']::text[]),
  ('Machine Bicep Curl', 'Machine Bicep Curl', 'machine', 'repdb-machine-bicep-curl.webp', 'repdb-machine-bicep-curl-end.webp', ARRAY['Sit in the machine and adjust the pad to your arm length.', 'Grip the handles with an underhand grip.', 'Curl the handles toward your shoulders.', 'Lower with control.', 'Repeat.', 'Tip: Keep your upper arms pressed into the pad throughout the set.', 'Tip: Avoid shrugging your shoulders as you curl.', 'Tip: Extend your arms fully at the bottom without bouncing.']::text[]),
  ('Preacher Curl', 'Machine Preacher Curl', 'machine', 'repdb-machine-preacher-curl.webp', 'repdb-machine-preacher-curl-end.webp', ARRAY['Sit at a preacher curl machine and adjust the seat so your armpits sit at the top of the pad.', 'Place the upper arms flat on the pad and grip the handles.', 'Start with the arms extended — but not locked — at the bottom.', 'Curl the handles up by flexing the elbows; squeeze hard at the top.', 'Lower slowly back to the starting position and repeat.', 'Tip: Do not let the elbows lift off the pad at the top.', 'Tip: Stop just short of full extension at the bottom to protect the elbow tendons.']::text[]),
  ('Reverse Barbell Curl', 'Reverse Curl', 'barbell', 'repdb-reverse-curl.webp', 'repdb-reverse-curl-end.webp', ARRAY['Stand and hold a barbell with an overhand grip.', 'Curl the bar up toward your shoulders.', 'Lower under control.', 'Repeat.', 'Tip: Keep wrists straight.', 'Tip: Move through a full range of motion.']::text[]),
  ('Rope Hammer Curl', 'Cable Hammer Curl', 'cable', 'repdb-cable-hammer-curl.webp', 'repdb-cable-hammer-curl-end.webp', ARRAY['Attach a rope to a low cable pulley and stand facing the machine.', 'Grip the rope with a neutral (hammer) grip, palms facing each other.', 'Curl the rope upward toward your shoulders, keeping elbows pinned at your sides.', 'Squeeze at the top, then lower slowly to full extension.', 'Repeat for the desired reps.', 'Tip: Keep your elbows stationary throughout the movement.', 'Tip: Pull the rope ends apart slightly at the top to increase contraction.', 'Tip: Avoid swinging the torso.']::text[]),
  ('Spider Curl', 'EZ Bar Spider Curl', 'barbell', 'repdb-ez-bar-spider-curl.webp', 'repdb-ez-bar-spider-curl-end.webp', ARRAY['Lie chest down on an incline bench holding an EZ bar with underhand grip.', 'Let your arms hang straight down from your shoulders.', 'Curl the bar up toward your shoulders.', 'Squeeze your biceps at the top of the movement.', 'Lower the bar back down with control.', 'Repeat for the desired number of reps.', 'Tip: Let your arms hang straight down and keep the upper arms fixed.', 'Tip: Curl with the biceps only — the bench removes any excuse to swing.', 'Tip: Lower to a full stretch before starting the next rep.']::text[]),
  ('Zottman Curl', 'Zottman Curl', 'dumbbell', 'repdb-zottman-curl.webp', 'repdb-zottman-curl-end.webp', ARRAY['Stand with your feet about hip-width apart, arms extended at your sides, and a dumbbell in each hand with the palms facing forward.', 'Keep your upper arms beside your ribs and curl both dumbbells toward your shoulders without swinging the torso.', 'At the top, keep the elbows bent and rotate the forearms until the palms face down.', 'Lower the dumbbells slowly with the pronated grip until the arms are straight.', 'Turn the palms forward again at the bottom and repeat for the desired number of repetitions.', 'Tip: Use less weight than for a standard dumbbell curl; the palms-down lowering phase is usually the limiting part.', 'Tip: Rotate through the forearms while keeping the wrists straight rather than bending them around the handles.', 'Tip: Keep the elbows close to the ribs and avoid turning the curl into a shoulder swing.']::text[]),
  ('Bench Dip', 'Bench Dips', 'bodyweight', 'repdb-bench-dips.webp', 'repdb-bench-dips-end.webp', ARRAY['Sit on a bench and place your hands on the edge beside your hips.', 'Slide your hips off the bench with legs extended.', 'Lower your body by bending your elbows to 90 degrees.', 'Press through your palms to return to the start.', 'Repeat for the desired number of reps.', 'Tip: Keep your hips close to the bench as you lower.', 'Tip: Avoid letting your shoulders roll forward at the bottom.', 'Tip: Bend your knees to make the movement easier.']::text[]),
  ('Close Grip Bench Press', 'Close-Grip Bench Press', 'barbell', 'repdb-close-grip-bench-press.webp', 'repdb-close-grip-bench-press-end.webp', ARRAY['Lie on a flat bench and grip the barbell with hands shoulder-width apart.', 'Lower the bar to your lower chest keeping elbows close to your sides.', 'Press back up to full extension.', 'Repeat.', 'Tip: Keep elbows tucked to maximize triceps activation.', 'Tip: Avoid too-narrow a grip to prevent wrist strain.']::text[]),
  ('Close-Grip Dumbbell Press', 'Close-Grip Dumbbell Bench Press', 'dumbbell', 'repdb-close-grip-db-bench-press.webp', 'repdb-close-grip-db-bench-press-end.webp', ARRAY['Lie on a flat bench and hold two dumbbells together over your chest.', 'Lower them to your chest keeping elbows close.', 'Press back up.', 'Repeat.', 'Tip: Press the dumbbells together throughout the movement.', 'Tip: Keep elbows tucked.']::text[]),
  ('Diamond Push Up', 'Diamond Push Ups', 'bodyweight', 'repdb-diamond-push-ups.webp', 'repdb-diamond-push-ups-end.webp', ARRAY['Assume a push-up position with hands close together forming a diamond.', 'Keep your elbows tucked close to your sides.', 'Lower your chest toward your hands.', 'Press back up to extend your arms.', 'Repeat for the desired number of reps.', 'Tip: Keep your elbows tracking back along your sides, not flared out.', 'Tip: Hold your body in a rigid straight line from head to heels.', 'Tip: Lower with control until your chest reaches your hands.']::text[]),
  ('Dumbbell Floor Press', 'Dumbbell Floor Press', 'dumbbell', 'repdb-dumbbell-floor-press.webp', 'repdb-dumbbell-floor-press-end.webp', ARRAY['Lie on the floor with a dumbbell in each hand at chest level.', 'Press the dumbbells upward until arms are extended.', 'Lower under control until elbows touch the floor.', 'Repeat.', 'Tip: The floor limits shoulder strain at the bottom.', 'Tip: Keep wrists stacked over elbows.']::text[]),
  ('Dumbbell Kickback', 'Dumbbell Tricep Kickback', 'dumbbell', 'repdb-tricep-kickback.webp', 'repdb-tricep-kickback-end.webp', ARRAY['Hinge forward at the hips, holding a dumbbell in each hand with the elbows bent at 90 degrees.', 'Extend both arms straight back, squeezing the triceps.', 'Hold briefly at full extension.', 'Lower with control.', 'Repeat for the planned number of reps.', 'Tip: Keep your elbows close to your sides and finish with your arms in line with your torso.', 'Tip: Use light dumbbells and avoid swinging them with momentum.', 'Tip: Keep your back flat and your knees slightly bent to hold the hinge.']::text[]),
  ('Dumbbell Overhead Extension', 'Overhead Tricep Extension', 'dumbbell', 'repdb-overhead-tricep-extension.webp', 'repdb-overhead-tricep-extension-end.webp', ARRAY['Stand or sit holding a dumbbell overhead with both hands.', 'Lower the dumbbell behind your head by bending your elbows.', 'Extend your arms back to the starting position.', 'Keep your elbows close to your head throughout.', 'Repeat.', 'Tip: Keep your ribs down and avoid arching your lower back.', 'Tip: Lower until you feel a deep stretch in your triceps.', 'Tip: Check your grip is secure before lowering the dumbbell behind your head.']::text[]),
  ('Floor Press', 'Floor Press', 'barbell', 'repdb-floor-press.webp', 'repdb-floor-press-end.webp', ARRAY['Lie on the floor and position yourself under a barbell in a rack.', 'Unrack the bar and lower it to your chest until your upper arms touch the floor.', 'Press back up to lockout.', 'Repeat.', 'Tip: Elbows touching the floor provides a natural stopping point.', 'Tip: Useful for addressing lockout weakness.']::text[]),
  ('Lying Dumbbell Extension', 'Lying Tricep Extension', 'dumbbell', 'repdb-lying-tricep-extension.webp', 'repdb-lying-tricep-extension-end.webp', ARRAY['Lie flat on a bench and hold one dumbbell in both hands straight above your chest.', 'Keep your upper arms close to vertical, elbows pointing up toward the ceiling.', 'Lower the dumbbell behind your head by bending your elbows.', 'Extend your arms back to the starting position.', 'Squeeze your triceps at the top.', 'Repeat for the desired number of reps.', 'Tip: Keep your elbows pointing up and tucked in rather than flaring out to the sides.', 'Tip: Move only at the elbows, not the shoulders.', 'Tip: Lower the weight under control rather than dropping it.']::text[]),
  ('Machine Dip', 'Seated Dip Machine', 'machine', 'repdb-seated-dip-machine.webp', 'repdb-seated-dip-machine-end.webp', ARRAY['Select your weight on the stack and adjust the seat so the handles are at about shoulder height when you are seated.', 'Sit upright with your back against the pad and grip the handles at your sides with your elbows bent.', 'Keep your shoulders down and your chest up, then press the handles down by straightening your elbows.', 'Squeeze your triceps at the bottom, with your arms straight but not locked out hard.', 'Let the handles rise back up under control until your elbows are bent to about 90 degrees.', 'Repeat for the planned repetitions, keeping your back against the pad.', 'Tip: Keep the elbows close to your sides so the work stays on the triceps.', 'Tip: Do not let the shoulders roll forward or shrug as the handles rise; stop where the stretch in the chest and shoulders is comfortable.', 'Tip: Keep your back against the pad; leaning forward shifts the work toward the chest.']::text[]),
  ('Machine Triceps Extension', 'Machine Triceps Extension', 'machine', 'repdb-machine-triceps-extension.webp', 'repdb-machine-triceps-extension-end.webp', ARRAY['Sit in the tricep extension machine with your back against the seat pad and your upper arms resting flat on the arm pad in front of your chest.', 'Take a handle in each hand with your elbows bent and your hands up near shoulder height.', 'Keeping your upper arms pressed into the pad, extend your elbows to drive the handles down and away until your arms are straight.', 'Squeeze your triceps at full extension, then bend your elbows to return to the start under control.', 'Repeat for the desired number of reps.', 'Tip: Set the seat height so your upper arms lie flat on the pad and your elbows line up with the machine''s pivot — that alignment is what keeps the work on the triceps.', 'Tip: Keep your upper arms glued to the pad; letting them lift turns the movement into a press and takes the triceps out of it.', 'Tip: Straighten your arms fully without snapping the elbows, and resist on the way back instead of letting the weight stack drop.']::text[]),
  ('Overhead Cable Triceps Extension', 'Cable Overhead Tricep Extension', 'cable', 'repdb-cable-overhead-tricep-extension.webp', 'repdb-cable-overhead-tricep-extension-end.webp', ARRAY['Attach a rope to the low pulley and select a light weight.', 'Take the rope in both hands, turn away from the stack and step forward into a staggered stance so the cable pulls you back.', 'Raise the rope overhead with your elbows bent and your upper arms close to your ears, so your hands are behind your head.', 'Brace your trunk and keep your upper arms still, then straighten your elbows to push the rope up until your arms are fully extended overhead.', 'Pause briefly at the top, then bend your elbows to lower the rope back behind your head under control.', 'Repeat for the planned repetitions.', 'Tip: Keep the elbows pointing forward and the upper arms still; letting them flare out or drift turns the extension into a press.', 'Tip: Step far enough forward that the cable holds you steady, and avoid arching your lower back as the arms go overhead.', 'Tip: Use a weight you can control through the full stretch; heavy loads pull the elbows apart.']::text[]),
  ('Ring Dip', 'Ring Dips', 'bodyweight', 'repdb-ring-dips.webp', 'repdb-ring-dips-end.webp', ARRAY['Support yourself on the rings with arms locked out.', 'Lower your body by bending the elbows until upper arms are parallel to the ground.', 'Press back up to the starting position.', 'Repeat.', 'Tip: Keep the rings close to your body.', 'Tip: Turn the rings out at the top for additional chest activation.']::text[]),
  ('Single-Arm Cable Extension', 'Single Arm Tricep Pushdown', 'cable', 'repdb-single-arm-tricep-pushdown.webp', 'repdb-single-arm-tricep-pushdown-end.webp', ARRAY['Attach a single handle to a high cable pulley.', 'Grasp the handle with one hand and keep your elbow pinned to your side.', 'Press the handle down until your arm is fully extended.', 'Squeeze the triceps at the bottom.', 'Slowly return to the start position.', 'Complete reps on one side, then switch.', 'Tip: Keep your elbow pinned to your side throughout.', 'Tip: Avoid leaning forward to add momentum.', 'Tip: Fully extend your arm at the bottom for a complete contraction.']::text[]),
  ('Single-Arm Overhead Extension', 'Single-Arm Dumbbell Overhead Tricep Extension', 'dumbbell', 'repdb-single-arm-dumbbell-overhead-tricep-extension.webp', 'repdb-single-arm-dumbbell-overhead-tricep-extension-end.webp', ARRAY['Stand or sit holding a dumbbell in one hand overhead, arm fully extended.', 'The palm faces forward; the other hand can hold your waist or an upright for stability.', 'Bend the elbow to lower the dumbbell behind the head in a controlled arc.', 'Keep the upper arm vertical and close to the head throughout.', 'Extend the elbow to return the dumbbell overhead.', 'Complete all reps on one side, then switch.', 'Tip: Only the forearm moves — the upper arm stays glued in place.', 'Tip: Don''t let the torso lean to the side; this is also a core exercise.']::text[]),
  ('Skull Crusher', 'Skull Crusher', 'barbell', 'repdb-skull-crusher.webp', 'repdb-skull-crusher-end.webp', ARRAY['Lie on a flat bench holding a barbell over your chest with a narrow grip.', 'Lower the bar toward your forehead by bending at the elbows.', 'Extend your arms back to the start.', 'Repeat.', 'Tip: Keep upper arms vertical throughout.', 'Tip: Lower slowly to protect the elbows.']::text[]),
  ('Triceps Pushdown', 'Cable Tricep Pushdown', 'cable', 'repdb-tricep-pushdown.webp', 'repdb-tricep-pushdown-end.webp', ARRAY['Stand facing a cable machine with a straight bar attachment.', 'Grip the bar and pin your elbows to your sides.', 'Push the bar down until your arms are fully extended.', 'Slowly return to the starting position.', 'Repeat.', 'Tip: Keep your torso upright.', 'Tip: Only your forearms should move.']::text[]),
  ('V-Bar Pushdown', 'V-Bar Tricep Pushdown', 'cable', 'repdb-v-bar-tricep-pushdown.webp', 'repdb-v-bar-tricep-pushdown-end.webp', ARRAY['Attach a V-bar handle to a high cable pulley.', 'Stand facing the stack and grip the V-bar with both hands, palms down.', 'Start with the elbows tucked to the sides, forearms parallel to the floor.', 'Press the handle down until the arms are fully extended.', 'Squeeze the triceps, then return under control to the starting position.', 'Repeat for the recommended number of repetitions.', 'Tip: Keep the elbows pinned to the sides the entire set.', 'Tip: Don''t lean into the bar; a small forward lean is fine, but let the triceps do the work.']::text[]),
  ('Barbell Wrist Curl', 'Barbell Wrist Curl', 'barbell', 'repdb-barbell-wrist-curl.webp', 'repdb-barbell-wrist-curl-end.webp', ARRAY['Sit on a bench with forearms resting on the thighs, palms up.', 'Hold a barbell with hands shoulder-width, wrists hanging off the knees.', 'Let the bar roll down to the fingertips at the bottom.', 'Curl the bar up by flexing the wrists.', 'Lower under control.', 'Tip: Move only at the wrist — keep the forearms still.', 'Tip: Roll the bar to the fingertips for full range.', 'Tip: Use a thumbless grip if it helps wrist comfort.']::text[]),
  ('Farmer''s Walk', 'Dumbbell Farmer''s Walk', 'dumbbell', 'repdb-dumbbell-farmers-walk.webp', null, ARRAY['Stand tall with a dumbbell in each hand, arms extended at your sides.', 'Retract your shoulder blades and brace your core, maintaining a neutral spine.', 'Walk slowly and deliberately for a set distance or duration, taking short, controlled steps.', 'Keep your chest up and avoid leaning to one side as you walk.', 'Focus on maintaining a strong, stable posture throughout the movement.', 'Tip: Use the heaviest dumbbells you can control without compromising form.', 'Tip: Breathe deeply and rhythmically to maintain core tension.', 'Tip: Imagine you are balancing a glass of water on your head.']::text[]),
  ('Plate Pinch', 'Plate Pinch', 'other', 'repdb-plate-pinch.webp', 'repdb-plate-pinch-end.webp', ARRAY['Stand a weight plate on its edge on the floor.', 'Squat down and pinch the plate by its rim between the fingers and thumb of one hand — no handles, just pinch.', 'Stand up and hold the plate at the side for time, keeping the arm straight.', 'Set it back down under control.', 'Repeat on the other hand.', 'Tip: Start with a 5 kg / 10 lb plate and build up; pinching two plates together smooth-side out is a harder variation.', 'Tip: Chalk on the hands makes a huge difference; sweaty pinches fail fast.']::text[]),
  ('Wrist Curl', 'Bilateral Dumbbell Wrist Curl', 'dumbbell', 'repdb-wrist-curl.webp', 'repdb-wrist-curl-end.webp', ARRAY['Sit on a bench holding a dumbbell in each hand, forearms resting on your thighs, palms up.', 'Let both dumbbells roll down to your fingertips.', 'Curl both dumbbells up by flexing your wrists.', 'Squeeze at the top, then lower under control.', 'Repeat for the desired number of reps.', 'Tip: Keep your forearms pinned to your thighs throughout -- only the wrists move.', 'Tip: Use a lighter load per hand than you would single-arm, since both sides work simultaneously.']::text[]),
  ('Wrist Roller', 'Wrist Roller', 'other', 'repdb-wrist-roller.webp', 'repdb-wrist-roller-end.webp', ARRAY['Grip the wrist roller handle with your elbows bent at your sides and your forearms in front of you at waist height.', 'Let the weight hang from the cord.', 'Roll the handle forward with alternating wrist movements to wind the weight up.', 'Keep your elbows at your sides throughout.', 'Once fully wound, reverse the rotation to lower the weight.', 'Repeat for the desired number of reps.', 'Tip: Use full wrist rotations rather than small partial turns.', 'Tip: Keep your shoulders relaxed and avoid shrugging as you roll.', 'Tip: Control the unwinding phase instead of letting the weight drop.']::text[]),
  ('Back Squat', 'Barbell Back Squat', 'barbell', 'repdb-squat.webp', 'repdb-squat-end.webp', ARRAY['Position the bar on your upper traps.', 'Unrack and step back, feet shoulder-width apart.', 'Brace your core and squat down until thighs are parallel.', 'Drive through your heels to stand back up.', 'Repeat.', 'Tip: Keep your chest up throughout the movement.', 'Tip: Push your knees out in line with your toes.']::text[]),
  ('Barbell Lunge', 'Barbell Lunge', 'barbell', 'repdb-barbell-lunge.webp', 'repdb-barbell-lunge-end.webp', ARRAY['Place a barbell across your upper back and stand tall.', 'Step forward with one leg into a long stride.', 'Lower your back knee toward the ground until your front thigh is parallel.', 'Drive through your front heel to return to standing.', 'Complete reps on one side, then switch.', 'Tip: Take a stride long enough that your front knee stays over your ankle.', 'Tip: Keep your torso upright and core braced under the bar.', 'Tip: Push the floor away through the front heel, not the toes.']::text[]),
  ('Bodyweight Squat', 'Bodyweight Squat', 'bodyweight', 'repdb-bodyweight-squat.webp', 'repdb-bodyweight-squat-end.webp', ARRAY['Stand with feet shoulder-width apart and arms extended forward.', 'Sit back and down by bending your hips and knees.', 'Lower until your thighs are parallel to the floor.', 'Drive through your heels to return to standing.', 'Repeat for the desired number of reps.', 'Tip: Keep your weight spread across your whole foot.', 'Tip: Track your knees in line with your toes.', 'Tip: Keep your chest up to avoid rounding the upper back.']::text[]),
  ('Box Jump', 'Box Jump', 'bodyweight', 'repdb-box-jump.webp', 'repdb-box-jump-end.webp', ARRAY['Stand a foot in front of a sturdy box with feet shoulder-width.', 'Drop into a quarter-squat and swing the arms back.', 'Drive the arms up and explode off the floor onto the box.', 'Land softly with both feet flat and knees bent.', 'Step down — do not jump down — and reset.', 'Tip: Always step down — repeated drop-landings stress the Achilles.', 'Tip: Land softly with the whole foot, knees tracking over the toes.', 'Tip: Pick a box height you can clear cleanly without piking the hips.']::text[]),
  ('Box Squat', 'Barbell Box Squat', 'barbell', 'repdb-barbell-box-squat.webp', 'repdb-barbell-box-squat-end.webp', ARRAY['Set a box or bench behind you at a height where your thighs end up about parallel to the floor when you sit on it.', 'Take the barbell on your upper back, step back and stand with your feet a little wider than shoulder-width.', 'Brace your trunk and push your hips back, then lower yourself under control toward the box.', 'Sit onto the box without dropping onto it, keeping your chest up and your shins close to vertical.', 'Pause briefly with your muscles still tight, without relaxing your back.', 'Drive through your whole foot to stand up, and repeat for the planned repetitions.', 'Tip: Sit back rather than down; the box should be touched with your hips, not rested on with your weight.', 'Tip: Keep the torso tight in the pause; relaxing on the box is where most back injuries happen.', 'Tip: Use a box that cannot slide, and lower it as you progress until you can squat to full depth.']::text[]),
  ('Bulgarian Split Squat', 'Bulgarian Split Squat', 'dumbbell', 'repdb-bulgarian-split-squat.webp', 'repdb-bulgarian-split-squat-end.webp', ARRAY['Stand in front of a bench, place one foot behind you on the bench.', 'Hold dumbbells at your sides.', 'Lower your body until your front thigh is parallel to the floor.', 'Push through your front heel to stand back up.', 'Repeat on both sides.', 'Tip: Keep most of your weight on the front leg.', 'Tip: Track your front knee over your toes without letting it cave inward.', 'Tip: Square your hips forward and avoid rotating toward the bench.']::text[]),
  ('Dumbbell Squat', 'Dumbbell Squat', 'dumbbell', 'repdb-db-squat.webp', 'repdb-db-squat-end.webp', ARRAY['Stand with feet shoulder-width, a dumbbell in each hand at the sides.', 'Brace the core and keep the chest up.', 'Squat down by hinging at the hips and bending the knees.', 'Descend until the thighs are parallel or below.', 'Drive through the heels to stand back up.', 'Tip: Keep the chest up and the back flat throughout.', 'Tip: Push the knees out in line with the toes.', 'Tip: Use straps if grip becomes the limiting factor.']::text[]),
  ('Front Squat', 'Front Squat', 'barbell', 'repdb-front-squat.webp', 'repdb-front-squat-end.webp', ARRAY['Clean or rack the bar to your front deltoids with elbows high.', 'Squat down keeping torso upright until thighs are parallel.', 'Drive back up.', 'Repeat.', 'Tip: Maintain high elbows to keep the bar stable.', 'Tip: A more upright torso increases quad activation.']::text[]),
  ('Goblet Squat', 'Dumbbell Goblet Squat', 'dumbbell', 'repdb-db-goblet-squat.webp', 'repdb-db-goblet-squat-end.webp', ARRAY['Stand with your feet slightly wider than shoulder-width and your toes turned out a little.', 'Hold one dumbbell vertically at your chest, with both hands cupped under the top end and your elbows pointing down.', 'Brace your trunk and sit your hips back and down, keeping your chest tall and the dumbbell close to your body.', 'Lower until your thighs are at least parallel to the floor, with your knees tracking over your toes and your heels flat.', 'Pause briefly in the bottom position, then drive through your whole foot to stand back up.', 'Repeat for the planned repetitions without letting the dumbbell drift away from your chest.', 'Tip: Keep your elbows inside your knees at the bottom; they can lightly press the knees out and help you sit deeper.', 'Tip: Let the dumbbell stay at the chest rather than sinking toward your stomach, or your back will round to compensate.', 'Tip: If your heels lift, raise them on a small plate or turn your toes out a little more until you can stay flat.']::text[]),
  ('Hack Squat', 'Hack Squat', 'machine', 'repdb-hack-squat.webp', 'repdb-hack-squat-end.webp', ARRAY['Load the hack squat machine and step on, positioning your back and shoulders against the pads.', 'Place your feet shoulder-width on the platform with toes turned out slightly.', 'Unlock the safety handles and lower the sled by bending at the knees and hips.', 'Descend until your thighs are at least parallel to the platform.', 'Drive through your heels to extend the legs and push the sled back to the start.', 'Re-engage the safety handles after your final rep.', 'Tip: Keep your lower back pressed against the pad throughout the movement.', 'Tip: Placing the feet higher on the platform shifts emphasis to the glutes and hamstrings.', 'Tip: Control the descent; do not bounce out of the bottom position.']::text[]),
  ('Hang Clean', 'Hang Clean', 'barbell', 'repdb-hang-clean.webp', 'repdb-hang-clean-end.webp', ARRAY['Stand holding a barbell with a shoulder-width grip at your thighs.', 'Hinge at the hips to lower the bar just above your knees.', 'Explosively extend your hips, knees, and ankles.', 'Shrug your shoulders and pull the bar up.', 'Pull yourself under the bar and catch it on your front shoulders in a full squat.', 'Stand up tall, then return to the hang position.', 'Tip: Hinge to just above the knees before exploding upward.', 'Tip: Shrug and pull the bar up close to your body.', 'Tip: Catch the bar on your shoulders as you sit into the squat.']::text[]),
  ('Jump Squat', 'Jump Squat', 'bodyweight', 'repdb-jump-squat.webp', 'repdb-jump-squat-end.webp', ARRAY['Stand with feet shoulder-width apart.', 'Drop into a quarter-squat with the arms back.', 'Explode upward, swinging the arms up and jumping as high as you can.', 'Land softly back into a quarter-squat to absorb impact.', 'Repeat without pausing for the prescribed reps.', 'Tip: Land softly with bent knees to absorb impact.', 'Tip: Drive the arms up to add height to the jump.', 'Tip: Keep the chest up — do not let the torso collapse.']::text[]),
  ('Kettlebell Pistol Squat', 'Kettlebell Pistol Squat', 'kettlebell', 'repdb-kettlebell-pistol-squat.webp', 'repdb-kettlebell-pistol-squat-end.webp', ARRAY['Hold a kettlebell at your chest with both hands.', 'Stand on one leg with the other leg extended forward.', 'Lower your hips down into a one-legged squat.', 'Keep your raised leg off the floor throughout.', 'Drive through your standing heel to return to standing.', 'Complete reps on one side, then switch.', 'Tip: Keep your standing heel rooted to the floor throughout.', 'Tip: Descend slowly to stay in control at the bottom.', 'Tip: Push the kettlebell slightly forward to counterbalance as you sit back.']::text[]),
  ('Leg Extension', 'Leg Extension', 'machine', 'repdb-leg-extension.webp', 'repdb-leg-extension-end.webp', ARRAY['Sit in the leg extension machine with ankles behind the pad.', 'Extend your legs until they are straight.', 'Squeeze your quads at the top.', 'Lower with control.', 'Repeat.', 'Tip: Adjust the seat so your knees align with the machine''s pivot point.', 'Tip: Keep your back pressed against the pad throughout.', 'Tip: Avoid swinging the weight up with momentum.']::text[]),
  ('Leg Press', 'Leg Press', 'machine', 'repdb-leg-press.webp', 'repdb-leg-press-end.webp', ARRAY['Sit in the leg press machine with feet shoulder-width apart on the platform.', 'Release the safety catches and lower the platform by bending your knees.', 'Push the platform back up until legs are nearly straight.', 'Do not lock your knees at the top.', 'Repeat.', 'Tip: Keep your lower back and hips pressed into the seat.', 'Tip: Lower only as far as you can without your hips tucking under.', 'Tip: Drive evenly through your whole foot, not just your toes.']::text[]),
  ('Narrow-Stance Leg Press', 'Close-Stance Leg Press', 'machine', 'repdb-close-stance-leg-press.webp', 'repdb-close-stance-leg-press-end.webp', ARRAY['Set the seat and back pad so your lower back stays supported throughout the repetition.', 'Place your feet close together near the middle of the platform, with the toes and knees pointing along the same line.', 'Lower the sled by bending the knees and hips while keeping both feet flat and the knees tracking over the toes.', 'Press the platform away through the whole foot until the legs are extended without snapping the knees straight.', 'Return under control and repeat for the desired number of repetitions.', 'Tip: Use only as narrow a stance as lets the knees track comfortably over the toes.', 'Tip: Keep the heels down and avoid letting the knees collapse inward as the sled descends.', 'Tip: Do not trade pelvic position for depth; stop before the lower back starts to round off the pad.']::text[]),
  ('Overhead Squat', 'Overhead Squat', 'barbell', 'repdb-overhead-squat.webp', 'repdb-overhead-squat-end.webp', ARRAY['Hold a barbell overhead with a wide snatch grip and arms locked out.', 'Stand with feet slightly wider than shoulder-width.', 'Squat down by pushing your hips back and bending your knees.', 'Keep the bar directly over the middle of your feet.', 'Drive through your heels to stand back up.', 'Repeat for the desired number of reps.', 'Tip: Keep your armpits facing forward to lock the bar in place.', 'Tip: Keep the bar over mid-foot with a more upright torso than a back squat.', 'Tip: Work on shoulder and ankle mobility before adding load.']::text[]),
  ('Reverse Lunge', 'Reverse Lunge', 'dumbbell', 'repdb-reverse-lunge.webp', 'repdb-reverse-lunge-end.webp', ARRAY['Stand holding dumbbells at your sides.', 'Step one leg back and lower your knee toward the floor.', 'Lower until your front thigh is parallel to the floor.', 'Push through your front heel to return to standing.', 'Repeat on both sides.', 'Tip: Keep the front knee tracking in line with your toes.', 'Tip: Stay upright through the torso rather than leaning forward.', 'Tip: Lower the back knee softly instead of dropping it to the floor.']::text[]),
  ('Single-Leg Leg Extension', 'Single Leg Extension', 'machine', 'repdb-single-leg-extension.webp', 'repdb-single-leg-extension-end.webp', ARRAY['Sit on a leg extension machine and place one foot under the pad.', 'Rest the other foot on the floor or let it hang.', 'Extend the working leg until it is nearly straight.', 'Squeeze the quadriceps at the top.', 'Lower the leg back down under control.', 'Complete reps on one side, then switch.', 'Tip: Squeeze the quadriceps hard at the top of the movement.', 'Tip: Lower the weight under control rather than letting it drop.', 'Tip: Keep your back flat against the pad.']::text[]),
  ('Sled Push', 'Sled Push', 'other', 'repdb-sled-push.webp', null, ARRAY['Load the sled and stand behind it, holding the uprights with your hands at about chest height.', 'Lean forward so your body forms a straight diagonal line from your head to your back heel, with your arms extended.', 'Brace your trunk and drive one knee forward, pushing the floor away with the ball of your back foot.', 'Keep taking short, powerful steps, driving each leg back hard to move the sled forward.', 'Keep your hips low and your back flat, and look a short distance ahead of the sled.', 'Push for the planned distance or time, then stop under control and rest before the next push.', 'Tip: Stay low with your arms locked or slightly bent; standing up tall makes you lose drive and push the sled with your arms.', 'Tip: Push through the balls of the feet with short, quick steps rather than long strides.', 'Tip: Pick a load you can keep moving at a steady pace; if the sled stops, the load is too heavy for the set.']::text[]),
  ('Smith Machine Split Squat', 'Smith Machine Split Squat', 'machine', 'repdb-smith-machine-split-squat.webp', 'repdb-smith-machine-split-squat-end.webp', ARRAY['Set the bar on the hooks just below shoulder height, then step under it and rest it across your upper traps.', 'Unrack the bar and take a long stride forward with one foot, leaving the rear foot planted on the floor with the heel lifted.', 'Check that your front shin will stay roughly vertical when you descend; adjust the stride length before you start loading it.', 'Lower straight down by bending both knees until the rear knee is just above the floor and the front thigh is close to parallel.', 'Drive through the front heel to return to the start, keeping both feet in place, and repeat for the desired reps before switching sides.', 'Tip: Set the stride length first, unloaded. Once the bar is on your back the fixed path will not let you shuffle forward to fix a stance that is too short.', 'Tip: Go straight down rather than forward. The bar can only travel vertically, so pushing the hips forward just jams your front knee past your toes.', 'Tip: Do the same number of reps on each side and start with the weaker leg, since a machine-guided split squat hides a side-to-side difference that a free bar would expose.']::text[]),
  ('Smith Machine Squat', 'Smith Machine Squat', 'machine', 'repdb-smith-machine-squat.webp', 'repdb-smith-machine-squat-end.webp', ARRAY['Set the Smith machine bar at shoulder height and step under it.', 'Position the bar across your upper traps and unrack it.', 'Stand with feet shoulder-width apart, slightly forward of the bar.', 'Descend until your thighs are parallel to the floor.', 'Drive through your heels to return to standing.', 'Repeat for the desired number of reps.', 'Tip: Keep your knees tracking in line with your toes.', 'Tip: Brace your core and keep your chest up throughout the movement.', 'Tip: Set the safety stops just below your lowest squat depth.']::text[]),
  ('Sumo Dumbbell Squat', 'Dumbbell Sumo Squat', 'dumbbell', 'repdb-db-sumo-squat.webp', 'repdb-db-sumo-squat-end.webp', ARRAY['Stand with feet wider than shoulder-width, toes turned out about 30 degrees.', 'Hold one dumbbell vertically by its top end with both hands, letting it hang between your legs.', 'Brace the core and keep the chest up.', 'Bend at the hips and knees to sit straight down into a deep squat.', 'Drive through the heels to return to standing.', 'Repeat for the desired number of reps.', 'Tip: Track the knees over the toes — do not let them cave in.', 'Tip: Keep the torso as upright as the hip mobility allows.', 'Tip: Let the dumbbell hang straight down; it should not touch the floor at the bottom.']::text[]),
  ('Walking Lunge', 'Dumbbell Lunge', 'dumbbell', 'repdb-db-lunge.webp', 'repdb-db-lunge-end.webp', ARRAY['Stand holding dumbbells at your sides.', 'Step forward with one foot and lower your back knee toward the floor.', 'Push off the front foot to return.', 'Alternate legs.', 'Repeat.', 'Tip: Keep your torso upright.', 'Tip: Front knee should track over your toes.']::text[]),
  ('Zercher Squat', 'Zercher Squat', 'barbell', 'repdb-zercher-squat.webp', 'repdb-zercher-squat-end.webp', ARRAY['Set a barbell in a rack at about waist height, step in and hook it into the crooks of the elbows, with the forearms crossed or the hands clasped in front of the chest.', 'Lift the bar out of the rack, step back and stand with the feet about shoulder-width apart.', 'Brace the core and keep the chest up and the elbows pressed together.', 'Squat down by bending the hips and knees until the thighs are at least parallel to the floor.', 'Drive through the middle of the feet to stand back up.', 'Repeat for the desired number of repetitions, then re-rack the bar.', 'Tip: Wrap the bar in a pad or towel; the elbow crease is sensitive and can bruise.', 'Tip: Keep the elbows high and together so the bar does not roll toward the hands.', 'Tip: Keep the torso upright; if the chest drops, lower the load.']::text[]),
  ('Dumbbell Stiff-Leg Deadlift', 'Dumbbell Romanian Deadlift', 'dumbbell', 'repdb-dumbbell-romanian-deadlift.webp', 'repdb-dumbbell-romanian-deadlift-end.webp', ARRAY['Stand holding dumbbells in front of your thighs with a soft knee bend.', 'Hinge at the hips and push your glutes back.', 'Lower the dumbbells along your legs until you feel a hamstring stretch.', 'Keep your back flat and shoulders pulled back.', 'Drive your hips forward to return to standing.', 'Repeat for the desired number of reps.', 'Tip: Keep your knee angle constant; the movement is a hinge, not a squat.', 'Tip: Tuck your chin slightly to keep your spine in one straight line.', 'Tip: Squeeze your glutes at the top without leaning backward.']::text[]),
  ('Good Morning', 'Good Morning', 'barbell', 'repdb-good-morning.webp', 'repdb-good-morning-end.webp', ARRAY['Stand with a barbell across your upper back.', 'Hinge at the hips, pushing them back while keeping your back flat.', 'Lower your torso until it''s nearly parallel to the floor.', 'Drive your hips forward to return to standing.', 'Repeat.', 'Tip: Start with a light bar and master the hinge first.', 'Tip: Keep a soft bend in your knees throughout.', 'Tip: Stop the descent if your lower back starts to round.']::text[]),
  ('Kettlebell Swing', 'Kettlebell Swing', 'kettlebell', 'repdb-kettlebell-swing.webp', 'repdb-kettlebell-swing-end.webp', ARRAY['Stand with feet shoulder-width apart, kettlebell on the floor in front.', 'Hinge at the hips, grip the kettlebell, and hike it back between your legs.', 'Explosively drive your hips forward to swing the kettlebell to chest height.', 'Let the kettlebell swing back between your legs.', 'Repeat in a fluid motion.', 'Tip: Power the swing with your hips, not your arms or shoulders.', 'Tip: Treat it as a hinge, not a squat, with minimal knee bend.', 'Tip: Finish each rep standing tall with glutes squeezed and core tight.']::text[]),
  ('Lying Leg Curl', 'Lying Leg Curl', 'machine', 'repdb-leg-curl.webp', 'repdb-leg-curl-end.webp', ARRAY['Lie face down on the leg curl machine with ankles under the pad.', 'Curl your heels toward your glutes.', 'Squeeze your hamstrings at the top.', 'Lower with control.', 'Repeat.', 'Tip: Keep your hips pressed into the bench throughout the set.', 'Tip: Avoid jerking the weight up with your lower back.', 'Tip: Use a full range of motion without letting the stack slam down.']::text[]),
  ('Nordic Hamstring Curl', 'Nordic Hamstring Curl', 'machine', 'repdb-nordic-hamstring-curl.webp', 'repdb-nordic-hamstring-curl-end.webp', ARRAY['Kneel on a pad with your ankles anchored under a fixed support.', 'Keep your torso upright and your hips extended.', 'Slowly lower your body forward by resisting with your hamstrings.', 'Catch yourself with your hands just before hitting the floor.', 'Push back up and pull yourself to the starting position.', 'Repeat for the desired number of reps.', 'Tip: Lower as slowly as possible — the eccentric is the point.', 'Tip: Keep your hips extended; do not fold at the waist.', 'Tip: Catch yourself with your hands and push off lightly while building strength.']::text[]),
  ('Power Clean', 'Clean', 'barbell', 'repdb-clean.webp', 'repdb-clean-end.webp', ARRAY['Stand over a loaded barbell with feet hip-width apart.', 'Grip the bar just outside your knees with an overhand grip.', 'Drive explosively through your legs and extend your hips.', 'Pull yourself under the bar and catch it on your front deltoids.', 'Stand fully upright to complete the lift.', 'Tip: Keep the bar close to your body as it travels up.', 'Tip: Finish your leg drive fully before pulling under the bar.', 'Tip: Catch with your elbows high so the bar rests on your shoulders.']::text[]),
  ('Power Snatch', 'Snatch', 'barbell', 'repdb-snatch.webp', 'repdb-snatch-end.webp', ARRAY['Stand with feet hip-width apart and grip the bar wide.', 'Hinge down, keeping your back flat and chest up.', 'Explosively extend hips, knees, and ankles to drive the bar up.', 'Pull yourself under the bar into an overhead squat.', 'Stand up with the bar locked out overhead.', 'Return the bar to the floor and repeat.', 'Tip: Keep the bar close to your body as it travels up.', 'Tip: Extend your hips fully before pulling under the bar.', 'Tip: Lock your arms out and stabilize before standing up.']::text[]),
  ('Romanian Deadlift', 'Romanian Deadlift', 'barbell', 'repdb-romanian-deadlift.webp', 'repdb-romanian-deadlift-end.webp', ARRAY['Stand holding a barbell at hip level with an overhand grip.', 'Hinge at the hips, pushing them back while keeping legs nearly straight.', 'Lower the bar along your legs until you feel a hamstring stretch.', 'Drive your hips forward to return to standing.', 'Repeat.', 'Tip: Keep your spine neutral and avoid rounding the lower back.', 'Tip: Maintain the same slight knee bend for the entire rep.', 'Tip: Go only as deep as your hamstring flexibility allows.']::text[]),
  ('Seated Leg Curl', 'Seated Leg Curl', 'machine', 'repdb-seated-leg-curl.webp', 'repdb-seated-leg-curl-end.webp', ARRAY['Adjust the seat back and ankle pad so your knees align with the machine''s pivot point.', 'Sit upright, place the backs of your ankles on top of the pad, and grip the handles.', 'Curl your lower legs down and back under the seat as far as the machine allows.', 'Pause at peak contraction, then return the weight slowly to the starting position.', 'Repeat for the desired reps.', 'Tip: Keep your back firmly against the backrest throughout the movement.', 'Tip: Point toes slightly toward your shins at peak contraction to increase hamstring activation.', 'Tip: Control the eccentric phase — do not let the weight pull your legs back quickly.']::text[]),
  ('Single-Leg Kettlebell Deadlift', 'Kettlebell Single Leg Deadlift', 'kettlebell', 'repdb-kettlebell-single-leg-deadlift.webp', 'repdb-kettlebell-single-leg-deadlift-end.webp', ARRAY['Hold a kettlebell in one hand and stand on the opposite leg.', 'Hinge at the hip and lower the kettlebell toward the floor.', 'Extend your free leg straight back for balance.', 'Lower until your torso is parallel to the floor.', 'Drive through your standing heel to return to standing.', 'Complete reps on one side, then switch.', 'Tip: Keep your hips square to the floor as you hinge.', 'Tip: Keep a soft bend in your standing knee.', 'Tip: Fix your eyes on one spot to steady your balance.']::text[]),
  ('Smith Machine Stiff-Leg Deadlift', 'Smith Machine Romanian Deadlift', 'machine', 'repdb-smith-machine-rdl.webp', 'repdb-smith-machine-rdl-end.webp', ARRAY['Set the Smith machine bar at mid-thigh height and stand facing it, feet hip-width, close enough that the bar touches your thighs.', 'Unrack the bar with an overhand grip just outside the hips.', 'Push the hips back while letting the bar slide down the front of the legs.', 'Go until you feel a deep hamstring stretch, with a flat back and a soft knee bend.', 'Drive the hips forward to return to standing, keeping the bar close to the body.', 'Repeat for the recommended number of repetitions.', 'Tip: The bar is locked to a straight path — use that to groove the hinge pattern.', 'Tip: Do not round the lower back at the bottom; stop at the end of your hamstring range.']::text[]),
  ('Stiff-Leg Deadlift', 'Stiff Leg Deadlift', 'barbell', 'repdb-stiff-leg-deadlift.webp', 'repdb-stiff-leg-deadlift-end.webp', ARRAY['Stand with feet hip-width apart and hinge at the hips, legs nearly straight, holding a barbell low in front of your shins with a flat back.', 'Keep your legs nearly straight with only a slight knee bend throughout.', 'Drive the hips forward and stand upright, the bar travelling along your legs.', 'Hinge at the hips again and lower the bar along your legs.', 'Go as low as your hamstring flexibility allows with a flat back.', 'Repeat for the desired number of reps.', 'Tip: Push your hips back and keep the bar close to your legs.', 'Tip: Go only as deep as a flat back allows.', 'Tip: Feel the hamstrings load in the stretch, then drive the hips forward to stand.']::text[]),
  ('Barbell Glute Bridge', 'Barbell Glute Bridge', 'barbell', 'repdb-barbell-glute-bridge.webp', 'repdb-barbell-glute-bridge-end.webp', ARRAY['Lie on the floor with a barbell across your hips and knees bent.', 'Drive your hips up by squeezing your glutes.', 'Hold at the top with hips fully extended.', 'Lower with control.', 'Repeat.', 'Tip: Drive through your heels rather than your toes.', 'Tip: Finish with your ribs down to avoid arching the lower back.', 'Tip: Keep your knees in line with your feet, not caving inward.']::text[]),
  ('Cable Kickback', 'Cable Glute Kickback', 'cable', 'repdb-cable-kickback.webp', 'repdb-cable-kickback-end.webp', ARRAY['Attach an ankle cuff to a low cable pulley and fasten it around one ankle.', 'Stand facing the machine, holding the frame lightly for balance, and hinge slightly forward at the hips.', 'Kick the cuffed leg straight back, extending the hip fully while keeping the knee nearly straight.', 'Squeeze the glute at full hip extension, then return the foot slowly to the start.', 'Complete all reps on one side before switching.', 'Tip: Lead with the heel to maximize glute activation over hamstrings.', 'Tip: Keep the hips square; avoid rotating the pelvis as the leg kicks back.', 'Tip: The movement comes entirely from the hip — keep the back and torso still.']::text[]),
  ('Cable Pull Through', 'Cable Pull-Through', 'cable', 'repdb-cable-pull-through.webp', 'repdb-cable-pull-through-end.webp', ARRAY['Attach a rope to the low pulley and stand facing away from the machine with the rope between the legs.', 'Step forward until the cable is taut, then brace the trunk and soften the knees.', 'Push the hips back while keeping the spine neutral and the arms long.', 'Drive the hips forward and squeeze the glutes to stand tall.', 'Reverse into the next hinge without letting the weight stack slam down.', 'Tip: Think hips back and hips through; the arms only hold the rope.', 'Tip: Keep the shins nearly vertical so the movement stays a hinge rather than a squat.', 'Tip: Finish tall without leaning backwards at lockout.']::text[]),
  ('Glute Bridge', 'Glute Bridge', 'bodyweight', 'repdb-glute-bridge.webp', 'repdb-glute-bridge-end.webp', ARRAY['Lie on your back with knees bent and feet flat on the floor.', 'Drive your hips up by squeezing your glutes.', 'Hold briefly at the top with hips fully extended.', 'Lower your hips back down with control.', 'Repeat.', 'Tip: Push through your heels rather than your toes.', 'Tip: Avoid arching your lower back at the top.', 'Tip: Don''t let your knees cave inward as you lift.']::text[]),
  ('Glute Kickback', 'Glute Kickback', 'bodyweight', 'repdb-glute-kickback.webp', 'repdb-glute-kickback-end.webp', ARRAY['Begin on all fours with hands under shoulders and knees under hips.', 'Keeping the knee bent at 90 degrees, drive one heel toward the ceiling.', 'Squeeze the glute at the top of the movement.', 'Lower the leg back to the starting position with control.', 'Complete all reps, then switch sides.', 'Tip: Keep your hips square to the floor — avoid rotating.', 'Tip: Focus on squeezing the glute, not just lifting the leg.', 'Tip: Add a resistance band or cable for progressive overload.']::text[]),
  ('Hip Abduction', 'Machine Hip Abduction', 'machine', 'repdb-hip-abduction.webp', 'repdb-hip-abduction-end.webp', ARRAY['Sit in the hip abduction machine with pads against your outer thighs.', 'Push your legs apart against the resistance.', 'Hold briefly at the widest point.', 'Return to the starting position with control.', 'Repeat.', 'Tip: Sit tall and keep your back against the pad.', 'Tip: Don''t let the weight stack slam down between reps.', 'Tip: Choose a resistance that allows a full range of motion.']::text[]),
  ('Hip Adduction', 'Hip Adduction', 'machine', 'repdb-hip-adduction.webp', 'repdb-hip-adduction-end.webp', ARRAY['Sit on the hip adduction machine with your back against the pad.', 'Place your legs against the pads with the machine set to a comfortable stretch.', 'Squeeze your legs together until the pads meet in the middle.', 'Hold the squeeze briefly in the fully closed position.', 'Let your legs open back out under control to the start.', 'Repeat for the desired number of reps.', 'Tip: Choose a start width that stretches without straining your groin.', 'Tip: Move through the whole range at an even, controlled speed.', 'Tip: Do not let the weight stack slam down as your legs open back out.']::text[]),
  ('Hip Thrust', 'Barbell Hip Thrust', 'barbell', 'repdb-hip-thrust.webp', 'repdb-hip-thrust-end.webp', ARRAY['Sit on the floor with your upper back against a bench, barbell across your hips.', 'Drive your hips up until your thighs are parallel to the floor.', 'Squeeze your glutes at the top.', 'Lower your hips back down with control.', 'Repeat.', 'Tip: Tuck your chin and keep your ribs down at the top.', 'Tip: Finish with your shins vertical, driving through your heels.', 'Tip: Reach full hip extension without arching your lower back.']::text[]),
  ('Single-Leg Glute Bridge', 'Single Leg Glute Bridge', 'bodyweight', 'repdb-single-leg-glute-bridge.webp', 'repdb-single-leg-glute-bridge-end.webp', ARRAY['Lie on your back with one knee bent, foot flat, the other leg extended straight.', 'Brace the core and squeeze the glute on the working side.', 'Drive the hips up by pressing through the working heel.', 'Pause at the top with the body in a straight line from shoulders to knee.', 'Lower under control. Complete reps per side, then switch.', 'Tip: Keep the extended leg in line with the working thigh.', 'Tip: Squeeze the glute hard at the top — do not push with the lower back.', 'Tip: Slow the lowering phase for more stimulus.']::text[]),
  ('Barbell Calf Raise', 'Barbell Calf Raise', 'barbell', 'repdb-barbell-calf-raise.webp', 'repdb-barbell-calf-raise-end.webp', ARRAY['Place a barbell across your upper back as in a squat.', 'Stand with the balls of your feet on a raised platform.', 'Push up onto your toes as high as possible.', 'Pause and squeeze your calves at the top.', 'Lower your heels below the platform and repeat.', 'Tip: Avoid bouncing out of the bottom stretch position.', 'Tip: Keep your knees straight but not locked throughout the set.', 'Tip: Move slowly to stay balanced under the bar.']::text[]),
  ('Donkey Calf Raise', 'Donkey Calf Raise', 'bodyweight', 'repdb-donkey-calf-raise.webp', 'repdb-donkey-calf-raise-end.webp', ARRAY['Bend at the hips and place your hands on the floor in front of you, hips high and legs nearly straight.', 'Set your feet hip-width apart with your weight on the balls of the feet.', 'Lower your heels as far as they go (below the edge if you stand on a raised platform) for a full stretch.', 'Drive up onto the toes as high as possible, squeezing the calves.', 'Lower under control to a deep stretch.', 'Tip: Pause briefly at the top to maximize the contraction.', 'Tip: Use a slow eccentric for full stretch.', 'Tip: Add a partner or weight on the lower back for resistance.']::text[]),
  ('Dumbbell Calf Raise', 'Dumbbell Calf Raise', 'dumbbell', 'repdb-dumbbell-calf-raise.webp', 'repdb-dumbbell-calf-raise-end.webp', ARRAY['Stand holding a dumbbell in each hand at your sides.', 'Set your feet flat on the floor, or place the balls of your feet on a raised surface with heels hanging off for a deeper stretch.', 'Press through the balls of your feet to raise your heels as high as possible.', 'Squeeze your calves at the top of the movement.', 'Lower your heels back to the floor (or below the platform) to stretch the calves.', 'Repeat for the desired number of reps.', 'Tip: Avoid bouncing out of the bottom stretch position.', 'Tip: Keep your legs straight but not locked throughout.', 'Tip: Prevent your ankles from rolling outward as you rise.']::text[]),
  ('Seated Calf Raise', 'Seated Calf Raise', 'machine', 'repdb-seated-calf-raise.webp', 'repdb-seated-calf-raise-end.webp', ARRAY['Sit at a calf raise machine with the pads resting on your thighs.', 'Lower your heels as far as possible.', 'Raise up onto your toes.', 'Lower under control.', 'Repeat.', 'Tip: The bent knee slackens the gastrocnemius, so the soleus does more of the work.', 'Tip: Use a full range of motion.']::text[]),
  ('Smith Machine Calf Raise', 'Smith Machine Calf Raise', 'machine', 'repdb-smith-machine-calf-raise.webp', 'repdb-smith-machine-calf-raise-end.webp', ARRAY['Stand in the Smith machine with your back to the bar, set just below hip height.', 'Reach back and grip the bar behind your thighs with both hands, arms straight.', 'Unrack the bar and raise up onto the balls of your feet.', 'Squeeze your calves hard at the top.', 'Lower your heels to the floor under control (below the edge if you stand on a low platform).', 'Repeat for the desired number of reps.', 'Tip: Avoid bouncing out of the bottom stretch position.', 'Tip: Keep your knees straight but not forcefully locked.', 'Tip: Use a slow tempo through the full range rather than pumping short reps.']::text[]),
  ('Standing Calf Raise', 'Standing Calf Raise', 'machine', 'repdb-standing-calf-raise.webp', 'repdb-standing-calf-raise-end.webp', ARRAY['Stand on the edge of a platform or calf raise machine.', 'Lower heels below the platform.', 'Push up onto your toes.', 'Lower slowly.', 'Repeat.', 'Tip: Pause at the top to maximize contraction.', 'Tip: Full heel drop increases range of motion.']::text[]),
  ('Ab Crunch Machine', 'Machine Seated Crunch', 'machine', 'repdb-machine-seated-crunch.webp', 'repdb-machine-seated-crunch-end.webp', ARRAY['Sit in the abdominal crunch machine and grip the handles.', 'Position the chest pad against your upper body.', 'Contract your abs to crunch your torso forward and down.', 'Squeeze at the bottom of the movement.', 'Return to the starting position with control.', 'Repeat for the desired number of reps.', 'Tip: Initiate the movement with your abs, not your arms.', 'Tip: Exhale as you crunch forward.', 'Tip: Avoid using momentum by rocking your body.']::text[]),
  ('Ab Wheel Rollout', 'Ab Wheel Rollout', 'bodyweight', 'repdb-ab-wheel-rollout.webp', 'repdb-ab-wheel-rollout-end.webp', ARRAY['Kneel on the floor and grip the ab wheel handles shoulder-width.', 'Brace the core hard so the lower back stays neutral.', 'Roll the wheel slowly forward, extending the body as far as you can control.', 'Stop before the hips sag or the back arches.', 'Pull the wheel back to the knees by contracting the abs.', 'Tip: Brace the core before each rep — do not let the lower back arch.', 'Tip: Build range gradually, stopping short of any hip sag.', 'Tip: Drop to a wall stop if you cannot control the bottom.']::text[]),
  ('Barbell Rollout', 'Barbell Ab Rollout', 'barbell', 'repdb-barbell-ab-rollout.webp', 'repdb-barbell-ab-rollout-end.webp', ARRAY['Load plates of equal size on both ends of a barbell and place it on the floor.', 'Kneel behind the bar and grip it shoulder-width, arms extended.', 'Brace the core hard, then roll the bar forward away from your body.', 'Go as far as you can keep a neutral spine — stop before the hips sag.', 'Pull the bar back to the starting position by contracting the abs and lats.', 'Repeat for the recommended number of repetitions.', 'Tip: Start with small plates for a limited range; graduate to 45s for full rollouts.', 'Tip: The moment the lower back arches or drops, stop — you''ve exceeded your range.']::text[]),
  ('Bicycle Crunch', 'Bicycle Crunch', 'bodyweight', 'repdb-bicycle-crunch.webp', 'repdb-bicycle-crunch-end.webp', ARRAY['Lie on your back with hands behind your head and legs raised.', 'Bring one knee toward your chest while rotating your torso to meet it with the opposite elbow.', 'Extend that leg while bringing the other knee in.', 'Continue alternating in a pedaling motion.', 'Repeat.', 'Tip: Avoid pulling on your neck with your hands.', 'Tip: Lead the rotation with your shoulder, not your elbow.', 'Tip: Move slowly and deliberately rather than racing through reps.']::text[]),
  ('Cable Crunch', 'Cable Crunch', 'cable', 'repdb-cable-crunch.webp', 'repdb-cable-crunch-end.webp', ARRAY['Kneel in front of a cable machine with a rope attachment at the top.', 'Hold the rope near your forehead with elbows bent.', 'Crunch down by flexing your spine and bringing your elbows to your thighs.', 'Squeeze your abs hard at the bottom.', 'Return to the start position and repeat.', 'Tip: Avoid pulling the rope down with your arms.', 'Tip: Keep your hips fixed so movement comes from the spine.', 'Tip: Exhale fully as you crunch down.']::text[]),
  ('Captain''s Chair Knee Raise', 'Captain''s Chair Knee Raise', 'bodyweight', 'repdb-captains-chair-knee-raise.webp', 'repdb-captains-chair-knee-raise-end.webp', ARRAY['Position yourself in the captain''s chair with your back flat against the pad and forearms on the armrests.', 'Let your legs hang straight down.', 'Engage your core and raise your knees toward your chest.', 'Hold briefly at the top, then lower slowly to the starting position.', 'Repeat for the desired reps.', 'Tip: Avoid swinging the legs for momentum.', 'Tip: Exhale as you raise your knees.', 'Tip: Keep your back pressed against the pad throughout.']::text[]),
  ('Crunch', 'Crunches', 'bodyweight', 'repdb-crunches.webp', 'repdb-crunches-end.webp', ARRAY['Lie on your back with knees bent and hands behind your head.', 'Curl your upper body toward your knees, lifting your shoulder blades off the floor.', 'Squeeze your abs at the top.', 'Lower with control.', 'Repeat.', 'Tip: Avoid pulling on your neck with your hands.', 'Tip: Exhale as you curl up and inhale on the way down.', 'Tip: Keep your lower back pressed into the floor throughout.']::text[]),
  ('Dead Bug', 'Dead Bug', 'bodyweight', 'repdb-dead-bug.webp', 'repdb-dead-bug-end.webp', ARRAY['Lie on your back with arms extended toward the ceiling and knees at 90 degrees.', 'Lower your right arm and left leg toward the floor while keeping the lower back pressed down.', 'Return to start.', 'Repeat on the other side.', 'Alternate.', 'Tip: Press your lower back into the floor at all times.', 'Tip: Move slowly.']::text[]),
  ('Decline Crunch', 'Decline Crunch', 'bodyweight', 'repdb-decline-crunch.webp', 'repdb-decline-crunch-end.webp', ARRAY['Secure your feet at the top of a decline bench.', 'Lie back with hands crossed on your chest or behind your head.', 'Crunch up by flexing your spine toward your knees.', 'Squeeze your abs at the top.', 'Lower under control and repeat.', 'Tip: Curl your spine up rather than pulling on your neck.', 'Tip: Exhale as you crunch and squeeze the abs at the top.', 'Tip: Lower slowly instead of dropping back to the bench.']::text[]),
  ('Dumbbell Side Bend', 'Dumbbell Side Bend', 'dumbbell', 'repdb-dumbbell-side-bend.webp', 'repdb-dumbbell-side-bend-end.webp', ARRAY['Stand upright holding a dumbbell in one hand at your side.', 'Keep the opposite hand on your hip or behind your head.', 'Bend laterally toward the dumbbell side, lowering it along your thigh.', 'Return to upright, then bend to the opposite side using only your obliques.', 'Complete all reps per side.', 'Tip: Avoid leaning forward or backward — move strictly sideways.', 'Tip: Use a controlled tempo in both directions.', 'Tip: Keep the weight close to your leg throughout.']::text[]),
  ('Flutter Kicks', 'Flutter Kicks', 'bodyweight', 'repdb-flutter-kicks.webp', 'repdb-flutter-kicks-end.webp', ARRAY['Lie flat on your back with your legs extended.', 'Place your hands under your glutes for support.', 'Lift both legs a few inches off the floor.', 'Alternate kicking your legs up and down in a small range.', 'Keep your core braced and lower back pressed down.', 'Continue for the desired duration or reps.', 'Tip: Press your lower back into the floor for the whole set.', 'Tip: Keep the kicks small and steady rather than big and wild.', 'Tip: Raise your legs higher if you feel your lower back arching.']::text[]),
  ('Hanging Leg Raise', 'Hanging Leg Raise', 'bodyweight', 'repdb-hanging-leg-raise.webp', 'repdb-hanging-leg-raise-end.webp', ARRAY['Hang from a pull-up bar with an overhand grip.', 'Raise your legs in front of you until they are parallel to the floor.', 'Hold briefly, then lower with control.', 'Avoid swinging.', 'Repeat.', 'Tip: Curl your pelvis up at the top to fully engage your abs.', 'Tip: Keep your shoulders engaged rather than hanging passively.', 'Tip: Bend your knees to make the movement easier if needed.']::text[]),
  ('Kettlebell Windmill', 'Kettlebell Windmills', 'kettlebell', 'repdb-kettlebell-windmills.webp', 'repdb-kettlebell-windmills-end.webp', ARRAY['Stand holding a kettlebell locked out overhead in one hand.', 'Turn your feet about 45 degrees away from the working arm.', 'Keeping the kettlebell up, hinge at the hips sideways.', 'Reach your opposite hand down toward your foot.', 'Drive your hips back to stand up tall.', 'Complete reps on one side, then switch.', 'Tip: Keep your eyes on the kettlebell throughout the movement.', 'Tip: Push your hips out to the side instead of rounding your spine.', 'Tip: Start light until the hinge pattern feels stable and controlled.']::text[]),
  ('Lying Leg Raise', 'Lying Leg Raise', 'bodyweight', 'repdb-lying-leg-raise.webp', 'repdb-lying-leg-raise-end.webp', ARRAY['Lie flat on your back with legs straight and hands under your lower back or gripping a stable surface behind your head.', 'Keeping your legs together and core braced, raise them to vertical (or as high as flexibility allows).', 'Pause briefly at the top.', 'Lower your legs slowly toward the floor without letting them touch.', 'Repeat for the desired reps.', 'Tip: Press your lower back into the floor throughout to protect the lumbar spine.', 'Tip: Avoid swinging — control the descent to maximize tension.', 'Tip: Bend the knees slightly if hamstring flexibility is a limiting factor.']::text[]),
  ('Medicine Ball Slam', 'Medicine Ball Slam', 'other', 'repdb-medicine-ball-slam.webp', 'repdb-medicine-ball-slam-end.webp', ARRAY['Stand with feet shoulder-width apart, holding a slam ball in front of your hips.', 'Lift the ball overhead by extending the hips and reaching tall.', 'Forcefully slam the ball into the floor between your feet, crunching through the core.', 'Catch the ball on the bounce or pick it up from the floor.', 'Repeat for the recommended number of repetitions.', 'Tip: Use a dead-bounce slam ball, not a traditional medicine ball — regular balls will bounce back into your face.', 'Tip: Finish with the whole body — it is a full swing, not just an arm throw.']::text[]),
  ('Mountain Climber', 'Mountain Climbers', 'bodyweight', 'repdb-mountain-climbers.webp', 'repdb-mountain-climbers-end.webp', ARRAY['Start in a high plank position.', 'Drive one knee toward your chest.', 'Quickly switch legs, driving the other knee forward.', 'Continue alternating at a brisk pace.', 'Repeat.', 'Tip: Keep your hips level and low rather than piking upward.', 'Tip: Keep your shoulders stacked directly over your wrists.', 'Tip: Maintain a steady breathing rhythm as the pace increases.']::text[]),
  ('Pallof Press', 'Cable Pallof Press', 'cable', 'repdb-cable-pallof-press.webp', 'repdb-cable-pallof-press-end.webp', ARRAY['Set a cable at chest height and take the handle in both hands, standing side-on to the machine.', 'Step away until there is real tension on the cable, with your feet about shoulder-width apart and knees softly bent.', 'Bring the handle to the centre of your chest and brace your trunk and glutes.', 'Press the handle straight out in front of you until your arms are extended, resisting the pull that wants to rotate you toward the machine.', 'Hold the extended position for a moment, then bring the handle back to your chest under control.', 'Complete the desired reps, then turn around and repeat facing the other way.', 'Tip: Nothing should rotate. If your shoulders turn toward the cable as you press, reduce the weight — the point is the rotation that does not happen.', 'Tip: The further you step from the machine, the longer the lever and the harder it gets, so you can change difficulty without touching the weight stack.', 'Tip: Keep your arms level with your chest and your shoulders down; letting the handle drift up turns it into a front raise.']::text[]),
  ('Plank', 'Plank', 'bodyweight', 'repdb-plank.webp', null, ARRAY['Place your forearms on the floor with elbows under your shoulders.', 'Extend your legs back and rise onto your toes.', 'Keep your body in a straight line from head to heels.', 'Brace your core and squeeze your glutes.', 'Hold the position for the desired duration.', 'Lower your knees to exit the hold.', 'Tip: Do not let your hips sag or pike up.', 'Tip: Squeeze your glutes and quads.']::text[]),
  ('Reverse Crunch', 'Reverse Crunches', 'bodyweight', 'repdb-reverse-crunches.webp', 'repdb-reverse-crunches-end.webp', ARRAY['Lie on your back with your arms at your sides.', 'Raise your legs with knees bent to 90 degrees.', 'Curl your hips off the floor by contracting your lower abs.', 'Bring your knees toward your chest.', 'Lower your hips with control.', 'Repeat for the desired number of reps.', 'Tip: Curl your pelvis rather than swinging your legs for momentum.', 'Tip: Exhale as your hips lift to deepen the abdominal contraction.', 'Tip: Press your arms into the floor for added stability.']::text[]),
  ('Russian Twist', 'Russian Twist', 'bodyweight', 'repdb-russian-twist.webp', 'repdb-russian-twist-end.webp', ARRAY['Sit on the floor with knees bent, lean back slightly.', 'Hold your hands together or hold a weight at chest level.', 'Rotate your torso to one side, then the other.', 'Keep your core braced throughout.', 'Repeat.', 'Tip: Rotate from the torso rather than just swinging the arms.', 'Tip: Keep your chest lifted and your spine long as you twist.', 'Tip: Move at a controlled tempo instead of racing through reps.']::text[]),
  ('Side Plank', 'Side Plank', 'bodyweight', 'repdb-side-plank.webp', null, ARRAY['Lie on your side with your forearm on the floor, elbow under your shoulder.', 'Lift your hips off the floor, forming a straight line from head to feet.', 'Hold the position, keeping your core tight.', 'Breathe steadily.', 'Repeat on both sides.', 'Tip: Don''t let your top shoulder roll forward during the hold.', 'Tip: Push the floor away through the forearm rather than sinking into the shoulder.', 'Tip: Keep your head in line with your spine.']::text[]),
  ('Sit Up', 'Sit-Ups', 'bodyweight', 'repdb-sit-ups.webp', 'repdb-sit-ups-end.webp', ARRAY['Lie on your back with knees bent and feet anchored.', 'Cross your arms over your chest or place hands behind your head.', 'Sit all the way up until your torso is upright.', 'Lower back down with control.', 'Repeat.', 'Tip: Avoid pulling on your neck when your hands are behind your head.', 'Tip: Roll up through the spine rather than jerking with momentum.', 'Tip: Exhale on the way up to reinforce the abdominal contraction.']::text[]),
  ('Battle Ropes', 'Battle Ropes', 'other', 'repdb-battle-ropes.webp', null, ARRAY['Anchor the ropes to a fixed point and grab one end in each hand.', 'Step back so the ropes have moderate slack.', 'Drop into a quarter squat with feet shoulder-width.', 'Drive each arm up and down rapidly to send waves through the ropes.', 'Continue for the prescribed work interval.', 'Tip: Stay in the quarter-squat the entire interval.', 'Tip: Drive force from the legs and hips, not just the arms.', 'Tip: Keep the waves consistent and tight.']::text[]),
  ('Elliptical', 'Elliptical Trainer', 'machine', 'repdb-elliptical-trainer.webp', null, ARRAY['Step onto the foot plates one at a time, holding the fixed centre post until you are steady, then take a moving handle in each hand.', 'Start the pedals turning forward, keeping your whole foot down on the plate rather than lifting your heel.', 'Push one handle away as the opposite foot travels forward, and pull the other back, so the arms and legs work in opposition.', 'Stand tall with your hips over the pedals and your core braced instead of hanging back on the handles.', 'Set the resistance and ramp so you can hold a smooth stride, and continue for the desired time or distance.', 'Tip: Drive the handles rather than letting the legs push them for you — the arm work is most of what makes the elliptical a full-body machine.', 'Tip: Keep your heels down on the plates. Riding on the toes cramps the calves and cuts the glutes out of the stride.', 'Tip: Pedalling backwards for part of the session shifts the emphasis toward the hamstrings and glutes and breaks up a long steady effort.']::text[]),
  ('Jump Rope', 'Jump Rope', 'other', 'repdb-jump-rope.webp', null, ARRAY['Hold a jump rope handle in each hand with the rope behind you.', 'Swing the rope overhead and forward in a smooth arc.', 'Hop just high enough for the rope to pass under your feet.', 'Land softly on the balls of the feet, knees slightly bent.', 'Keep a steady rhythm for the prescribed interval.', 'Tip: Use the wrists to spin the rope, not the shoulders.', 'Tip: Hop low — only an inch or two off the floor.', 'Tip: Stay tall with elbows close to the sides.']::text[]),
  ('Outdoor Cycling', 'Cycling', 'other', 'repdb-cycling.webp', null, ARRAY['Adjust the saddle so your knee is only slightly bent when the pedal is at the bottom of the stroke.', 'Sit on the saddle with your hands on the handlebars, elbows slightly bent and shoulders relaxed.', 'Place the balls of your feet over the pedal axles.', 'Push each pedal down and forward, then let it come up and over the top in a smooth circle.', 'Keep a steady cadence and choose a gear that lets you pedal without bouncing on the saddle.', 'Ride for the planned time or distance, easing the pace for the last few minutes to cool down.', 'Tip: Keep your knees tracking in line with your feet; knees that fall in or out usually mean the saddle or cleats need adjusting.', 'Tip: A higher cadence in an easier gear is kinder to the knees than grinding a hard gear slowly.', 'Tip: Keep your upper body relaxed and your back long rather than rounded or rocking from side to side.']::text[]),
  ('Rowing Machine', 'Rowing Machine', 'machine', 'repdb-rowing-machine.webp', 'repdb-rowing-machine-end.webp', ARRAY['Sit on the rower, strap your feet into the footplates and take the handle with an overhand grip.', 'Slide forward into the catch: shins vertical, torso leaning slightly ahead of the hips, arms straight out toward the flywheel.', 'Drive through your legs first, pushing the seat back until your knees are almost straight.', 'Swing your torso back past vertical, then pull the handle in to your lower ribs with your elbows travelling past your sides.', 'Reverse the order on the recovery — arms away, torso forward, then bend the knees — and slide back to the catch for the next stroke.', 'Continue for the desired time, distance or number of strokes.', 'Tip: Keep the order: legs, then body, then arms on the drive, and arms, body, legs on the recovery. Breaking the arms early wastes the strongest part of the stroke.', 'Tip: Row with a flat back and a braced core — rounding the lower back at the catch is what turns rowing into a back ache instead of conditioning.', 'Tip: Let the handle travel in a straight, level line to the lower ribs, and make the recovery about twice as slow as the drive rather than rushing back to the catch.']::text[]),
  ('Running', 'Running', 'bodyweight', 'repdb-running.webp', null, ARRAY['Start from an easy jog and build into your pace over the first few minutes rather than setting off at target speed.', 'Land with your foot under your hips, not out in front, and keep the contact with the ground short and quiet.', 'Run tall through the hips with a slight forward lean from the ankles, not a fold at the waist.', 'Bend your elbows to about ninety degrees and drive your arms forward and back, keeping them off your chest.', 'Breathe rhythmically and keep your shoulders, jaw and hands loose.', 'Hold the pace for the desired time or distance, then jog and walk for a few minutes to finish.', 'Tip: Build weekly distance gradually. Almost every running injury comes from adding volume faster than the tendons and bones adapt, not from a single hard run.', 'Tip: Most of your running should be easy enough to talk in. Running every session at a middling hard pace is the fastest way to plateau.', 'Tip: Shorten your stride and let your cadence rise if you feel yourself thudding — reaching for a longer stride puts the brakes on with every footfall.']::text[]),
  ('Stair Climber', 'Stair Climber', 'machine', 'repdb-stair-climber.webp', null, ARRAY['Step onto the bottom stair with the machine at its slowest setting and take the rails lightly for balance.', 'Climb one step at a time, placing the whole foot on each stair rather than just the toes.', 'Stand upright with your chest open and your hips under your shoulders instead of hunching over the console.', 'Push the step down through the heel of the front foot, letting the glute of that leg do the work.', 'Set the pace so you can hold your posture, and keep climbing for the desired time or number of floors.', 'Tip: Do not lean on the rails or hook your forearms over them — supporting your weight there takes the load off the legs and the readout stops meaning anything.', 'Tip: Full foot on the step, heel included. Climbing on the toes shifts the whole session into the calves and burns them out early.', 'Tip: Take one step at a time before you try skipping steps; deliberate, upright climbing beats a fast shuffle at the bottom of the staircase.']::text[]),
  ('Stationary Bike', 'Stationary Bike', 'machine', 'repdb-stationary-bike.webp', null, ARRAY['Set the saddle height so your knee stays slightly bent at the bottom of the pedal stroke, then sit down and place the balls of your feet on the pedals.', 'Take the handlebars with a relaxed grip and sit tall, with your back neutral and your shoulders down.', 'Push one pedal down and forward while the other rises, keeping the effort in your legs rather than pulling on the bars.', 'Keep pedalling in a smooth, even circle at a steady cadence, breathing in rhythm with the stroke.', 'Adjust the resistance to hold your target effort, and continue for the desired time or distance.', 'Tip: Set the saddle before you start: too low grinds the knees, too high rocks your hips side to side at the bottom of every stroke.', 'Tip: Drive with the legs and keep the upper body quiet — gripping and hauling on the bars adds nothing but neck and shoulder tension.', 'Tip: Raise the resistance rather than spinning the pedals loose and fast; a light flywheel at high cadence feels hard on the lungs but does little for the legs.']::text[]),
  ('Treadmill', 'Treadmill Running', 'machine', 'repdb-treadmill-running.webp', null, ARRAY['Step onto the treadmill with a foot on each side rail, start the belt at a walking speed and step on once it is moving.', 'Build up to your running pace, landing under your hips rather than reaching out in front of you.', 'Run tall with your shoulders relaxed, your elbows bent at about ninety degrees and your arms swinging forward and back, not across your body.', 'Keep your eyes forward and stay in the middle of the belt instead of drifting back toward the rear roller.', 'Hold the pace for the desired time or distance, then slow the belt and walk for a few minutes before stepping off.', 'Tip: Clip the safety key to your waistband — it is the only thing that stops the belt if you lose your footing.', 'Tip: Do not hold the handrails while running. Leaning on them shortens your stride, twists your posture and hides how hard you are actually working.', 'Tip: A one to two percent incline makes indoor running feel closer to running outdoors, where you have to push through air resistance.']::text[])
) as v (old_name, new_name, equipment, image_path, image_path_end, instructions)
where e.user_id is null and e.name = v.old_name and (e.image_path is null or e.image_path not like 'repdb-%');

-- 2. Built-ins RepDB doesn't cover: hidden from pickers, still shown in
--    history and routines that use them.
update exercises e set hidden = true
where e.user_id is null and (e.image_path is null or e.image_path not like 'repdb-%')
  and e.name in ('Cable Fly', 'Medicine Ball Chest Pass', 'Neutral-Grip Dumbbell Press', 'Single-Arm Cable Crossover', 'Incline Cable Fly', 'Incline Machine Press', 'Low Cable Crossover', 'Decline Machine Press', 'Chest-Supported T-Bar Row', 'Machine High Row', 'Seal Row', 'Rope Straight-Arm Pulldown', 'Single-Arm Landmine Row', 'Clean and Press', 'Plate Front Raise', 'Band Lateral Raise', 'Single-Arm Lateral Raise', 'Dumbbell External Rotation', 'Cable Shrug', 'Cable Preacher Curl', 'Overhead Cable Curl', 'Prone Incline Curl', 'Single-Arm Cable Curl', 'JM Press', 'Reverse-Grip Pushdown', 'Rope Pushdown', 'Tate Press', 'Triceps Dip', 'Reverse Wrist Curl', 'Barbell Hack Squat', 'Barbell Walking Lunge', 'Broad Jump', 'Double Kettlebell Front Squat', 'Dumbbell Step Up', 'Glute-Ham Raise', 'Kettlebell Clean', 'Reverse Hyperextension', 'Stability Ball Leg Curl', 'Standing Leg Curl', 'Monster Walk', 'Leg Press Calf Raise', 'Single-Leg Seated Calf Raise', 'Cable Woodchop', 'Landmine 180', 'Oblique Crunch', 'Standing Cable Crunch', 'Recumbent Bike', 'Star Jump');

-- 3. New built-ins from RepDB (names already taken are skipped, so this can re-run).
insert into exercises
  (user_id, name, muscle_group, equipment, kind, image_path, image_path_end, instructions)
select null::uuid, v.name, v.muscle_group, v.equipment, v.kind::exercise_kind,
       v.image_path, v.image_path_end, v.instructions
from (values
  ('Incline EZ-Bar Bench Press', 'upper-chest', 'barbell', 'weight_reps', 'repdb-incline-bench-ez-bar-press.webp', 'repdb-incline-bench-ez-bar-press-end.webp', ARRAY['Set bench to 30–45 degrees. Grip the EZ-bar with hands on the angled sections.', 'Lower the bar to your upper chest.', 'Press back up to full extension.', 'Repeat.', 'Tip: The incline shifts emphasis to the upper pectorals.', 'Tip: Control the descent to avoid shoulder strain.']::text[]),
  ('Archer Push Ups', 'mid-chest', 'bodyweight', 'bodyweight_reps', 'repdb-archer-push-ups.webp', 'repdb-archer-push-ups-end.webp', ARRAY['Set up in a wide push-up position with arms straight.', 'Lower yourself toward one hand while keeping the other arm straight.', 'Keep your core tight and body in a straight line.', 'Press back up to the start position.', 'Alternate sides each rep for the desired number of reps.', 'Tip: Keep your hips square to the floor as you shift sideways.', 'Tip: Let the straight arm assist as little as possible.', 'Tip: Start from wide push-ups and shift a little further each session.']::text[]),
  ('Clap Push-Ups', 'mid-chest', 'bodyweight', 'bodyweight_reps', 'repdb-clap-push-ups.webp', 'repdb-clap-push-ups-end.webp', ARRAY['Begin in a standard push-up position.', 'Lower your chest to the floor.', 'Explosively push up so hands leave the ground.', 'Clap your hands together and land softly, returning to start.', 'Repeat.', 'Tip: Land with soft elbows to absorb impact.', 'Tip: Ensure you have enough upper body strength before attempting.']::text[]),
  ('Close Grip Push Ups', 'mid-chest', 'bodyweight', 'bodyweight_reps', 'repdb-close-grip-push-ups.webp', 'repdb-close-grip-push-ups-end.webp', ARRAY['Assume a push-up position with hands directly under your shoulders.', 'Keep your elbows tucked close to your ribs.', 'Lower your chest toward the floor.', 'Press back up to the starting position.', 'Repeat for the desired number of reps.', 'Tip: Keep your elbows tracking backward, not flared out.', 'Tip: Maintain a rigid plank position throughout.', 'Tip: Slow the descent for greater triceps activation.']::text[]),
  ('Deficit Push Ups', 'mid-chest', 'bodyweight', 'bodyweight_reps', 'repdb-deficit-push-ups.webp', 'repdb-deficit-push-ups-end.webp', ARRAY['Place your hands on two elevated surfaces like parallettes or blocks.', 'Assume a plank position with hands under your shoulders.', 'Lower your chest below the level of your hands.', 'Press back up to extend your arms.', 'Repeat for the desired number of reps.', 'Tip: Avoid letting your hips sag during the deep stretch.', 'Tip: Work within a pain-free depth and increase it gradually.', 'Tip: Keep your elbows tracking back rather than flaring wide.']::text[]),
  ('Dumbbell Svend Press', 'mid-chest', 'dumbbell', 'weight_reps', 'repdb-db-svend-press.webp', 'repdb-db-svend-press-end.webp', ARRAY['Stand and press two dumbbells together horizontally at chest height.', 'Maintain the inward squeeze on the dumbbells throughout.', 'Press the dumbbells forward until your arms are almost straight.', 'Pull them back to the chest under control.', 'Repeat for the prescribed reps.', 'Tip: The squeeze on the dumbbells is what makes the exercise — do not let them separate.', 'Tip: Use a light load — pec activation is the goal, not load.', 'Tip: Keep the elbows slightly bent at the lockout.']::text[]),
  ('EZ-Bar Bench Press', 'mid-chest', 'barbell', 'weight_reps', 'repdb-ez-bar-bench-press.webp', 'repdb-ez-bar-bench-press-end.webp', ARRAY['Lie flat on a bench with your feet planted on the floor, gripping the EZ bar''s angled bends over your chest.', 'Unrack the bar and hold it over your lower chest with your arms extended.', 'Lower the bar under control toward your lower chest.', 'Press the bar back up to full arm extension.', 'Repeat for the desired number of reps.', 'Tip: Keep your feet flat on the floor and maintain a slight arch in your lower back for a stable base.', 'Tip: The EZ bar''s angled grip is easier on the wrists than a straight barbell.', 'Tip: Lower the bar to your lower chest and keep your elbows tucked at roughly 45 degrees to protect the shoulders.']::text[]),
  ('Floor EZ-Bar Press', 'mid-chest', 'barbell', 'weight_reps', 'repdb-floor-ez-bar-press.webp', 'repdb-floor-ez-bar-press-end.webp', ARRAY['Lie on the floor holding an EZ-bar over your chest.', 'Lower the bar until your elbows touch the floor.', 'Press back up to full extension.', 'Repeat.', 'Tip: The EZ-bar reduces wrist strain vs. a straight bar.', 'Tip: Keep your feet flat on the floor.']::text[]),
  ('Kettlebell Svend Press', 'mid-chest', 'kettlebell', 'weight_reps', 'repdb-kettlebell-svend-press.webp', 'repdb-kettlebell-svend-press-end.webp', ARRAY['Stand holding one kettlebell by the handle with both hands at chest height, the bell hanging below your hands.', 'Squeeze your hands together on the handle to tense the chest.', 'Press the kettlebell forward until your arms are almost straight.', 'Pull it back to the chest under control.', 'Repeat for the prescribed reps.', 'Tip: Keep pushing the hands toward each other on the handle throughout; without that squeeze it turns into a front-shoulder raise.', 'Tip: Use a light kettlebell — the long lever of straight arms dictates the load.', 'Tip: Keep the elbows slightly bent at the lockout.']::text[]),
  ('Knee Push Ups', 'mid-chest', 'bodyweight', 'bodyweight_reps', 'repdb-knee-push-ups.webp', 'repdb-knee-push-ups-end.webp', ARRAY['Start in a push-up position with your knees on the floor.', 'Place your hands shoulder-width apart on the ground.', 'Keep your body in a straight line from knees to shoulders.', 'Lower your chest toward the floor by bending your elbows.', 'Press through your hands to return to the starting position.', 'Repeat for the desired number of reps.', 'Tip: Squeeze your glutes to keep your hips from sagging.', 'Tip: Keep your elbows at roughly a 45-degree angle from your torso.', 'Tip: Lower with control instead of dropping your chest quickly.']::text[]),
  ('Machine Chest Fly', 'mid-chest', 'machine', 'weight_reps', 'repdb-machine-chest-fly.webp', 'repdb-machine-chest-fly-end.webp', ARRAY['Sit in the chest fly machine and adjust the seat so the handles align with your chest.', 'Grip the handles with a slight bend in your elbows.', 'Bring the handles together in front of your chest in a smooth arc.', 'Squeeze your pectorals at the point of peak contraction.', 'Return under control to the starting position without slamming the weight.', 'Repeat for the desired number of reps.', 'Tip: Keep a slight, fixed bend in your elbows throughout.', 'Tip: Focus on squeezing the chest rather than pushing with the arms.', 'Tip: Control the return instead of letting the weight stack slam.']::text[]),
  ('One Arm Kettlebell Floor Press', 'mid-chest', 'kettlebell', 'weight_reps', 'repdb-one-arm-kettlebell-floor-press.webp', 'repdb-one-arm-kettlebell-floor-press-end.webp', ARRAY['Lie flat on the floor with knees bent.', 'Hold a kettlebell at your shoulder with one hand.', 'Press the kettlebell straight up until your arm is fully extended.', 'Lower the kettlebell until your upper arm touches the floor.', 'Keep your core braced throughout.', 'Complete reps on one side, then switch.', 'Tip: Keep your forearm vertical throughout the press.', 'Tip: Tuck your elbow to roughly 45 degrees from your torso.', 'Tip: Let your upper arm touch down gently rather than bouncing off the floor.']::text[]),
  ('Paused Bench Press', 'mid-chest', 'barbell', 'weight_reps', 'repdb-paused-bench-press.webp', 'repdb-paused-bench-press-end.webp', ARRAY['Lie on a flat bench and grip the barbell slightly wider than shoulder-width.', 'Unrack the bar and lower it to your chest.', 'Pause on your chest for 1-2 seconds.', 'Press the bar back up until your arms are fully extended.', 'Control the descent on every rep.', 'Repeat for the desired number of reps.', 'Tip: Stay tight during the pause instead of letting the bar sink.', 'Tip: Keep your shoulder blades pinched and your feet planted throughout.', 'Tip: Touch the bar to the same spot on your chest every rep.']::text[]),
  ('Ring Push-Up', 'mid-chest', 'bodyweight', 'bodyweight_reps', 'repdb-ring-push-up.webp', 'repdb-ring-push-up-end.webp', ARRAY['Set the rings just above floor height.', 'Grip the rings and assume a plank position with arms straight.', 'Lower the chest toward the rings, keeping the elbows close to the body.', 'Press back up to full arm extension.', 'Repeat for the prescribed reps.', 'Tip: Keep the rings turned out at the top to engage the chest.', 'Tip: Brace the core — the rings will magnify any wobble.', 'Tip: Drop to knees to scale the difficulty.']::text[]),
  ('Single Dumbbell Svend Press', 'mid-chest', 'dumbbell', 'weight_reps', 'repdb-single-db-svend-press.webp', 'repdb-single-db-svend-press-end.webp', ARRAY['Stand tall and hold a single dumbbell upright in front of your sternum, the handle running vertically between your flat palms.', 'Squeeze your palms hard into the dumbbell so the chest takes the tension and the weight cannot slip.', 'Press the dumbbell straight forward until your arms are almost straight, keeping it at chest height the whole way out.', 'Pause briefly without letting the squeeze go, then draw the dumbbell back to your chest under control.', 'Repeat for the recommended number of repetitions.', 'Tip: The squeeze on the dumbbell is what makes the exercise. If you are gripping the handle instead of crushing the weight between flat palms, the chest is not working.', 'Tip: Use a light dumbbell. Your palms hold it up on friction alone, so the grip sets the ceiling long before the chest does.', 'Tip: Keep the elbows slightly bent at the lockout and the dumbbell at sternum height throughout; letting it sag toward the hips takes the pecs out of it.']::text[]),
  ('Spiderman Push-Up', 'mid-chest', 'bodyweight', 'bodyweight_reps', 'repdb-spiderman-push-up.webp', 'repdb-spiderman-push-up-end.webp', ARRAY['Start in a high plank with the hands slightly wider than the shoulders and the body in a straight line.', 'Begin to lower the chest toward the floor and at the same time lift one foot off the floor.', 'Draw that knee out and up toward the elbow on the same side, keeping the hips low.', 'Press back up to the plank while returning the leg to the starting position.', 'Repeat on the other side and keep alternating.', 'Tip: Keep the hips level; letting them pike or sag takes the work off the trunk.', 'Tip: Bring the knee toward the elbow without letting the foot touch the floor.', 'Tip: Lower with control and keep the elbows at about 45 degrees to the body.']::text[]),
  ('Spoto Press', 'mid-chest', 'barbell', 'weight_reps', 'repdb-spoto-press.webp', 'repdb-spoto-press-end.webp', ARRAY['Lie on a flat bench and grip the barbell slightly wider than shoulders.', 'Unrack the bar and hold it over your chest with arms extended.', 'Lower the bar until it is one inch above your chest.', 'Pause there for a full second without touching the chest.', 'Press the bar back up until your arms are extended.', 'Repeat for the desired number of reps.', 'Tip: Keep your shoulder blades retracted and pinned to the bench.', 'Tip: Hold the bar motionless during the pause instead of letting it drift.', 'Tip: Use a lighter load than your standard bench press.']::text[]),
  ('TRX Chest Press', 'mid-chest', 'bodyweight', 'bodyweight_reps', 'repdb-trx-chest-press.webp', 'repdb-trx-chest-press-end.webp', ARRAY['Adjust the suspension trainer handles to mid-calf height.', 'Stand facing away from the anchor point, holding a handle in each hand, arms extended.', 'Lean forward into a plank position, keeping your body straight from head to heels.', 'Lower your chest towards your hands by bending your elbows, maintaining tension in the straps.', 'Press back up to the starting position, fully extending your arms and squeezing your chest.', 'Tip: Keep your core engaged throughout the movement to maintain a rigid plank.', 'Tip: Control the eccentric (lowering) phase for better muscle activation.', 'Tip: Adjust your foot position to modify difficulty: closer to the anchor (more horizontal) is harder, further away (more upright) is easier.', 'Tip: Ensure your elbows track slightly out and back, not flaring wide.']::text[]),
  ('Wall Push Ups', 'mid-chest', 'bodyweight', 'bodyweight_reps', 'repdb-wall-push-ups.webp', 'repdb-wall-push-ups-end.webp', ARRAY['Stand facing a wall and place your palms on it at shoulder height.', 'Step your feet back until your arms are fully extended.', 'Bend your elbows to bring your chest toward the wall.', 'Keep your body in a straight line throughout.', 'Press back to the starting position.', 'Repeat for the desired number of reps.', 'Tip: Avoid flaring your elbows straight out to the sides.', 'Tip: Step your feet farther from the wall to increase the difficulty.', 'Tip: Keep your core engaged so your hips do not sag.']::text[]),
  ('Decline EZ-Bar Bench Press', 'lower-chest', 'barbell', 'weight_reps', 'repdb-decline-bench-press-ez-bar.webp', 'repdb-decline-bench-press-ez-bar-end.webp', ARRAY['Set the bench to a decline. Secure your feet and grip the EZ-bar.', 'Lower the bar to your lower chest.', 'Press back up explosively.', 'Repeat.', 'Tip: The angled grip reduces wrist strain.', 'Tip: Keep your core braced.']::text[]),
  ('Machine Assisted Dips', 'lower-chest', 'machine', 'weight_reps', 'repdb-assisted-dips.webp', 'repdb-assisted-dips-end.webp', ARRAY['Step onto the assisted dip machine with knees on the pad.', 'Grip the parallel bars and support your weight with straight arms.', 'Lower your body by bending your elbows until shoulders are below elbows.', 'Press back up to the start position.', 'Repeat for the desired number of reps.', 'Tip: Keep your elbows tracking back rather than flaring out wide.', 'Tip: Stop the descent if you feel pinching in the shoulders.', 'Tip: Reduce the assistance gradually as pressing strength improves.']::text[]),
  ('Smith Machine Decline Bench Press', 'lower-chest', 'machine', 'weight_reps', 'repdb-smith-machine-decline-bench-press.webp', 'repdb-smith-machine-decline-bench-press-end.webp', ARRAY['Set a decline bench in the machine so the bar lines up with your lower chest when you lie down, and hook your legs under the pads.', 'Lie back with your head at the low end, take an overhand grip slightly wider than your shoulders and unrack the bar.', 'Lower the bar under control until it touches your lower chest, keeping your elbows at roughly forty-five degrees from your torso.', 'Press the bar back up until your arms are extended, without locking the elbows out hard.', 'Repeat for the desired number of repetitions, then rack the bar before releasing your legs.', 'Tip: Line the bench up before you load it. The bar only moves in one plane, so if the bench is a few centimetres out the bar will meet your throat or your stomach instead of your lower chest.', 'Tip: Secure your legs under the pads first. Head-down and unsecured, you slide toward the low end of the bench on the first hard rep.', 'Tip: Come down and sit up slowly between sets. Long sets with the head below the heart make people light-headed, and this variation is where it happens.']::text[]),
  ('Straight Bar Dips', 'lower-chest', 'bodyweight', 'bodyweight_reps', 'repdb-straight-bar-dips.webp', 'repdb-straight-bar-dips-end.webp', ARRAY['Grip a straight bar overhand, slightly wider than shoulder-width, and jump into a straight-arm support on top of it with the bar at your hips.', 'Lean your chest slightly forward and bend your elbows to lower yourself toward the bar, keeping the elbows pointing back.', 'Stop when the bar is close to your upper chest or at the deepest point you can control.', 'Press down through the bar to straighten your arms and return to the support position.', 'Repeat for the desired number of reps.', 'Tip: Lean the chest forward over the bar as you lower; the bar is in front of you, so staying upright tips you backwards.', 'Tip: Engage your core to keep your body from swinging.', 'Tip: This is a harder wrist and shoulder position than standard dips -- build up volume gradually.']::text[]),
  ('Weighted Dips', 'lower-chest', 'bodyweight', 'bodyweight_reps', 'repdb-weighted-dips.webp', 'repdb-weighted-dips-end.webp', ARRAY['Attach a plate to a dip belt around your waist so the weight hangs between your legs.', 'Grip the parallel dip bars and press yourself up to the top position with your arms locked out and your feet off the floor.', 'Lean your torso slightly forward and lower your body by bending your elbows until your shoulders are below them.', 'Press back up through your palms until your arms are locked out again, keeping the hanging plate from swinging.', 'Repeat for the desired number of reps.', 'Tip: Add weight only once you can do clean bodyweight dips through a full range — small jumps of 2.5–5 kg are enough, since the load stacks on top of your own bodyweight.', 'Tip: Keep your legs together and your core braced so the plate does not start swinging; a swinging weight throws off the bottom of the rep.', 'Tip: Keep your shoulders pulled down away from your ears and stop the descent if you feel pinching at the front of the shoulder.']::text[]),
  ('Archer Pull Ups', 'lats', 'bodyweight', 'bodyweight_reps', 'repdb-archer-pull-ups.webp', 'repdb-archer-pull-ups-end.webp', ARRAY['Grip the bar wider than shoulder width with palms facing away.', 'Pull yourself up while shifting your body toward one hand.', 'Keep the opposite arm straight as a support.', 'Lower yourself under control back to the hang.', 'Alternate sides each rep or complete reps on one side first.', 'Tip: Keep the straight arm fully extended and use it only as a guide.', 'Tip: Pull your chin toward the working hand, not straight up.', 'Tip: Master wide-grip pull-ups before progressing to archers.']::text[]),
  ('Assisted Pull Ups', 'lats', 'machine', 'weight_reps', 'repdb-assisted-pull-ups.webp', 'repdb-assisted-pull-ups-end.webp', ARRAY['Place your knees on the assisted pull-up machine pad.', 'Grip the bar with palms facing away, slightly wider than shoulders.', 'Pull your chest toward the bar by driving your elbows down.', 'Lower yourself under control to a full hang.', 'Repeat for the desired number of reps.', 'Tip: Pull your shoulder blades down before bending your arms.', 'Tip: Avoid swinging or using momentum from the knee pad.', 'Tip: Decrease the assistance over time to progress toward unassisted reps.']::text[]),
  ('Barbell Pullover', 'lats', 'barbell', 'weight_reps', 'repdb-barbell-pullover.webp', 'repdb-barbell-pullover-end.webp', ARRAY['Lie across a bench with a barbell held over your chest.', 'Lower the bar back over your head in an arc.', 'Pull it back to the start over your chest.', 'Repeat.', 'Tip: Keep a slight bend in the elbows.', 'Tip: Engage the lats to drive the bar back.']::text[]),
  ('Behind-the-Neck Lat Pulldown', 'lats', 'machine', 'weight_reps', 'repdb-behind-the-neck-lat-pulldown.webp', 'repdb-behind-the-neck-lat-pulldown-end.webp', ARRAY['Sit at a lat pulldown station with thighs secured under the pad.', 'Grip the bar with a wide, overhand grip — wider than shoulder-width.', 'Keep the torso upright and tuck the chin slightly forward.', 'Pull the bar down behind the head until it touches the base of the neck.', 'Return under control to the full overhead stretch.', 'Repeat for the recommended number of repetitions.', 'Tip: Only perform this if you have full, pain-free overhead shoulder mobility.', 'Tip: Use a moderate load — this is not a strength lift, it''s a hypertrophy accessory.']::text[]),
  ('Behind-the-Neck Pull-Up', 'lats', 'bodyweight', 'bodyweight_reps', 'repdb-behind-the-neck-pull-ups.webp', 'repdb-behind-the-neck-pull-ups-end.webp', ARRAY['Grip the pull-up bar with an overhand grip wider than shoulder-width and hang at full arm extension with your legs together.', 'Keep your torso vertical rather than leaning back, and pull your elbows down and out to the sides.', 'Continue pulling until the bar passes behind your head and the back of your neck comes level with it, without letting the bar touch your neck.', 'Lower yourself under control back to a full dead hang, keeping your head still rather than letting it snap forward.', 'Repeat for the desired number of reps.', 'Tip: This variation is widely discouraged. Finishing behind the head loads the shoulder at the end of its external rotation, where the joint has the least capacity to protect itself, and any contact between the bar and the neck puts that load through the cervical spine.', 'Tip: A standard or wide-grip pull-up trains the same muscles through the same shoulder range — nothing about back development requires the bar to travel behind the head, so there is no benefit here to trade the risk against.', 'Tip: If you perform it anyway, stop well short of touching the bar to your neck and leave it out entirely if you lack full pain-free overhead shoulder mobility or have any history of shoulder or neck problems.']::text[]),
  ('Bench Pull', 'lats', 'barbell', 'weight_reps', 'repdb-bench-pull.webp', 'repdb-bench-pull-end.webp', ARRAY['Lie face down on an elevated bench with arms hanging straight down.', 'Grip a barbell or dumbbells below you.', 'Row the weight up to the underside of the bench.', 'Squeeze your shoulder blades at the top.', 'Lower under control and repeat.', 'Tip: Keep your chest glued to the bench to prevent cheating.', 'Tip: Reach a full stretch at the bottom before each pull.', 'Tip: Drive your elbows up and back rather than curling the weight.']::text[]),
  ('Bent-Arm EZ-Bar Pullover', 'lats', 'barbell', 'weight_reps', 'repdb-bent-arm-ez-bar-pullover.webp', 'repdb-bent-arm-ez-bar-pullover-end.webp', ARRAY['Lie on a flat bench holding an EZ-bar with a narrow overhand grip on the inner bends.', 'Start with the bar above your chest, elbows bent to roughly 90 degrees.', 'Keep the elbow angle fixed and lower the bar back in an arc overhead until a deep stretch is felt in the lats and pecs.', 'Pull the bar back over the chest along the same arc, without straightening the elbows.', 'Repeat for the recommended number of repetitions.', 'Tip: The elbow angle stays fixed — only the shoulder moves.', 'Tip: Bent elbows shorten the lever, so you can usually handle a little more weight than in a straight-arm pullover.', 'Tip: If the lower back arches, plant the feet more firmly and brace the abs.']::text[]),
  ('Dumbbell Bench Pull', 'lats', 'dumbbell', 'weight_reps', 'repdb-dumbbell-bench-pull.webp', 'repdb-dumbbell-bench-pull-end.webp', ARRAY['Lie face down on an incline bench holding dumbbells.', 'Let your arms hang straight down.', 'Pull the dumbbells up toward your chest, squeezing your shoulder blades.', 'Lower with control.', 'Repeat.', 'Tip: Keep your chest glued to the bench throughout the pull.', 'Tip: Drive your elbows up and back rather than curling the weight.', 'Tip: Let your shoulder blades protract fully at the bottom for full range.']::text[]),
  ('EZ Bar Pullover', 'lats', 'barbell', 'weight_reps', 'repdb-ez-bar-pullover.webp', 'repdb-ez-bar-pullover-end.webp', ARRAY['Lie supine on a flat bench with your head slightly off the end, holding an EZ bar with a pronated grip.', 'Extend the bar straight above your chest, keeping a slight bend in your elbows.', 'Slowly lower the bar in an arc behind your head, feeling a stretch in your lats and chest.', 'Pull the bar back to the starting position using your lats and pectorals.', 'Maintain control throughout the movement, avoiding momentum.', 'Tip: Keep your core braced to prevent arching your lower back excessively.', 'Tip: Focus on a deep stretch at the bottom of the movement.', 'Tip: Use a spotter for heavier loads to ensure safety.', 'Tip: Control the eccentric (lowering) phase for maximum muscle engagement.']::text[]),
  ('Floor Kettlebell Pullover', 'lats', 'kettlebell', 'weight_reps', 'repdb-floor-kettlebell-pullover.webp', 'repdb-floor-kettlebell-pullover-end.webp', ARRAY['Lie face-up on the floor with knees bent and feet flat.', 'Hold a kettlebell by the handle with both hands above your chest, arms almost straight (slight elbow bend).', 'Keeping the elbow angle fixed, lower the bell overhead in an arc until the upper arms touch the floor.', 'Pull the bell back above the chest along the same arc.', 'Repeat for the recommended number of repetitions.', 'Tip: The floor caps the ROM; if it feels too short, use a bench version.', 'Tip: Grip the handle firmly and squeeze the lats at the top.', 'Tip: Keep the lower back flat against the floor throughout.']::text[]),
  ('Front Lever', 'lats', 'bodyweight', 'duration', 'repdb-front-lever.webp', null, ARRAY['Grip the bar with an overhand grip and hang.', 'Tuck your knees to your chest and pull your straight arms down toward your hips, leaning back until your torso is horizontal and your chest faces up.', 'Extend your body horizontally with arms straight and chest facing the ceiling.', 'Keep your body rigid and parallel to the floor.', 'Hold for the desired duration, then tuck and lower under control.', 'Tip: Progress through tuck and straddle holds before attempting the full extension.', 'Tip: Squeeze your core and glutes to prevent the hips from dropping.', 'Tip: Keep the shoulders actively depressed away from the ears throughout the hold.']::text[]),
  ('Kettlebell Pullover', 'lats', 'kettlebell', 'weight_reps', 'repdb-kettlebell-pullover.webp', 'repdb-kettlebell-pullover-end.webp', ARRAY['Lie on a flat bench holding a kettlebell by the horns with both hands above the chest, arms nearly straight (slight elbow bend).', 'Keeping the elbow angle fixed, lower the bell overhead in an arc until the upper arms are in line with the torso.', 'Pull the bell back above the chest along the same arc.', 'Repeat for the recommended number of repetitions.', 'Tip: Keep the lower back pressed into the bench — do not arch to steal ROM.', 'Tip: Grip the horns hard; the bell will try to flip over at the bottom.', 'Tip: Go only as deep as your shoulder mobility allows without pain.']::text[]),
  ('Negative Pull Ups', 'lats', 'bodyweight', 'bodyweight_reps', 'repdb-negative-pull-ups.webp', 'repdb-negative-pull-ups-end.webp', ARRAY['Use a box or jump to position yourself at the top of a pull-up.', 'Grip the bar with hands shoulder-width apart.', 'Hold your chin above the bar briefly.', 'Lower yourself slowly over 3-5 seconds with control.', 'Fully extend your arms at the bottom.', 'Reset and repeat for the desired number of reps.', 'Tip: Fight for control during the final third of the descent.', 'Tip: Keep your shoulder blades engaged instead of hanging passively.', 'Tip: Stop the set once you can no longer lower slowly.']::text[]),
  ('Neutral Grip Pull Ups', 'lats', 'bodyweight', 'bodyweight_reps', 'repdb-neutral-grip-pull-ups.webp', 'repdb-neutral-grip-pull-ups-end.webp', ARRAY['Grip parallel bars with palms facing each other.', 'Hang with your arms fully extended.', 'Pull yourself up until your chin clears the bar.', 'Squeeze your lats at the top of the movement.', 'Lower yourself with control to the starting position.', 'Repeat for the desired number of reps.', 'Tip: Initiate each rep by pulling your shoulder blades down and back.', 'Tip: Drive your elbows down toward your ribs as you pull.', 'Tip: Avoid kipping or swinging your legs for momentum.']::text[]),
  ('Pause Pull-Up', 'lats', 'bodyweight', 'bodyweight_reps', 'repdb-pause-pull-up.webp', 'repdb-pause-pull-up-end.webp', ARRAY['Hang from a pull-up bar with an overhand grip, arms fully extended.', 'Pull yourself up until your chin clears the bar.', 'Pause and hold that top position for a moment.', 'Lower yourself back down under control to a full hang.', 'Repeat for the desired number of reps.', 'Tip: The pause removes momentum, so the pull is harder than a regular pull-up -- expect fewer reps.', 'Tip: Keep your shoulders engaged during the hold instead of relaxing into the bar.', 'Tip: Lower slowly instead of dropping straight into the next rep.']::text[]),
  ('Plate Pullover', 'lats', 'other', 'weight_reps', 'repdb-plate-pullover.webp', 'repdb-plate-pullover-end.webp', ARRAY['Lie flat on a bench holding a plate with both hands.', 'Press the plate over the chest with arms nearly straight.', 'Lower the plate back in an arc behind the head until you feel a stretch.', 'Pull the plate back over the chest along the same arc.', 'Repeat for the prescribed reps.', 'Tip: Keep the elbows soft but locked at the same angle.', 'Tip: Stop at the bottom of your clean range — no excessive shoulder stretch.', 'Tip: Plant the feet firmly for stability.']::text[]),
  ('Ring Muscle-Up', 'lats', 'bodyweight', 'bodyweight_reps', 'repdb-ring-muscle-up.webp', 'repdb-ring-muscle-up-end.webp', ARRAY['Hang from the rings with a false grip, palms facing each other.', 'Pull explosively, driving the chest up to the rings.', 'Transition the elbows over the rings as the chest rises.', 'Press to full arm extension at the top.', 'Lower under control through the transition back to the hang.', 'Tip: A false grip is essential for the transition.', 'Tip: Drive the elbows down hard during the transition.', 'Tip: Build the strength with negatives and band-assisted reps first.']::text[]),
  ('Rope Climb', 'lats', 'other', 'weight_reps', 'repdb-rope-climb.webp', null, ARRAY['Grip the rope as high as you can with both hands.', 'Either wrap the rope around one foot (S-hook or J-hook) or pinch it between both feet.', 'Pull with your arms and bring your knees up, then clamp the rope with your feet and stand up on the foot lock.', 'Reach higher with one hand, then the other, release the feet, and clamp the rope again higher up.', 'Repeat until you reach the top of the rope.', 'Descend hand-under-hand with the feet controlling the speed — never slide.', 'Tip: Learn the foot lock before attempting longer climbs; it doubles your work capacity.', 'Tip: Never drop from the top; controlled descent is part of the exercise.']::text[]),
  ('Single-Arm Chest-Supported Dumbbell Row', 'lats', 'dumbbell', 'weight_reps', 'repdb-single-arm-chest-supported-dumbbell-row.webp', 'repdb-single-arm-chest-supported-dumbbell-row-end.webp', ARRAY['Lie face-down on an incline bench holding a dumbbell in one hand, arm hanging straight down.', 'Row the dumbbell up to your side, driving your elbow past your torso.', 'Squeeze your shoulder blade at the top, then lower under control.', 'Complete all reps on one side before switching arms.', 'Tip: Working one side at a time lets you focus on a full contraction without the other arm compensating.', 'Tip: Keep your chest pressed into the bench throughout to avoid using momentum.', 'Tip: Match the rep count on both sides to avoid imbalances.']::text[]),
  ('Wide Grip Pull Ups', 'lats', 'bodyweight', 'bodyweight_reps', 'repdb-wide-grip-pull-ups.webp', 'repdb-wide-grip-pull-ups-end.webp', ARRAY['Grip the pull-up bar with an overhand grip wider than shoulder-width.', 'Hang with arms fully extended and core braced.', 'Pull your chest toward the bar by driving your elbows down.', 'Keep your shoulders pulled back as you rise.', 'Lower yourself under control to full extension.', 'Repeat for the desired number of reps.', 'Tip: Initiate each rep by depressing your shoulder blades before bending the arms.', 'Tip: Avoid kipping or swinging your legs for momentum.', 'Tip: Squeeze the bar firmly and keep your wrists straight.']::text[]),
  ('Bent-Over EZ-Bar Row', 'upper-back', 'barbell', 'weight_reps', 'repdb-bent-over-ez-bar-row.webp', 'repdb-bent-over-ez-bar-row-end.webp', ARRAY['Hold an EZ-bar with an overhand grip, hinge at the hips to 45 degrees.', 'Pull the bar to your lower ribcage.', 'Lower under control.', 'Repeat.', 'Tip: Keep your back flat throughout.', 'Tip: Initiate with the elbows, not the hands.']::text[]),
  ('Cable Bent-Over Row', 'upper-back', 'cable', 'weight_reps', 'repdb-cable-bent-over-row.webp', 'repdb-cable-bent-over-row-end.webp', ARRAY['Attach a straight or V-bar to a low cable pulley.', 'Hinge at the hips with knees slightly bent.', 'Pull the handle toward your lower chest.', 'Squeeze your shoulder blades at the top.', 'Lower with control and repeat.', 'Tip: Hold the hinge position steady instead of standing up as you pull.', 'Tip: Keep your back flat from head to hips throughout.', 'Tip: Resist the cable''s pull on the way back to full stretch.']::text[]),
  ('Chest-Supported Kettlebell Row', 'upper-back', 'kettlebell', 'weight_reps', 'repdb-chest-supported-kettlebell-row.webp', 'repdb-chest-supported-kettlebell-row-end.webp', ARRAY['Lie face down on an incline bench, allowing your arms to hang freely with a kettlebell in each hand.', 'Brace your core and retract your shoulder blades.', 'Pull the kettlebells towards your hips, squeezing your shoulder blades together.', 'Pause briefly at the top, feeling the contraction in your back.', 'Slowly lower the kettlebells back to the starting position with control.', 'Tip: Maintain a stable torso throughout the movement; avoid rocking.', 'Tip: Focus on initiating the pull with your back muscles, not just your arms.', 'Tip: Keep your elbows close to your body to emphasize the lats.']::text[]),
  ('Chest-Supported Smith Machine Row', 'upper-back', 'machine', 'weight_reps', 'repdb-chest-supported-smith-machine-row.webp', 'repdb-chest-supported-smith-machine-row-end.webp', ARRAY['Set an incline bench inside the Smith machine facing the bar, and set the bar low enough that your arms hang straight when you lean on the pad.', 'Stand astride the bench with your feet planted and your chest resting against the top of the pad.', 'Take an overhand grip a little wider than shoulder-width and unhook the bar with your arms extended.', 'Pull the bar up to your lower chest, leading with your elbows and squeezing the shoulder blades together at the top.', 'Lower the bar under control until your arms are straight again, and repeat for the desired number of repetitions.', 'Tip: Keep your chest on the pad for every repetition. The moment you push off it to move the weight you have turned this back into a bent-over row and given up the reason for the setup.', 'Tip: Lead with the elbows and stop when they pass your torso. Pulling further only rolls the shoulders forward and the fixed bar path leaves nowhere for them to go.', 'Tip: Because your lower back is doing nothing here, this is the row to use on a day when a bent-over row is not an option -- match the weight to what your back can pull, not to what your legs could brace.']::text[]),
  ('Double Kettlebell Row', 'upper-back', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-row.webp', 'repdb-double-kettlebell-row-end.webp', ARRAY['Hold a kettlebell in each hand and hinge forward at the hips.', 'Let your arms hang straight down from your shoulders.', 'Row both kettlebells to your hips by driving elbows back.', 'Squeeze your shoulder blades at the top.', 'Lower under control and repeat.', 'Tip: Hold your hinge angle steady; avoid standing up as you pull.', 'Tip: Keep your neck neutral by gazing at the floor ahead.', 'Tip: Brace your core to protect your lower back throughout.']::text[]),
  ('Kneeling Cable Row', 'upper-back', 'cable', 'weight_reps', 'repdb-kneeling-cable-row.webp', 'repdb-kneeling-cable-row-end.webp', ARRAY['Set a cable pulley to about chest height and attach a rope or double-D handle.', 'Kneel upright facing the stack far enough back that the weight stack doesn''t bottom out.', 'Grab the handle with both hands and hold it out in front at chest height.', 'Row the handle to the sternum by driving the elbows back and squeezing the shoulder blades together.', 'Return under control to the stretched starting position.', 'Repeat for the recommended number of repetitions.', 'Tip: Stay tall — no leaning back to finish the rep.', 'Tip: The tall-kneeling stance forces the core to resist rotation on every pull.']::text[]),
  ('Pendlay Row', 'upper-back', 'barbell', 'weight_reps', 'repdb-pendlay-row.webp', 'repdb-pendlay-row-end.webp', ARRAY['Load a barbell and set it on the floor.', 'Hinge at the hips until your torso is parallel to the ground, knees slightly bent.', 'Grip the bar slightly wider than shoulder-width with an overhand grip.', 'Explosively pull the bar to your lower chest.', 'Lower the bar back to the floor under control and pause before the next rep.', 'Repeat.', 'Tip: Dead-stop each rep on the floor — no touch-and-go.', 'Tip: Keep your torso locked at roughly 90 degrees; do not use body english.', 'Tip: Drive the elbows up and back, not out to the sides.']::text[]),
  ('Ring Row', 'upper-back', 'bodyweight', 'bodyweight_reps', 'repdb-ring-row.webp', 'repdb-ring-row-end.webp', ARRAY['Set the rings at hip to chest height.', 'Grip the rings with palms facing each other, lean back at an angle with arms straight.', 'Brace the core and pull the chest toward the rings.', 'Squeeze the shoulder blades together at the top.', 'Lower under control to a full-arm extension.', 'Tip: The lower the body angle, the harder the row.', 'Tip: Keep the body in a straight line — do not let the hips sag.', 'Tip: Pull the elbows back, not flared out, for more lat involvement.']::text[]),
  ('Rings Inverted Row', 'upper-back', 'bodyweight', 'bodyweight_reps', 'repdb-rings-inverted-row.webp', 'repdb-rings-inverted-row-end.webp', ARRAY['Set the rings just above hip height.', 'Lie under the rings and grip them with palms facing each other.', 'Walk the feet forward so the body forms a straight line.', 'Pull the chest toward the rings, squeezing the shoulder blades.', 'Lower under control to a full-arm extension.', 'Tip: Keep the body in a straight line — heels through head.', 'Tip: Squeeze the glutes and core to prevent sagging.', 'Tip: Elevate the feet on a box for a harder version.']::text[]),
  ('Sled Row', 'upper-back', 'other', 'weight_reps', 'repdb-sled-row.webp', 'repdb-sled-row-end.webp', ARRAY['Load a sled with two straps attached and take one strap handle in each hand.', 'Stand facing the sled with the arms extended and the torso leaned back slightly against the load.', 'Pull the sled toward you by driving the elbows back, and take a short step backwards as you do.', 'Extend the arms again, step back once more, and repeat the pull.', 'Continue for distance or time, keeping a steady pull-and-step rhythm.', 'Tip: Keep the chest up and the back flat — let the legs carry you backwards rather than rounding over the sled.', 'Tip: Use a load you can move continuously; the point is a steady drag, not a maximal pull.', 'Tip: No straps? A rope looped around the sled works the same way.']::text[]),
  ('Wide Grip Seated Cable Row', 'upper-back', 'cable', 'weight_reps', 'repdb-wide-grip-seated-cable-row.webp', 'repdb-wide-grip-seated-cable-row-end.webp', ARRAY['Sit at a cable row station with feet on the platform.', 'Grip a wide bar with an overhand grip.', 'Pull the bar toward your upper abdomen, squeezing your shoulder blades.', 'Extend your arms back to the starting position with control.', 'Repeat.', 'Tip: Keep your torso upright and avoid rocking back and forth.', 'Tip: Drive your elbows high and wide to target the upper back.', 'Tip: Maintain a slight bend in your knees throughout the set.']::text[]),
  ('Chest Supported Dumbbell Shrug', 'traps', 'dumbbell', 'weight_reps', 'repdb-chest-supported-dumbbell-shrug.webp', 'repdb-chest-supported-dumbbell-shrug-end.webp', ARRAY['Set an incline bench to about 30 degrees.', 'Lie face down on the bench holding dumbbells at arm''s length.', 'Shrug your shoulders up and back toward your ears.', 'Squeeze your upper traps at the top.', 'Lower under control and repeat.', 'Tip: Shrug up and back toward your ears rather than straight up.', 'Tip: Keep your chest pinned to the pad so you cannot use body english.', 'Tip: Pause and squeeze at the top before lowering under control.']::text[]),
  ('EZ-Bar Shrug', 'traps', 'barbell', 'weight_reps', 'repdb-ez-bar-shrug.webp', 'repdb-ez-bar-shrug-end.webp', ARRAY['Stand holding an EZ-bar in front of you.', 'Shrug your shoulders straight up.', 'Hold at the top, then lower.', 'Repeat.', 'Tip: Avoid rolling the shoulders in circles.', 'Tip: Use a full range of motion.']::text[]),
  ('Kettlebell Shrug', 'traps', 'kettlebell', 'weight_reps', 'repdb-kettlebell-shrug.webp', 'repdb-kettlebell-shrug-end.webp', ARRAY['Stand tall with feet hip-width apart, holding a kettlebell in each hand with palms facing your body.', 'Keep your arms straight and shoulders relaxed.', 'Elevate your shoulders straight up towards your ears, squeezing your traps at the top.', 'Hold the contraction briefly.', 'Slowly lower your shoulders back to the starting position with control.', 'Repeat for the desired number of repetitions.', 'Tip: Focus on moving only your shoulders, keeping your arms straight throughout the movement.', 'Tip: Avoid rolling your shoulders; move them straight up and down.', 'Tip: Maintain a neutral spine and engaged core to prevent lower back strain.', 'Tip: Use a weight that allows for full range of motion and controlled execution.']::text[]),
  ('Smith Machine Shrug', 'traps', 'machine', 'weight_reps', 'repdb-smith-machine-shrug.webp', 'repdb-smith-machine-shrug-end.webp', ARRAY['Stand upright inside a Smith machine with the bar at thigh height.', 'Grip the bar slightly wider than shoulder-width with an overhand grip.', 'Unrack the bar and let it hang in front of your thighs.', 'Shrug your shoulders straight up toward your ears.', 'Hold the top for a moment, then lower slowly.', 'Repeat for the desired number of reps.', 'Tip: Keep your arms straight so the traps, not the biceps, do the work.', 'Tip: Lift straight up and down rather than rolling the shoulders.', 'Tip: Keep your neck neutral and avoid jutting the chin forward.']::text[]),
  ('Bird-Dog', 'lower-back', 'bodyweight', 'bodyweight_reps', 'repdb-bird-dog.webp', 'repdb-bird-dog-end.webp', ARRAY['Start on all fours with a neutral spine.', 'Extend your right arm forward and left leg back simultaneously.', 'Hold for a moment, then return.', 'Repeat on the other side.', 'Alternate.', 'Tip: Move slowly and with control.', 'Tip: Keep hips level throughout.']::text[]),
  ('Bodyweight Good Morning', 'lower-back', 'bodyweight', 'bodyweight_reps', 'repdb-bodyweight-good-morning.webp', 'repdb-bodyweight-good-morning-end.webp', ARRAY['Stand with feet hip-width apart and hands behind your head.', 'Keep a slight bend in your knees and brace your core.', 'Hinge at the hips and lower your torso toward parallel.', 'Drive your hips forward to return to standing.', 'Repeat for the desired number of reps.', 'Tip: Push your hips back as if closing a door behind you.', 'Tip: Keep your spine neutral from head to tailbone throughout.', 'Tip: Stop the descent when your hamstrings reach their stretch limit.']::text[]),
  ('Dumbbell Deadlift', 'lower-back', 'dumbbell', 'weight_reps', 'repdb-dumbbell-deadlift.webp', 'repdb-dumbbell-deadlift-end.webp', ARRAY['Stand with feet hip-width apart, hinge at the hips with a flat back and hold the dumbbells low, at shin height.', 'Brace your core and keep the dumbbells close to your legs.', 'Drive through your heels and extend your hips to stand up tall.', 'Extend your hips fully at the top without hyperextending your lower back.', 'Hinge back down, lowering the dumbbells along your legs to your shins.', 'Repeat for the desired number of reps.', 'Tip: Brace your core before each rep to keep your spine stable.', 'Tip: Balance your weight over midfoot rather than your toes.', 'Tip: Keep your neck in line with your spine rather than looking up.']::text[]),
  ('Jefferson Curl', 'lower-back', 'dumbbell', 'weight_reps', 'repdb-jefferson-curl.webp', 'repdb-jefferson-curl-end.webp', ARRAY['Stand tall holding a light dumbbell with straight arms, feet roughly hip-width.', 'Tuck your chin and begin rounding the spine from the top, one vertebra at a time.', 'Curl down slowly, letting the weight hang and keeping the legs mostly straight.', 'Reach the bottom with the back fully rounded and a stretch through the hamstrings.', 'Reverse it, restacking the spine from the bottom up back to standing.', 'Tip: Use a very light weight -- this is a controlled mobility drill, not a heavy lift.', 'Tip: Round segment by segment; do not hinge at the hips like a stiff-leg deadlift.', 'Tip: Move slowly and never bounce at the bottom.']::text[]),
  ('Kettlebell Deadlift', 'lower-back', 'kettlebell', 'weight_reps', 'repdb-kettlebell-deadlift.webp', 'repdb-kettlebell-deadlift-end.webp', ARRAY['Stand with feet shoulder-width apart and kettlebell between your feet.', 'Hinge at the hips and bend your knees to grip the handle.', 'Brace your core and set your back flat.', 'Drive through your heels to stand up with the kettlebell.', 'Lock out at the top with shoulders pulled back.', 'Lower the kettlebell back to the floor with control.', 'Tip: Keep the kettlebell close to your shins as you lift.', 'Tip: Think of pushing the floor away rather than lifting with your back.', 'Tip: Look at a spot on the floor ahead to keep your neck neutral.']::text[]),
  ('Machine Back Extension', 'lower-back', 'machine', 'weight_reps', 'repdb-machine-back-extension.webp', 'repdb-machine-back-extension-end.webp', ARRAY['Sit in the back extension machine with your feet flat on the foot platform and the roller pad set behind your upper back, just below the shoulder blades.', 'Grip the handles at your sides and let your torso come forward into a slight flexion — this is the starting position.', 'Push back against the pad by extending your spine until your torso is leaning back and your lower back is fully contracted.', 'Pause briefly at full extension, then return to the starting position under control, resisting the weight stack on the way back.', 'Repeat for the desired number of reps.', 'Tip: Set the pad across your upper back just below the shoulder blades — too high and it presses on your neck, too low and you lose range of motion.', 'Tip: Extend with your lower back rather than throwing your head and shoulders backwards, and keep both directions slow.', 'Tip: Stop at a neutral, fully extended trunk instead of forcing the spine past it, and start light — the lower back responds better to controlled reps than to heavy loads.']::text[]),
  ('Pause Deadlift', 'lower-back', 'barbell', 'weight_reps', 'repdb-pause-deadlift.webp', 'repdb-pause-deadlift-end.webp', ARRAY['Set up for a conventional deadlift.', 'Pull the bar off the floor and pause when it passes your knees.', 'Hold for 2–3 seconds, then complete the lift.', 'Lower under control.', 'Repeat.', 'Tip: The pause removes momentum and builds strength and control from the knees to lockout.', 'Tip: Keep your back flat during the pause.']::text[]),
  ('Reverse Plank', 'lower-back', 'bodyweight', 'duration', 'repdb-reverse-plank.webp', null, ARRAY['Sit on the floor with your legs extended in front of you.', 'Place your hands behind you with fingers pointing toward your feet.', 'Lift your hips off the floor to form a straight line from head to heels.', 'Squeeze your glutes and brace your core.', 'Hold the position for the desired duration.', 'Lower your hips with control to exit.', 'Tip: Don''t let your hips sag as the hold progresses.', 'Tip: Keep your gaze up to maintain a neutral neck.', 'Tip: Press evenly through your palms to reduce wrist strain.']::text[]),
  ('Smith Machine Good Morning', 'lower-back', 'machine', 'weight_reps', 'repdb-smith-machine-good-morning.webp', 'repdb-smith-machine-good-morning-end.webp', ARRAY['Set the bar at upper-back height, step under it and settle it across your traps, then unrack it with your feet about hip-width apart.', 'Soften your knees slightly and keep them there -- this is a hinge, not a squat.', 'Push your hips straight back and let your torso tip forward, keeping your back flat and your head in line with your spine.', 'Stop when you feel a strong stretch in your hamstrings, with your torso somewhere near parallel to the floor.', 'Drive your hips forward to stand back up, squeezing the glutes at the top, and repeat for the desired reps.', 'Tip: Use much less weight than you would for a squat. The bar is a long way from your hips at the bottom, and that lever, not the number on the bar, is what the exercise costs you.', 'Tip: Hips back, not chest down. If your torso drops without your hips travelling backwards you are bending your spine instead of hinging at the hip.', 'Tip: Let the range of motion end where your back would start to round. Depth on a good morning is set by your hamstrings, and the machine will happily take you past that point.']::text[]),
  ('Superman', 'lower-back', 'bodyweight', 'bodyweight_reps', 'repdb-superman.webp', 'repdb-superman-end.webp', ARRAY['Lie face down with arms extended overhead.', 'Simultaneously lift your arms, chest, and legs off the floor.', 'Hold briefly at the top.', 'Lower under control.', 'Repeat.', 'Tip: Squeeze glutes as you lift.', 'Tip: Avoid jerking movements.']::text[]),
  ('Thoracic Bridge', 'lower-back', 'bodyweight', 'bodyweight_reps', 'repdb-thoracic-bridge.webp', null, ARRAY['Sit on the floor with knees bent and hands behind you, fingers pointing back.', 'Press through your hands and feet to lift your hips off the floor.', 'Continue pressing until your chest opens and your arms are extended.', 'Drop your head back and hold the position.', 'Breathe steadily while maintaining the bridge.', 'Lower back down under control.', 'Tip: Drive the hips high and squeeze the glutes to protect the lower back.', 'Tip: Keep the feet flat and the weight even between hands and feet.']::text[]),
  ('Barbell Front Raise', 'front-delts', 'barbell', 'weight_reps', 'repdb-barbell-front-raise.webp', 'repdb-barbell-front-raise-end.webp', ARRAY['Stand holding a barbell with an overhand grip at thigh level.', 'Keep your arms straight and core braced.', 'Raise the barbell in front of you to shoulder height.', 'Pause briefly at the top.', 'Lower under control and repeat.', 'Tip: Use a light weight to avoid swinging the bar up.', 'Tip: Avoid leaning back as the bar rises.', 'Tip: Keep your wrists neutral rather than letting them bend backward.']::text[]),
  ('Bear Crawl', 'front-delts', 'bodyweight', 'bodyweight_reps', 'repdb-bear-crawl.webp', 'repdb-bear-crawl-end.webp', ARRAY['Start on all fours with your hands under your shoulders and knees under your hips.', 'Tuck your toes and lift your knees a few centimeters off the floor.', 'Keeping your back flat and hips low, step your right hand and left foot forward together.', 'Then move your left hand and right foot, crawling forward in a controlled rhythm.', 'Keep your core braced and your hips from swaying side to side.', 'Tip: Move opposite hand and foot together, like an exaggerated crawl.', 'Tip: Keep your knees low and hips level — do not let them pop up or rock.']::text[]),
  ('Behind the Neck Press', 'front-delts', 'barbell', 'weight_reps', 'repdb-behind-the-neck-press.webp', 'repdb-behind-the-neck-press-end.webp', ARRAY['Sit or stand with a barbell resting on your upper traps behind your neck.', 'Grip the bar wider than shoulder width.', 'Press the bar straight up overhead until your arms are extended.', 'Lower the bar back to the starting position under control.', 'Repeat for the desired number of reps.', 'Tip: Lower the bar only as far as your shoulders allow comfortably.', 'Tip: Keep your forearms vertical under the bar throughout the press.', 'Tip: Brace your core to avoid arching the lower back overhead.']::text[]),
  ('Bodyweight Overhead Press', 'front-delts', 'bodyweight', 'bodyweight_reps', 'repdb-bodyweight-overhead-press.webp', 'repdb-bodyweight-overhead-press-end.webp', ARRAY['Stand tall with your feet hip-width apart and your hands in loose fists at shoulder height, palms facing forward and elbows under the wrists.', 'Brace your core and squeeze your glutes so your ribs stay down.', 'Press both arms straight up until the elbows are fully extended and the upper arms are beside your ears.', 'Lower your hands back to shoulder height under control.', 'Repeat for the desired number of reps.', 'Tip: Finish with your hands directly over your shoulders, not in front of your face.', 'Tip: Do not lean back or arch your lower back to get the arms higher.', 'Tip: Once the pattern feels smooth, hold light dumbbells or a band to add load.']::text[]),
  ('Double Dumbbell Overhead Carry', 'front-delts', 'dumbbell', 'weight_reps', 'repdb-double-db-overhead-carry.webp', null, ARRAY['Clean or press a dumbbell to lockout above each shoulder.', 'Straighten both elbows fully and keep reaching up into the weights so the shoulders stay active, without letting the dumbbells sink down onto them.', 'Brace hard and keep your ribs down — with both arms overhead the temptation to arch is much stronger.', 'Walk forward with short, deliberate strides, keeping both dumbbells stacked over your shoulders.', 'Keep breathing shallowly and steadily instead of holding your breath for the whole carry.', 'Carry for the desired distance, then lower both weights under control.', 'Tip: Start lighter than your single-arm carry weight per hand. Two arms overhead is not twice as easy, it is twice as much to stabilise.', 'Tip: Have a plan for bailing out before you start, and carry where you can drop the weights safely.', 'Tip: Short distances done well beat long ones done bent. Stop the set when your ribs start to flare, not when your shoulders give out.']::text[]),
  ('Double Kettlebell Clean and Press', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-clean-and-press.webp', 'repdb-double-kettlebell-clean-and-press-end.webp', ARRAY['Stand with two kettlebells on the floor between your feet, feet about hip-width apart, and hinge at the hips to grip one handle in each hand.', 'Drive through your legs and extend your hips explosively to pull both kettlebells up, then rotate your elbows under and catch the bells in the racked position at the front of your shoulders.', 'Brace your core and press both kettlebells overhead until your arms are fully locked out.', 'Lower the kettlebells back to the racked position, then down to the floor under control.', 'Repeat for the desired number of reps.', 'Tip: Keep the kettlebells close to your body during the clean and punch your hands around and through the handles as you catch them, so the bells settle on your forearms instead of banging into them.', 'Tip: Use a slight dip-drive from the legs and hips to start the press, then finish with the shoulders — keep your core tight so you do not lean back under the load.', 'Tip: At lockout keep your wrists straight and the kettlebells stacked over your elbows and shoulders, with your head returning to a neutral position between the bells.']::text[]),
  ('Double Kettlebell Dead Split Snatch', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-dead-split-snatch.webp', 'repdb-double-kettlebell-dead-split-snatch-end.webp', ARRAY['Set two kettlebells on the floor between your feet.', 'Hinge down and grip both handles firmly.', 'Explosively pull the kettlebells overhead in one motion.', 'Drop into a split stance to catch them at lockout.', 'Recover by stepping feet back together.', 'Tip: Punch up through the handles to achieve a stable overhead lockout.', 'Tip: Keep your front knee tracking over your foot in the split.', 'Tip: Stay tall through your torso as you drop under the bells.']::text[]),
  ('Double Kettlebell Jerk', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-jerk.webp', 'repdb-double-kettlebell-jerk-end.webp', ARRAY['Start with two kettlebells racked on the shoulders, elbows resting on the hips.', 'Perform a short dip at the knees, then explosively extend the legs to drive the kettlebells up.', 'As the bells rise, perform a second dip under them by bending the knees again.', 'Catch the kettlebells overhead with arms locked out, then stand fully upright.', 'Lower them back to the rack under control and repeat.', 'Tip: The jerk is two dips, not one — the second dip is what lets you lock out with light arms.', 'Tip: Breathe on every rep, exhaling on each dip and drive, instead of holding your breath through the set.']::text[]),
  ('Double Kettlebell Overhead Carry', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-overhead-carry.webp', null, ARRAY['Clean two kettlebells to the rack, then press or push press both to lockout overhead.', 'Straighten both elbows and settle each bell behind and above its wrist, with your wrists straight.', 'Pull your ribs down and brace hard before the first step; with both bells overhead there is nothing to counterbalance with.', 'Walk forward with short, controlled strides, keeping both bells stacked over your shoulders.', 'Keep looking straight ahead and breathe steadily through the carry.', 'Cover the desired distance, then lower both bells to the rack and down under control.', 'Tip: Earn this one. Be comfortable with the single-bell overhead carry on both sides before loading two.', 'Tip: Only do it where you can safely drop both bells, and know which way you will step if you have to.', 'Tip: Distance should be short and posture perfect. The moment your back arches or a wrist folds, the set is finished.']::text[]),
  ('Double Kettlebell Overhead Press', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-overhead-press.webp', 'repdb-double-kettlebell-overhead-press-end.webp', ARRAY['Clean two kettlebells to the rack position at your shoulders.', 'Stand tall with feet hip-width apart.', 'Press both kettlebells straight overhead.', 'Lock out your arms at the top.', 'Lower back to the rack position and repeat.', 'Tip: Squeeze your glutes and brace your abs before each press.', 'Tip: Keep your forearms vertical as you drive the bells up.', 'Tip: Avoid flaring your ribs or arching your lower back at lockout.']::text[]),
  ('Double Kettlebell Push Press', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-push-press.webp', 'repdb-double-kettlebell-push-press-end.webp', ARRAY['Stand with two kettlebells racked at the shoulders, elbows down and tucked.', 'Feet shoulder-width, core braced.', 'Dip the knees slightly while keeping the torso vertical.', 'Explosively extend the legs and press both bells overhead in one motion.', 'Lock out with the bells over the mid-foot.', 'Lower back to the rack under control.', 'Repeat for the recommended number of repetitions.', 'Tip: Only ONE dip — if you re-bend the knees under the bell, that is a jerk.', 'Tip: Drive from the legs, the arms finish.', 'Tip: The torso stays vertical throughout; no lean.']::text[]),
  ('Double Kettlebell Split Jerk', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-split-jerk.webp', 'repdb-double-kettlebell-split-jerk-end.webp', ARRAY['Clean two kettlebells to the rack position at your shoulders.', 'Dip slightly by bending your knees.', 'Drive the kettlebells overhead explosively.', 'Split your legs to catch them with locked arms.', 'Recover by stepping feet back together.', 'Tip: Keep your heels down during the dip to maintain power.', 'Tip: Time the split so your arms lock as your feet land.', 'Tip: Drive with your legs; your arms mainly guide the bells.']::text[]),
  ('Dumbbell Clean and Press', 'front-delts', 'dumbbell', 'weight_reps', 'repdb-dumbbell-clean-and-press.webp', 'repdb-dumbbell-clean-and-press-end.webp', ARRAY['Stand with the feet hip-width apart and a dumbbell in each hand, hanging at your sides.', 'Hinge at the hips and bend the knees slightly to lower the dumbbells to just below the knees.', 'Explosively extend the hips and knees and shrug to pull the dumbbells up to the shoulders, catching them with the elbows forward.', 'Dip slightly at the knees and drive the dumbbells straight overhead until the arms are locked out.', 'Lower the dumbbells back to the shoulders, then to your sides, under control.', 'Repeat for the desired number of repetitions.', 'Tip: Let the legs and hips produce the power; the arms only guide the dumbbells.', 'Tip: Keep the dumbbells close to the body on the way up.', 'Tip: Finish each press with the ribs down and the glutes tight.']::text[]),
  ('Dumbbell Curl and Press', 'front-delts', 'dumbbell', 'weight_reps', 'repdb-dumbbell-curl-and-press.webp', 'repdb-dumbbell-curl-and-press-end.webp', ARRAY['Stand tall with the feet hip-width apart, holding a dumbbell in each hand at your sides with the palms facing forward.', 'Curl both dumbbells up to the shoulders, keeping the elbows close to the body.', 'Press the dumbbells overhead until the arms are fully extended.', 'Lower the dumbbells back to the shoulders under control.', 'Lower them to your sides with a controlled reverse curl, then repeat.', 'Tip: Brace the abdominals and keep the ribs down so the press does not turn into a back bend.', 'Tip: Do not swing the weights up with the legs; use a load you can curl strictly.', 'Tip: Press in a slight arc so the dumbbells finish directly over the shoulders.']::text[]),
  ('Dumbbell Overhead Carry', 'front-delts', 'dumbbell', 'weight_reps', 'repdb-db-overhead-carry.webp', null, ARRAY['Clean or press a dumbbell to a locked-out position directly above your shoulder.', 'Push the arm all the way up so the elbow is straight and the biceps is close to your ear.', 'Brace your ribs down rather than letting your lower back arch to hold the weight up.', 'Walk forward with controlled strides, keeping the dumbbell stacked over your shoulder and hip.', 'Keep your eyes forward — tipping your head back to watch the weight drags your posture with it.', 'Carry for the desired distance, lower under control, then repeat with the other arm.', 'Tip: Match the distance on both arms so the asymmetric load does not become an asymmetric adaptation.', 'Tip: A locked elbow is not optional. A soft elbow puts the whole load on the muscle instead of the skeleton and the set ends early.', 'Tip: If your ribs flare and your back arches, the weight is too heavy for your current overhead position — fix the position before adding load.']::text[]),
  ('Dumbbell Push Press', 'front-delts', 'dumbbell', 'weight_reps', 'repdb-dumbbell-push-press.webp', 'repdb-dumbbell-push-press-end.webp', ARRAY['Stand holding dumbbells at shoulder height with palms facing forward.', 'Slightly bend your knees into a quarter squat.', 'Drive through your legs to generate momentum, then press the dumbbells overhead.', 'Lock out your arms at the top.', 'Lower the dumbbells back to shoulder height with control.', 'Tip: Use a shallow dip — this is not a full squat.', 'Tip: Drive the heels into the floor to initiate the press.', 'Tip: Keep your core braced to protect the lower back.']::text[]),
  ('Dumbbell Snatch', 'front-delts', 'dumbbell', 'weight_reps', 'repdb-dumbbell-snatch.webp', 'repdb-dumbbell-snatch-end.webp', ARRAY['Stand with feet shoulder-width apart, dumbbell on the floor between your feet.', 'Hinge and grip the dumbbell with one hand.', 'Explosively extend hips, knees, and ankles to pull the dumbbell upward.', 'Punch the dumbbell overhead in one fluid motion.', 'Lock out your arm and stabilize at the top.', 'Complete reps on one side, then switch.', 'Tip: Extend your hips and knees fully before pulling with your arm.', 'Tip: Punch the dumbbell up to a stable overhead lockout.', 'Tip: Keep the dumbbell close to your body as it rises.']::text[]),
  ('EZ-Bar Front Raise', 'front-delts', 'barbell', 'weight_reps', 'repdb-ez-bar-front-raise.webp', 'repdb-ez-bar-front-raise-end.webp', ARRAY['Stand holding an EZ-bar with an overhand grip on the inner bends, arms hanging in front of the thighs.', 'Keep the elbows slightly bent and fixed throughout.', 'Raise the bar in a smooth arc up to shoulder height.', 'Pause briefly at the top, then lower under control.', 'Repeat for the recommended number of repetitions.', 'Tip: Raise and lower the bar along the same smooth arc, without swinging it away from the body.', 'Tip: Do not swing the torso; keep the core braced and the knees slightly soft.', 'Tip: Stop at shoulder height — going higher shifts tension off the front delts.']::text[]),
  ('Kettlebell Lunge Press', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-kettlebell-lunge-press.webp', 'repdb-kettlebell-lunge-press-end.webp', ARRAY['Hold a kettlebell at shoulder height with one arm.', 'Step forward into a lunge with the opposite leg.', 'As you lunge, press the kettlebell overhead.', 'Lock out the arm at the top of the press.', 'Step back to standing while lowering the kettlebell.', 'Complete reps on one side, then switch.', 'Tip: Brace your core to resist leaning toward the loaded side.', 'Tip: Keep your front knee tracking in line with your toes.', 'Tip: Avoid arching your back as you lock out overhead.']::text[]),
  ('Kettlebell Offset Reverse Lunge and Press', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-kettlebell-offset-reverse-lunge-and-press.webp', 'repdb-kettlebell-offset-reverse-lunge-and-press-end.webp', ARRAY['Hold a kettlebell at shoulder height on one side.', 'Step backward into a reverse lunge with the opposite leg.', 'As you reach the bottom of the lunge, press the kettlebell overhead.', 'Drive through your front heel to return to standing.', 'Lower the kettlebell back to shoulder height.', 'Complete reps on one side, then switch.', 'Tip: Keep your hips square as you step back into the lunge.', 'Tip: Brace your trunk to resist bending toward the loaded side.', 'Tip: Lower your back knee with control instead of dropping into the bottom.']::text[]),
  ('Kettlebell Overhead Carry', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-kettlebell-overhead-carry.webp', null, ARRAY['Clean and press a kettlebell to lockout, letting the bell settle on the back of your forearm.', 'Straighten the elbow fully and turn the arm so the bell sits behind and above your wrist rather than off to the side.', 'Keep the shoulder active: push the weight up toward the ceiling and let the shoulder blade rotate up with it rather than forcing it down.', 'Brace your trunk and walk forward with even strides, keeping the bell stacked over your shoulder and hip.', 'Keep your wrist straight; letting it bend back is what makes an overhead bell feel unstable.', 'Carry for the desired distance, lower under control, then repeat on the other side.', 'Tip: Go lighter than you would with a dumbbell. The offset mass makes the same weight noticeably harder to keep still.', 'Tip: A bent wrist is the usual failure point. If it keeps collapsing, drop the weight rather than fighting it for the whole distance.', 'Tip: Do both sides for the same distance — the unilateral load is the point of the exercise.']::text[]),
  ('Landmine Press', 'front-delts', 'barbell', 'weight_reps', 'repdb-landmine-press.webp', 'repdb-landmine-press-end.webp', ARRAY['Load one end of a barbell into a landmine attachment and load the other end with a plate.', 'Stand in a staggered or square stance and cup the sleeve end of the barbell in both hands at chest height.', 'Brace your core and press the bar forward and upward along its natural arc.', 'Fully extend your arms without locking the elbows, then lower the bar back under control.', 'Keep both hands on the bar throughout and repeat for the desired number of reps.', 'Tip: Keep your torso upright and avoid leaning excessively into the press.', 'Tip: The angled path makes it more shoulder-friendly than a strict overhead press.', 'Tip: Use a push-press leg drive for heavier loads.']::text[]),
  ('One Arm Kettlebell Push Press', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-one-arm-kettlebell-push-press.webp', 'repdb-one-arm-kettlebell-push-press-end.webp', ARRAY['Hold a kettlebell in the racked position at one shoulder.', 'Stand with feet shoulder-width apart.', 'Dip by bending your knees slightly.', 'Drive explosively through your legs and press the kettlebell overhead.', 'Lock out your arm at the top.', 'Lower the kettlebell to your shoulder with control.', 'Complete reps on one side, then switch.', 'Tip: Keep your torso upright during the dip, not tipping forward.', 'Tip: Time the press so your arm extends as your legs finish driving.', 'Tip: Keep the dip shallow and quick rather than a half squat.']::text[]),
  ('One-Arm Dumbbell Push Press', 'front-delts', 'dumbbell', 'weight_reps', 'repdb-one-arm-dumbbell-push-press.webp', 'repdb-one-arm-dumbbell-push-press-end.webp', ARRAY['Stand holding a dumbbell at one shoulder, palm facing inward (neutral).', 'Feet shoulder-width, core braced, free arm out to the side for balance.', 'Dip by bending the knees slightly, keeping the torso vertical.', 'Explosively extend the legs and press the dumbbell overhead in one motion.', 'Lock out overhead, then lower back to the shoulder under control.', 'Complete all reps on one side, then switch.', 'Tip: Drive from the legs — the arm finishes, it does not start.', 'Tip: The torso must stay upright and square; do not side-bend away from the load.', 'Tip: Lighter weight and cleaner leg drive beat heavy with a leaning torso.']::text[]),
  ('One-Arm Kettlebell Bottoms-Up Press', 'front-delts', 'kettlebell', 'weight_reps', 'repdb-one-arm-kettlebell-bottoms-up-press.webp', 'repdb-one-arm-kettlebell-bottoms-up-press-end.webp', ARRAY['Clean a light kettlebell to the rack position, then tilt it so the bell points up and the handle is at the palm.', 'Grip the handle hard; wrist absolutely straight and vertical.', 'Brace the core and press the bell straight up without letting it tip.', 'Lock out overhead with the bell still perfectly upright.', 'Lower slowly back to the rack position keeping the bell vertical the entire descent.', 'Complete all reps on one side, then switch.', 'Tip: If the bell tips, the set is over — do not fight it down.', 'Tip: Start with a very light weight; this is a skill and stability lift, not a heavy press.', 'Tip: Grip hard throughout — any loosening and the bell falls.']::text[]),
  ('Paused Incline Bench Press', 'front-delts', 'barbell', 'weight_reps', 'repdb-paused-incline-bench-press.webp', 'repdb-paused-incline-bench-press-end.webp', ARRAY['Lie on an incline bench and grip the barbell slightly wider than shoulder-width.', 'Unrack the bar and lower it to your upper chest.', 'Pause on your chest for 1-2 seconds.', 'Press the bar back up until your arms are fully extended.', 'Keep your shoulder blades retracted throughout.', 'Repeat for the desired number of reps.', 'Tip: Keep your wrists stacked over your elbows during the pause.', 'Tip: Maintain full-body tension while the bar rests on your chest.', 'Tip: Avoid bouncing the bar off your chest after the pause.']::text[]),
  ('Paused Overhead Press', 'front-delts', 'barbell', 'weight_reps', 'repdb-paused-ohp.webp', 'repdb-paused-ohp-end.webp', ARRAY['Set up with a barbell racked at shoulder height, feet shoulder-width apart, and the core braced.', 'Press the bar straight overhead until the elbows are fully locked out.', 'Lower the bar under control back down to the front of the shoulders.', 'Hold a full one-second pause at the shoulders, keeping tension and eliminating any bounce.', 'Press back up from the dead stop without using leg drive.', 'Tip: Keep the pause strict -- no rebounding the bar off the shoulders.', 'Tip: Brace hard and keep the bar path vertical over the mid-foot.', 'Tip: Use a weight you can control through the dead-stop start.']::text[]),
  ('Pike Push Ups', 'front-delts', 'bodyweight', 'bodyweight_reps', 'repdb-pike-push-ups.webp', 'repdb-pike-push-ups-end.webp', ARRAY['Start in a downward dog position with hips high and hands shoulder-width apart.', 'Walk your feet closer to your hands.', 'Bend your elbows and lower your head toward the floor.', 'Keep your hips high throughout.', 'Press back up until your arms are fully extended.', 'Repeat for the desired number of reps.', 'Tip: The higher your hips, the more the shoulders work.', 'Tip: Lower your head toward a spot slightly ahead of your hands.', 'Tip: Walk your feet closer to your hands to progress toward handstand push-ups.']::text[]),
  ('Push Jerk', 'front-delts', 'barbell', 'weight_reps', 'repdb-push-jerk.webp', 'repdb-push-jerk-end.webp', ARRAY['Hold a barbell in the front rack position at your shoulders.', 'Stand with feet hip-width apart.', 'Dip by bending your knees slightly.', 'Drive explosively through your legs and press the bar overhead.', 'Drop into a quarter-squat under the bar and lock out your arms.', 'Stand up fully and lower the bar to repeat.', 'Tip: Keep your torso upright during the dip.', 'Tip: Drive with your legs before pressing with your arms.', 'Tip: Lock your arms out as you drop under the bar.']::text[]),
  ('Seated Smith Machine Shoulder Press', 'front-delts', 'machine', 'weight_reps', 'repdb-seated-smith-machine-shoulder-press.webp', 'repdb-seated-smith-machine-shoulder-press-end.webp', ARRAY['Position a bench inside a Smith machine.', 'Sit facing forward with the bar at shoulder height.', 'Grip the bar slightly wider than shoulder-width.', 'Unrack and press the bar straight up until your arms are extended.', 'Lower the bar back to shoulder height with control.', 'Repeat for the desired number of reps.', 'Tip: Align the bench so the bar tracks just in front of your nose.', 'Tip: Brace your core to keep the lower back from over-arching.', 'Tip: Plant your feet firmly on the floor for a stable base.']::text[]),
  ('Single-Arm Machine Shoulder Press', 'front-delts', 'machine', 'weight_reps', 'repdb-single-arm-machine-shoulder-press.webp', 'repdb-single-arm-machine-shoulder-press-end.webp', ARRAY['Adjust the seat so the working handle starts around shoulder height and sit with your back firmly against the pad.', 'Grip one handle with the wrist straight and keep the free hand on the support or resting comfortably.', 'Press the handle upward without leaning away from the back pad or rotating the torso.', 'Lower the handle under control until the elbow is just below the starting line, then repeat.', 'Complete the repetitions on one side, adjust the seat if needed, and train the other side.', 'Tip: Start with the weaker arm and let it set the weight and repetitions for both sides.', 'Tip: Keep the ribs down and the back against the pad instead of leaning away from the working arm.', 'Tip: Stop short of a painful shoulder position; the machine path should feel controlled from bottom to top.']::text[]),
  ('Split Jerk', 'front-delts', 'barbell', 'weight_reps', 'repdb-split-jerk.webp', 'repdb-split-jerk-end.webp', ARRAY['Hold the barbell across your front rack with elbows high.', 'Dip straight down by bending your knees slightly.', 'Explosively drive the bar overhead with your legs and arms.', 'Split your feet forward and back as the bar locks out.', 'Stand up by bringing your feet back together under the bar.', 'Lower the bar and repeat.', 'Tip: Dip straight down rather than letting your torso tip forward.', 'Tip: Split your feet front and back as the bar locks out.', 'Tip: Bring your front foot back first when recovering.']::text[]),
  ('Straight-Bar Cable Front Raise', 'front-delts', 'cable', 'weight_reps', 'repdb-straight-bar-cable-front-raise.webp', 'repdb-straight-bar-cable-front-raise-end.webp', ARRAY['Attach a straight bar to a low cable pulley and stand facing away from the machine with the cable running forward past your legs.', 'Hold the bar with an overhand grip, hands about shoulder-width apart, arms hanging straight down in front of your thighs.', 'Keep the elbows almost straight and the core braced so the torso does not lean back.', 'Raise the bar forward in a smooth arc until it reaches shoulder height.', 'Lower it under control back to the thighs and repeat for the desired number of repetitions.', 'Tip: Use a light weight — swinging the bar up with the legs or leaning back takes the work off the front delts.', 'Tip: Stop at shoulder height; raising the bar higher shifts the load onto the traps.', 'Tip: Keep the wrists neutral rather than letting them bend back under the bar.']::text[]),
  ('Thruster', 'front-delts', 'barbell', 'weight_reps', 'repdb-thruster.webp', 'repdb-thruster-end.webp', ARRAY['Hold a barbell in a front rack position with elbows high.', 'Stand with feet shoulder-width apart.', 'Squat down to parallel while keeping your torso upright.', 'Drive up out of the squat and press the bar overhead in one motion.', 'Lock out your arms at the top with the bar overhead.', 'Lower the bar back to the front rack and repeat.', 'Tip: Use the momentum from the squat drive to launch the press.', 'Tip: Keep your elbows high so the bar rests on your shoulders, not your wrists.', 'Tip: Finish each rep with the bar locked out over your ears.']::text[]),
  ('Bodyweight Lateral Raise', 'side-delts', 'bodyweight', 'bodyweight_reps', 'repdb-bodyweight-lateral-raise.webp', 'repdb-bodyweight-lateral-raise-end.webp', ARRAY['Stand upright with arms hanging at your sides.', 'Raise both arms out to the sides with a slight elbow bend until parallel with the floor.', 'Pause briefly at the top.', 'Lower slowly back to the starting position.', 'Repeat for the desired reps.', 'Tip: Lead with your elbows, not your hands.', 'Tip: Avoid shrugging your shoulders at the top.', 'Tip: Control the descent to maximize time under tension.']::text[]),
  ('Dumbbell Windmill', 'side-delts', 'dumbbell', 'weight_reps', 'repdb-dumbbell-windmill.webp', 'repdb-dumbbell-windmill-end.webp', ARRAY['Stand with feet shoulder-width apart, holding a dumbbell overhead in one hand, arm locked.', 'Turn your feet slightly away from the dumbbell side, keeping the arm straight and eyes on the weight.', 'Hinge at your hips, pushing them out to the side of the dumbbell, and slowly lower your torso towards the floor.', 'Keep your back straight and the dumbbell arm vertical as you reach your free hand towards your foot or the floor.', 'Reverse the motion by driving through your hips and obliques to return to the starting position.', 'Complete all reps on one side, then switch and repeat for the other side.', 'Tip: Maintain a tight core throughout the movement to protect your spine and enhance stability.', 'Tip: Keep your eyes fixed on the dumbbell overhead to help maintain balance and a straight arm.', 'Tip: Focus on hinging at the hips, not rounding your back, to engage the hamstrings and glutes.', 'Tip: Start with a light weight to master the form before progressing to heavier loads.']::text[]),
  ('EZ-Bar Upright Row', 'side-delts', 'barbell', 'weight_reps', 'repdb-ez-bar-upright-row.webp', 'repdb-ez-bar-upright-row-end.webp', ARRAY['Stand holding an EZ-bar with a shoulder-width grip on the angled portions.', 'Pull the bar straight up along your body toward your chin.', 'Lead with your elbows, keeping them above your hands.', 'Lower with control.', 'Repeat.', 'Tip: Pull only as high as your shoulders allow without pinching.', 'Tip: Keep the bar close to your body throughout the movement.', 'Tip: Avoid swinging or using your legs to lift the weight.']::text[]),
  ('Kettlebell Halo', 'side-delts', 'kettlebell', 'weight_reps', 'repdb-kettlebell-halo.webp', 'repdb-kettlebell-halo-end.webp', ARRAY['Stand tall, core braced, holding a light kettlebell by the horns (upside down) at chest height.', 'Raise the bell to one side of your head and pass it around the back in a smooth circle.', 'Bring it back to the starting position in front of your face.', 'Reverse direction every few reps.', 'Repeat for the recommended number of repetitions or time.', 'Tip: Light weight only — this is mobility, not strength.', 'Tip: Keep the head stationary; the bell goes around, not the head.', 'Tip: If the bell drifts wide, shrink the circle — tight orbit, close to the skull.']::text[]),
  ('Muscle Snatch', 'side-delts', 'barbell', 'weight_reps', 'repdb-muscle-snatch.webp', 'repdb-muscle-snatch-end.webp', ARRAY['Stand with feet hip-width apart and grip the bar wide with a hook grip.', 'Pull the bar explosively from the floor, keeping it close to your body.', 'Shrug hard and pull the bar overhead without dipping under.', 'Lock out the bar overhead with straight arms.', 'Lower the bar under control to the starting position.', 'Repeat for the desired number of reps.', 'Tip: Shrug hard and keep pulling the bar up high.', 'Tip: Stay tall; do not dip under the bar to catch it.', 'Tip: Keep the bar close to your body throughout the pull.']::text[]),
  ('Plate-Loaded Lateral Raise', 'side-delts', 'machine', 'weight_reps', 'repdb-plate-loaded-lateral-raise.webp', 'repdb-plate-loaded-lateral-raise-end.webp', ARRAY['Set the seat height so that the pivot of the arm pads lines up with the point of your shoulders when you sit down.', 'Load the plate horns evenly on both sides and sit with your back flat against the pad.', 'Place the outside of your upper arms against the pads with your elbows bent and your arms hanging down.', 'Push out and up against the pads until your upper arms are roughly level with your shoulders.', 'Lower under control until your arms are back at your sides, and repeat for the desired number of repetitions.', 'Tip: Set the seat first. If the pivot sits below your shoulder the pads drive your arm across your body instead of out to the side, and the side deltoid stops being the muscle doing the work.', 'Tip: Push with the arm, not the hand. The handles are there to stop your arms sliding off the pads -- gripping hard pulls the biceps and forearms into a raise that should be all deltoid.', 'Tip: Stop at shoulder height. Going higher hands the last part of the rep to the traps, and the machine will happily let you.']::text[]),
  ('Side-Lying Lateral Raise', 'side-delts', 'dumbbell', 'weight_reps', 'repdb-side-lying-lateral-raise.webp', 'repdb-side-lying-lateral-raise-end.webp', ARRAY['Lie on your side on a flat bench with your bottom arm supporting your head or gripping the bench edge.', 'Hold a dumbbell in your top hand with your arm resting along your side.', 'Keeping your elbow slightly bent, raise the dumbbell upward until your arm is perpendicular to the floor.', 'Pause briefly at the top, then lower the dumbbell slowly back to your side.', 'Complete all reps on one side before switching.', 'Tip: Keep your torso still — only the working arm should move.', 'Tip: The lying position removes momentum and isolates the lateral deltoid effectively.', 'Tip: Use a lighter weight than your standing lateral raise — the leverage is more challenging.']::text[]),
  ('Single-Arm Plate-Loaded Lateral Raise', 'side-delts', 'machine', 'weight_reps', 'repdb-single-arm-plate-loaded-lateral-raise.webp', 'repdb-single-arm-plate-loaded-lateral-raise-end.webp', ARRAY['Set the seat height so the pad pivot lines up with your shoulder, and load only the side you are about to work.', 'Sit with your back flat against the pad and place the outside of your working upper arm against its pad.', 'Hold the handle on the free side or rest that hand in your lap, and keep your torso square to the seat.', 'Push the working arm out and up against the pad until the upper arm is level with your shoulder, then lower it under control.', 'Complete all the repetitions on that side, then load and work the other side.', 'Tip: Match the sides on the weaker arm, not the stronger one. Working one side at a time only tells you about an imbalance if you let the weaker side set the number.', 'Tip: Do not let the torso tip toward the working side. With load on one arm only, the machine no longer balances itself and leaning turns the raise into a side bend.', 'Tip: Start with the weaker arm so it sets the target, and give both sides the same rest.']::text[]),
  ('Smith Machine Upright Row', 'side-delts', 'machine', 'weight_reps', 'repdb-smith-machine-upright-row.webp', 'repdb-smith-machine-upright-row-end.webp', ARRAY['Set the bar at hip height, take an overhand grip a little wider than shoulder-width and stand close to it with your arms straight.', 'Unrack the bar and stand tall with your shoulders back and your core braced.', 'Pull the bar straight up the front of your body, leading with your elbows and keeping the bar close.', 'Stop when the bar reaches your lower chest and your elbows are level with your shoulders, then pause briefly.', 'Lower the bar under control until your arms are straight again, and repeat for the desired reps.', 'Tip: Stop at chest height. Pulling the bar to the collarbone rotates the shoulder into the position that causes the impingement this exercise is known for.', 'Tip: Lead with the elbows, not the hands. If the wrists come up first the biceps take over and the side deltoids barely work.', 'Tip: Widen the grip if the movement pinches. A narrow grip forces more internal rotation, and the fixed bar path gives you nowhere else to go.']::text[]),
  ('Double Kettlebell Rear Delt Row', 'rear-delts', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-rear-delt-row.webp', 'repdb-double-kettlebell-rear-delt-row-end.webp', ARRAY['Stand a kettlebell just outside each foot with your feet about hip-width apart.', 'Hinge at the hips with a flat back until your torso is close to parallel with the floor, letting your knees bend slightly.', 'Take both handles with an overhand grip and let your arms hang straight down from your shoulders.', 'Row both bells up by driving your elbows out to the sides, away from your ribs rather than back along them.', 'Stop when your upper arms are roughly in line with your shoulders, and squeeze your shoulder blades together.', 'Lower the bells under control until your arms hang straight again, and repeat for the desired reps.', 'Tip: The wide elbow is the whole exercise. Let it drift in against your ribs and you are doing an ordinary double kettlebell row, training your lats instead of your rear delts.', 'Tip: Use less weight than you would for a normal row. The flared elbow is a long lever and the rear delts are a far smaller engine than the lats.', 'Tip: Hold the hinge angle steady. Standing up as you pull hands the work to the traps and lower back and shortens the range where the rear delts actually work.']::text[]),
  ('Dumbbell Face Pull', 'rear-delts', 'dumbbell', 'weight_reps', 'repdb-dumbbell-face-pull.webp', 'repdb-dumbbell-face-pull-end.webp', ARRAY['Stand or sit holding a dumbbell in each hand with arms extended forward.', 'Bend your elbows and pull the dumbbells toward your face.', 'Flare your elbows out wide to shoulder height.', 'Squeeze your rear delts and upper back at the peak.', 'Lower the dumbbells back under control.', 'Repeat for the desired number of reps.', 'Tip: Lead with your elbows, not your hands.', 'Tip: Keep your upper arms roughly parallel to the floor.', 'Tip: Use a lighter weight to prioritize form over load.']::text[]),
  ('Dumbbell Reverse Fly', 'rear-delts', 'dumbbell', 'weight_reps', 'repdb-dumbbell-reverse-fly.webp', 'repdb-dumbbell-reverse-fly-end.webp', ARRAY['Hinge forward at the hips holding dumbbells with arms hanging down.', 'Keep your back flat and knees slightly bent.', 'Raise the dumbbells out to the sides until level with your shoulders.', 'Squeeze your shoulder blades together at the top.', 'Lower the dumbbells back with control.', 'Repeat for the desired number of reps.', 'Tip: Use a light weight so the rear delts do the work, not momentum.', 'Tip: Squeeze your shoulder blades together at the top.', 'Tip: Keep a soft, fixed bend in your elbows throughout.']::text[]),
  ('Ring Face Pull', 'rear-delts', 'bodyweight', 'bodyweight_reps', 'repdb-ring-face-pull.webp', 'repdb-ring-face-pull-end.webp', ARRAY['Grip the rings and lean back so your body is at an angle.', 'Pull the rings toward your face, flaring elbows to the sides.', 'Hold briefly, then return.', 'Repeat.', 'Tip: Adjust your body angle to control difficulty.', 'Tip: Externally rotate your arms at the top.']::text[]),
  ('TRX Face Pull', 'rear-delts', 'bodyweight', 'bodyweight_reps', 'repdb-trx-face-pull.webp', 'repdb-trx-face-pull-end.webp', ARRAY['Grasp the TRX handles with an overhand grip, palms facing down.', 'Lean back until your arms are fully extended and your body forms a straight line.', 'Pull the handles towards your face, driving your elbows high and wide.', 'Squeeze your shoulder blades together at the peak contraction.', 'Slowly extend your arms back to the starting position with control.', 'Tip: Maintain a rigid torso throughout the movement; avoid arching your lower back.', 'Tip: Focus on initiating the pull with your upper back muscles, not just your arms.', 'Tip: Adjust your body angle to modify difficulty: a more horizontal position is harder.']::text[]),
  ('TRX Y-Fly', 'rear-delts', 'bodyweight', 'bodyweight_reps', 'repdb-trx-y-fly.webp', 'repdb-trx-y-fly-end.webp', ARRAY['Stand facing the anchor point, holding the handles with an overhand grip, palms facing down.', 'Lean back, extending your arms straight in front of you, maintaining a plank position with your body.', 'Raise your arms up and out into a ''Y'' overhead, pulling your shoulder blades together and down as your body rises toward the anchor.', 'Keep a slight, fixed bend in the elbows throughout and squeeze your shoulder blades at the top.', 'Slowly control the descent back to the starting position, resisting the pull of the straps.', 'Tip: Adjust your body angle to modify difficulty: leaning further back increases the challenge.', 'Tip: Focus on retracting and depressing your shoulder blades throughout the movement.', 'Tip: Maintain a rigid core and straight body line to prevent sagging hips.']::text[]),
  ('Cheat Curl', 'biceps', 'barbell', 'weight_reps', 'repdb-cheat-curl.webp', 'repdb-cheat-curl-end.webp', ARRAY['Stand holding weight at thigh level with an underhand grip.', 'Use a slight hip drive to start the curl.', 'Curl the weight up toward your shoulders explosively.', 'Lower the weight slowly under control through the full range.', 'Repeat for the desired number of reps.', 'Tip: Keep the hip drive small so your biceps still do most of the work.', 'Tip: Avoid leaning back excessively to protect your lower back.', 'Tip: Keep your elbows close to your torso throughout the curl.']::text[]),
  ('Close-Grip Barbell Curl', 'biceps', 'barbell', 'weight_reps', 'repdb-close-grip-barbell-curl.webp', 'repdb-close-grip-barbell-curl-end.webp', ARRAY['Stand holding a barbell with an underhand grip, hands closer than shoulder-width apart.', 'Start with the bar at the thighs, arms extended, elbows tucked to the sides.', 'Curl the bar up to the shoulders by flexing the elbows.', 'Squeeze the biceps at the top, then lower under control.', 'Repeat for the recommended number of repetitions.', 'Tip: Keep the elbows pinned to the sides — do not let them drift forward.', 'Tip: If the narrow grip bothers your wrists, use an EZ-bar.']::text[]),
  ('Close-Grip EZ-Bar Curl', 'biceps', 'barbell', 'weight_reps', 'repdb-close-grip-ez-bar-curl.webp', 'repdb-close-grip-ez-bar-curl-end.webp', ARRAY['Stand holding an EZ-bar with hands on the inner bends, palms up.', 'Keep the elbows tucked at the sides.', 'Curl the bar up to shoulder level, squeezing the biceps.', 'Lower under control to a full stretch.', 'Repeat for the prescribed reps.', 'Tip: Keep the elbows pinned — do not let them flare forward.', 'Tip: Squeeze hard at the top.', 'Tip: Avoid swinging the torso for momentum.']::text[]),
  ('Close-Grip Pull-Ups', 'biceps', 'bodyweight', 'bodyweight_reps', 'repdb-close-grip-pull-ups.webp', 'repdb-close-grip-pull-ups-end.webp', ARRAY['Hang from a pull-up bar with hands shoulder-width or narrower, palms away.', 'Pull yourself up until chin clears the bar.', 'Lower under control.', 'Repeat.', 'Tip: The narrow grip increases biceps involvement.', 'Tip: Avoid kipping for strength development.']::text[]),
  ('Commando Pull-Up', 'biceps', 'bodyweight', 'bodyweight_reps', 'repdb-commando-pull-up.webp', 'repdb-commando-pull-up-end.webp', ARRAY['Grip the bar with the hands one in front of the other, palms facing each other, and hang with the arms straight and the body turned sideways.', 'Brace the trunk and pull the shoulder blades down to start the movement.', 'Pull yourself up, driving the elbows down, until your head clears the bar on one side of it.', 'Pause briefly at the top with the chest close to the bar.', 'Lower under control to a full hang.', 'Take the head to the other side of the bar on the next repetition, or swap the hand positions each set.', 'Tip: Keep the legs and trunk still; swinging turns the pull into a kip.', 'Tip: Alternate the sides evenly so both arms and lats do the same work.', 'Tip: Start with a few repetitions per set: the staggered grip is harder than a regular pull-up.']::text[]),
  ('Double Kettlebell Bicep Curl', 'biceps', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-bicep-curl.webp', 'repdb-double-kettlebell-bicep-curl-end.webp', ARRAY['Stand holding a kettlebell in each hand by the handle, palms facing forward.', 'Keep the elbows tucked to the sides and the bells hanging at arm length.', 'Curl both kettlebells up toward the shoulders by flexing the elbows.', 'Squeeze the biceps at the top, then lower under control to the starting position.', 'Repeat for the recommended number of repetitions.', 'Tip: Do not let the bells swing — control the eccentric.', 'Tip: Elbows stay pinned to the sides; no shoulder flexion.', 'Tip: Grip hard throughout; the bell wants to pull the wrist into extension.']::text[]),
  ('Dumbbell Reverse Curl', 'biceps', 'dumbbell', 'weight_reps', 'repdb-db-reverse-curl.webp', 'repdb-db-reverse-curl-end.webp', ARRAY['Hold dumbbells with an overhand grip at your sides.', 'Curl them up to shoulder height.', 'Lower under control.', 'Repeat.', 'Tip: Keep wrists neutral throughout.', 'Tip: Controlled movement is key.']::text[]),
  ('EZ Bar Reverse Grip Row', 'biceps', 'barbell', 'weight_reps', 'repdb-ez-bar-reverse-grip-row.webp', 'repdb-ez-bar-reverse-grip-row-end.webp', ARRAY['Stand with feet shoulder-width apart, holding an EZ bar with an underhand, shoulder-width grip.', 'Hinge at your hips, keeping a slight bend in your knees and your back straight, until your torso is nearly parallel to the floor.', 'Let the bar hang directly below your shoulders with arms fully extended.', 'Pull the bar towards your lower abdomen, squeezing your shoulder blades together and driving your elbows up.', 'Control the eccentric phase, slowly lowering the bar back to the starting position with full arm extension.', 'Tip: Maintain a neutral spine throughout the movement to protect your lower back.', 'Tip: Focus on initiating the pull with your lats, not just your biceps.', 'Tip: Avoid shrugging your shoulders; keep them depressed and retracted.', 'Tip: Use a full range of motion, extending your arms completely at the bottom.']::text[]),
  ('EZ-Bar Reverse Curl', 'biceps', 'barbell', 'weight_reps', 'repdb-ez-bar-reverse-curl.webp', 'repdb-ez-bar-reverse-curl-end.webp', ARRAY['Hold an EZ-bar with an overhand grip.', 'Curl the bar up toward your shoulders.', 'Lower under control.', 'Repeat.', 'Tip: Keep elbows close to your torso.', 'Tip: The EZ-bar reduces wrist strain.']::text[]),
  ('Flexed Arm Hang', 'biceps', 'bodyweight', 'duration', 'repdb-flexed-arm-hang.webp', null, ARRAY['Grip a pull-up bar with the palms facing away, a little wider than shoulder-width, or facing you for an easier version.', 'Pull yourself up, or step up on a box, until the chin is above the bar.', 'Keep the elbows bent and pointing down, with the shoulders pulled away from the ears.', 'Hold the position without swinging, keeping the legs together and the trunk tight.', 'Lower slowly to a full hang when the chin begins to drop.', 'Tip: Keep the chin clearly above the bar; once it drops below, the hold is over.', 'Tip: Squeeze the bar and pull the shoulder blades down and back.', 'Tip: Step up to the top position rather than jumping if you cannot yet pull up.']::text[]),
  ('Kettlebell Concentration Curl', 'biceps', 'kettlebell', 'weight_reps', 'repdb-kettlebell-concentration-curl.webp', 'repdb-kettlebell-concentration-curl-end.webp', ARRAY['Sit on a bench with your feet wide, holding a kettlebell in one hand.', 'Brace the back of your upper arm against the inside of your thigh, letting the kettlebell hang.', 'Curl the kettlebell up toward your shoulder, keeping the elbow pinned against your leg.', 'Squeeze the bicep at the top, then lower slowly under control.', 'Finish all reps on one side, then switch arms.', 'Tip: Keep the upper arm braced and still -- only the forearm moves.', 'Tip: Rotate the wrist slightly as you curl for a stronger peak contraction.', 'Tip: Use a lighter weight than a standard curl -- strict form matters more here.']::text[]),
  ('Kettlebell Curl', 'biceps', 'kettlebell', 'weight_reps', 'repdb-kettlebell-curl.webp', 'repdb-kettlebell-curl-end.webp', ARRAY['Stand with your feet about shoulder-width apart and hold the kettlebell by its handle with both hands, so it hangs in front of your thighs.', 'Keep your elbows close to your sides, your chest tall and your shoulders relaxed.', 'Bend your elbows and curl the kettlebell up toward your chest without letting your upper arms swing forward.', 'Squeeze your biceps at the top, with the kettlebell close to your chest.', 'Lower the kettlebell slowly until your arms are straight again, keeping control of the swing of the bell.', 'Repeat for the planned repetitions.', 'Tip: Hold the handle firmly with both hands and keep your wrists straight, so the kettlebell does not roll or tilt.', 'Tip: Do not lean back or swing your hips to lift the kettlebell; if you have to, the weight is too heavy.', 'Tip: Take about twice as long to lower the kettlebell as to lift it, so the biceps work through the whole descent.']::text[]),
  ('Kettlebell Hammer Curl', 'biceps', 'kettlebell', 'weight_reps', 'repdb-kettlebell-hammer-curl.webp', 'repdb-kettlebell-hammer-curl-end.webp', ARRAY['Stand holding a kettlebell in each hand, gripping the handles in a neutral position (palms facing the body).', 'Let the bells hang below your hands.', 'Keep the elbows tucked to the sides and curl both bells up toward the shoulders.', 'Squeeze at the top, then lower under control.', 'Repeat for the planned number of reps.', 'Tip: Control the offset mass — the bells want to rotate at the bottom of the ROM.', 'Tip: Elbows stay still; only the forearms move.', 'Tip: Light load — this biases brachialis, not peak bicep size.']::text[]),
  ('One Arm Dumbbell Preacher Curl', 'biceps', 'dumbbell', 'weight_reps', 'repdb-one-arm-dumbbell-preacher-curl.webp', 'repdb-one-arm-dumbbell-preacher-curl-end.webp', ARRAY['Sit at a preacher bench and rest the back of one upper arm flat on the pad.', 'Hold a dumbbell in that hand with the palm facing up and the arm almost fully extended.', 'Curl the dumbbell toward the shoulder without lifting the elbow off the pad.', 'Squeeze the biceps at the top of the movement.', 'Lower the dumbbell slowly until the arm is almost straight.', 'Complete the repetitions, then switch arms.', 'Tip: Stop just short of lockout at the bottom to keep tension on the biceps and spare the elbow.', 'Tip: Keep the shoulder relaxed and the chest against the pad.', 'Tip: Lower the weight more slowly than you lift it.']::text[]),
  ('One Arm Kettlebell Bicep Curl', 'biceps', 'kettlebell', 'weight_reps', 'repdb-one-arm-kettlebell-bicep-curl.webp', 'repdb-one-arm-kettlebell-bicep-curl-end.webp', ARRAY['Stand tall holding a kettlebell in one hand.', 'Keep your elbow pinned to your side.', 'Curl the kettlebell toward your shoulder by flexing your bicep.', 'Squeeze at the top of the movement.', 'Lower the kettlebell with control.', 'Complete reps on one side, then switch.', 'Tip: Keep your wrist straight as the offset weight shifts through the curl.', 'Tip: Brace your core to resist leaning away from the working side.', 'Tip: Avoid swinging the kettlebell up with your hips.']::text[]),
  ('Preacher Curl', 'biceps', 'barbell', 'weight_reps', 'repdb-preacher-curl.webp', 'repdb-preacher-curl-end.webp', ARRAY['Sit at a preacher bench with your upper arms resting on the pad.', 'Hold an EZ-bar with an underhand grip.', 'Curl the bar up toward your shoulders.', 'Lower with control until arms are nearly straight.', 'Repeat.', 'Tip: Avoid bouncing at the bottom to protect the biceps tendon.', 'Tip: Keep your wrists neutral rather than letting them bend back.', 'Tip: Don''t shrug your shoulders as the bar rises.']::text[]),
  ('Preacher Hammer Curl', 'biceps', 'dumbbell', 'weight_reps', 'repdb-preacher-hammer-curl.webp', 'repdb-preacher-hammer-curl-end.webp', ARRAY['Sit at a preacher bench with a dumbbell in each hand.', 'Rest your upper arms on the pad with palms facing each other.', 'Curl the dumbbells up while keeping your wrists neutral.', 'Squeeze your biceps at the top of the movement.', 'Lower the dumbbells with control.', 'Repeat for the desired number of reps.', 'Tip: Keep your upper arms flat against the pad.', 'Tip: Avoid locking out the elbows completely at the bottom.', 'Tip: Control the lowering phase rather than dropping the weight.']::text[]),
  ('Seated Dumbbell Curl', 'biceps', 'dumbbell', 'weight_reps', 'repdb-seated-dumbbell-curl.webp', 'repdb-seated-dumbbell-curl-end.webp', ARRAY['Sit on a bench with a dumbbell in each hand.', 'Let your arms hang at your sides with palms facing forward.', 'Curl both dumbbells toward your shoulders by flexing your biceps.', 'Squeeze at the top of the movement.', 'Lower the dumbbells with control.', 'Repeat for the desired number of reps.', 'Tip: Keep your elbows pinned at your sides throughout.', 'Tip: Avoid leaning back to help lift the weight.', 'Tip: Straighten your arms fully at the bottom of each rep.']::text[]),
  ('Single-Arm Hammer Curl', 'biceps', 'dumbbell', 'weight_reps', 'repdb-single-arm-hammer-curl.webp', 'repdb-single-arm-hammer-curl-end.webp', ARRAY['Stand with your feet about hip-width apart and hold one dumbbell at your side with the palm facing inward.', 'Brace your trunk and keep the working upper arm beside your ribs as the arm hangs straight.', 'Curl the dumbbell toward your shoulder without rotating the palm or swinging the torso.', 'Squeeze the elbow flexors at the top, then lower the dumbbell under control until the arm is straight.', 'Complete the repetitions on one side, then switch arms and repeat.', 'Tip: Let the weaker arm set the repetitions and weight so both sides receive the same work.', 'Tip: Keep the wrist neutral and the shoulder quiet; the movement should come from bending the elbow.', 'Tip: Use a controlled lowering phase instead of dropping the dumbbell from the top.']::text[]),
  ('Smith Machine Reverse Grip Bent Over Row', 'biceps', 'machine', 'weight_reps', 'repdb-smith-machine-reverse-grip-bent-over-row.webp', 'repdb-smith-machine-reverse-grip-bent-over-row-end.webp', ARRAY['Stand inside a Smith machine and grip the bar with an underhand grip.', 'Hinge forward at the hips until your torso is about 45 degrees.', 'Keep your back flat and core braced.', 'Pull the bar toward your lower abdomen.', 'Squeeze your lats and shoulder blades at the top.', 'Lower the bar under control and repeat.', 'Tip: Keep your wrists straight under the underhand grip.', 'Tip: Drive your elbows back close to your sides.', 'Tip: Avoid rising out of the hinge to cheat the bar up.']::text[]),
  ('Spider Curl', 'biceps', 'dumbbell', 'weight_reps', 'repdb-spider-curl.webp', 'repdb-spider-curl-end.webp', ARRAY['Lie face down on an incline bench with arms hanging straight down.', 'Hold a dumbbell in each hand with an underhand grip.', 'Keep your upper arms vertical as you curl the weights up.', 'Squeeze the biceps hard at the top.', 'Lower the dumbbells under control to full extension.', 'Repeat for the desired number of reps.', 'Tip: Keep your chest glued to the pad for the whole set.', 'Tip: Squeeze at the top without letting the elbows drift backward.', 'Tip: Use the full range — the stretch at the bottom is half the value.']::text[]),
  ('Strict Curl', 'biceps', 'dumbbell', 'weight_reps', 'repdb-strict-curl.webp', 'repdb-strict-curl-end.webp', ARRAY['Stand tall with a dumbbell in each hand, arms at your sides and palms facing forward.', 'Pin your elbows against your sides and brace your core so your torso cannot swing.', 'Curl both dumbbells up by bending only at the elbows.', 'Lower them under control until your arms are straight.', 'Repeat for the desired number of reps.', 'Tip: Standing with your back against a wall or post is a useful self-check — if your shoulders or hips leave it, you are using momentum.', 'Tip: Keep the elbows from drifting forward; the upper arms should stay vertical throughout.', 'Tip: Lower slower than you lift — the strict version lives in the descent.']::text[]),
  ('TRX Bicep Curl', 'biceps', 'bodyweight', 'bodyweight_reps', 'repdb-trx-bicep-curl.webp', 'repdb-trx-bicep-curl-end.webp', ARRAY['Adjust the suspension trainer straps to a medium length.', 'Stand facing the anchor point, grasp the handles with an underhand grip, and lean back until your arms are fully extended.', 'Keep your body straight and core engaged, pull your chest towards your hands by bending your elbows.', 'Squeeze your biceps at the top of the movement.', 'Slowly extend your arms back to the starting position, controlling the descent.', 'Maintain tension throughout the set.', 'Tip: Adjust your body angle to increase or decrease difficulty; leaning further back makes it harder.', 'Tip: Keep your elbows high and fixed to isolate the biceps effectively.', 'Tip: Avoid swinging your body or using momentum; focus on a controlled contraction.', 'Tip: Ensure a full range of motion, from full extension to a strong peak contraction.']::text[]),
  ('Barbell Overhead Extension', 'triceps', 'barbell', 'weight_reps', 'repdb-barbell-overhead-extension.webp', 'repdb-barbell-overhead-extension-end.webp', ARRAY['Load a barbell with an appropriate weight and stand or sit with a neutral spine.', 'Grip the barbell with an overhand, shoulder-width grip, and press it overhead.', 'Slowly lower the barbell behind your head by flexing your elbows, keeping your upper arms stable.', 'Extend your elbows to press the barbell back to the starting overhead position, squeezing your triceps.', 'Maintain control throughout the movement, avoiding momentum.', 'Tip: Keep your elbows tucked in and pointing forward to maximize triceps engagement and protect your shoulders.', 'Tip: Control the eccentric (lowering) phase to enhance muscle tension and growth.', 'Tip: Avoid arching your lower back excessively; brace your core to maintain stability.']::text[]),
  ('Cable Tricep Kickback', 'triceps', 'cable', 'weight_reps', 'repdb-cable-tricep-kickback.webp', 'repdb-cable-tricep-kickback-end.webp', ARRAY['Attach a handle to a low cable and hinge forward at the hips.', 'Tuck your upper arm against your side with elbow bent 90 degrees.', 'Extend your elbow to push the handle back behind you.', 'Squeeze your triceps at the end of the movement.', 'Return under control. Complete reps on one side, then switch.', 'Tip: Move only your forearm; keep the upper arm completely still.', 'Tip: Avoid rounding your back while holding the hinged position.', 'Tip: Use a light weight to reach full lockout without swinging.']::text[]),
  ('Close-Grip EZ-Bar Bench Press', 'triceps', 'barbell', 'weight_reps', 'repdb-close-grip-ez-bar-bench-press.webp', 'repdb-close-grip-ez-bar-bench-press-end.webp', ARRAY['Lie on a flat bench and grip the inner curves of the EZ-bar.', 'Lower the bar to your chest with elbows tucked.', 'Press back up to full extension.', 'Repeat.', 'Tip: The EZ-bar reduces wrist discomfort.', 'Tip: Keep the movement controlled.']::text[]),
  ('Close-Grip Incline Bench Press', 'triceps', 'barbell', 'weight_reps', 'repdb-close-grip-incline-bench.webp', 'repdb-close-grip-incline-bench-end.webp', ARRAY['Set bench to an incline. Grip the barbell with hands shoulder-width or closer.', 'Lower the bar to your upper chest.', 'Press back up.', 'Repeat.', 'Tip: The incline increases the stretch on the long head of the triceps.', 'Tip: Tuck elbows to keep the focus on triceps.']::text[]),
  ('Crab Dips', 'triceps', 'bodyweight', 'bodyweight_reps', 'repdb-crab-dips.webp', 'repdb-crab-dips-end.webp', ARRAY['Sit with the knees bent, the feet flat and the hands on the floor behind you, fingers pointing towards the heels.', 'Press into the hands and feet and lift the hips until the trunk is roughly level with the knees.', 'Bend the elbows straight back to lower the hips towards the floor without sitting down.', 'Push back up until the arms are straight, keeping the hips lifted.', 'Repeat for the desired number of repetitions and lower the hips to finish.', 'Tip: Keep the elbows pointing back, not flaring out to the sides.', 'Tip: Hold the hips high the whole set; letting them drop turns it into a rest.', 'Tip: Walk the feet further away for a longer lever and more triceps work.']::text[]),
  ('Dumbbell Skull Crusher', 'triceps', 'dumbbell', 'weight_reps', 'repdb-db-skull-crusher.webp', 'repdb-db-skull-crusher-end.webp', ARRAY['Lie on a flat bench holding dumbbells over your chest.', 'Lower the dumbbells toward the sides of your head.', 'Extend your arms back up.', 'Repeat.', 'Tip: Keep elbows pointing toward the ceiling.', 'Tip: Use a controlled tempo.']::text[]),
  ('Dumbbell Tricep Extension', 'triceps', 'dumbbell', 'weight_reps', 'repdb-dumbbell-tricep-extension.webp', 'repdb-dumbbell-tricep-extension-end.webp', ARRAY['Stand holding a dumbbell in each hand with your arms extended overhead.', 'Lower the dumbbells behind your head by bending your elbows.', 'Extend your arms back to the starting position.', 'Keep your elbows close to your head.', 'Repeat for the planned number of reps.', 'Tip: Move only your forearms, keeping the upper arms still.', 'Tip: Brace your core to avoid arching your lower back.', 'Tip: Choose a weight light enough to reach a full stretch.']::text[]),
  ('EZ-Bar Lying Triceps Extension', 'triceps', 'barbell', 'weight_reps', 'repdb-ez-bar-lying-tricep-extension.webp', 'repdb-ez-bar-lying-tricep-extension-end.webp', ARRAY['Lie on a flat bench holding an EZ bar over your chest with a narrow grip.', 'Lower the bar toward your forehead by bending at the elbows.', 'Extend your arms back to the start.', 'Repeat.', 'Tip: Keep your upper arms vertical throughout so the triceps do the work.', 'Tip: The EZ bar''s angled grip is easier on the wrists than a straight bar.', 'Tip: Lower slowly to protect the elbows.']::text[]),
  ('EZ-Bar Overhead Tricep Extension', 'triceps', 'barbell', 'weight_reps', 'repdb-ez-bar-overhead-extension.webp', 'repdb-ez-bar-overhead-extension-end.webp', ARRAY['Stand or sit holding an EZ-bar overhead with an overhand grip on the inner bends.', 'Arms fully extended, bar above the head.', 'Bend only the elbows to lower the bar behind the head in an arc.', 'Keep the upper arms vertical and close to the head; only the forearms move.', 'Extend the elbows to return the bar overhead.', 'Repeat for the recommended number of repetitions.', 'Tip: If the elbows flare out, drop the load — flared elbows mean shoulders are assisting.', 'Tip: The deeper the stretch at the bottom, the better the long-head hypertrophy stimulus.', 'Tip: A seated version is easier on the lower back.']::text[]),
  ('Kettlebell Close-Grip Floor Press', 'triceps', 'kettlebell', 'weight_reps', 'repdb-kettlebell-close-grip-floor-press.webp', 'repdb-kettlebell-close-grip-floor-press-end.webp', ARRAY['Lie on your back on the floor with the knees bent and feet flat.', 'Hold a single kettlebell by the handle with both hands, close together, the bell resting on the chest with elbows tucked tight to the ribs.', 'Brace the core and press the kettlebell straight up until the arms are fully extended.', 'Lower under control until the upper arms touch the floor and pause briefly.', 'Press back up to lockout.', 'Repeat for the recommended number of repetitions.', 'Tip: Keep the elbows tucked at roughly 30–45 degrees from the torso — wide elbows turn it into a chest press.', 'Tip: The brief pause when the elbows touch the floor kills the bounce and forces a clean concentric.', 'Tip: Pick a bell you can control with two hands; the narrow grip is unforgiving if it tips.']::text[]),
  ('Kettlebell Overhead Tricep Extension', 'triceps', 'kettlebell', 'weight_reps', 'repdb-kettlebell-overhead-tricep-extension.webp', 'repdb-kettlebell-overhead-tricep-extension-end.webp', ARRAY['Stand or sit holding a kettlebell by the horns (upside down) with both hands overhead.', 'Arms fully extended, bell above the head.', 'Bend only the elbows to lower the bell behind the head in a controlled arc.', 'Keep the upper arms vertical and close to the head; only the forearms move.', 'Extend the elbows to return the bell overhead.', 'Repeat for the recommended number of repetitions.', 'Tip: Grip the horns firmly — the bell wants to rotate at the bottom.', 'Tip: Elbows stay narrow; if they flare, drop the load.', 'Tip: A seated version on a bench with a back rest is easier on the lumbar.']::text[]),
  ('Kettlebell Skull Crusher', 'triceps', 'kettlebell', 'weight_reps', 'repdb-kettlebell-skull-crusher.webp', 'repdb-kettlebell-skull-crusher-end.webp', ARRAY['Lie on your back on the floor with your knees bent and feet flat, holding a kettlebell by the horns with both hands, arms extended above the chest.', 'Bend the elbows to lower the bell in a controlled arc past your forehead to behind your head, until it nearly touches the floor.', 'Keep the upper arms still, angled slightly back toward your head; only the forearms move.', 'Extend the elbows to press the bell back up.', 'Repeat for the recommended number of repetitions.', 'Tip: Grip the horns firmly — the bell tries to rotate forward at the bottom.', 'Tip: Elbows stay narrow — if they flare, the load is too heavy.', 'Tip: Angle the upper arms slightly back toward the head to keep tension on the triceps at lockout.']::text[]),
  ('One-Arm Kettlebell Tricep Kickback', 'triceps', 'kettlebell', 'weight_reps', 'repdb-one-arm-kettlebell-tricep-kickback.webp', 'repdb-one-arm-kettlebell-tricep-kickback-end.webp', ARRAY['Hinge forward at the hips with a flat back, knees softly bent.', 'Hold a kettlebell by the handle in one hand, palm facing the body.', 'Pin the upper arm to the side so it is parallel to the floor; the forearm hangs straight down.', 'Extend the elbow back to straighten the arm fully behind you, keeping the upper arm motionless.', 'Squeeze the tricep at lockout, then return under control to the starting position.', 'Complete all reps on one side, then switch hands.', 'Tip: The upper arm does not move — only the forearm. Any shoulder swing is a cheat.', 'Tip: Lock the bell briefly at full extension; the bottom of the bell wants to dip the wrist.', 'Tip: Use a lighter bell than you would for a dumbbell kickback — the offset load is harder to stabilize.']::text[]),
  ('Plate-Loaded Seated Dip Machine', 'triceps', 'machine', 'weight_reps', 'repdb-plate-loaded-seated-dip-machine.webp', 'repdb-plate-loaded-seated-dip-machine-end.webp', ARRAY['Load the plates evenly on the sleeve and adjust the seat so the handles are at about shoulder height when you are seated.', 'Sit upright with your back against the pad and grip the handles at your sides with your elbows bent.', 'Keep your shoulders down and your chest up, then press the handles down by straightening your elbows.', 'Squeeze your triceps at the bottom, with your arms straight but not locked out hard.', 'Let the handles rise back up under control until your elbows are bent to about 90 degrees.', 'Repeat for the planned repetitions, then return the lever to its safety stop before you stand up.', 'Tip: Start light and add plates gradually; if the handles stop short of full extension the load is too heavy.', 'Tip: Keep the elbows close to your sides and your back against the pad so the work stays on the triceps.', 'Tip: Do not let the shoulders roll forward or shrug as the handles rise; stop where the stretch in the chest and shoulders is comfortable.']::text[]),
  ('Reverse Plank Dips', 'triceps', 'bodyweight', 'bodyweight_reps', 'repdb-reverse-plank-dips.webp', 'repdb-reverse-plank-dips-end.webp', ARRAY['Sit with the legs straight and the hands on the floor behind the hips, fingers pointing forward.', 'Press into the hands and heels and lift the hips into a straight-leg reverse plank.', 'Bend the elbows straight back and lower the hips a short way towards the floor.', 'Push back up until the arms lock out, keeping the hips high.', 'Repeat for the desired number of repetitions.', 'Tip: Keep the hips lifted at the bottom; sitting down between reps removes the load.', 'Tip: Keep the elbows tracking straight back rather than flaring outwards.', 'Tip: Bend the knees if the straight-leg version is too demanding on the hamstrings.']::text[]),
  ('Seated Dumbbell Tricep Extension', 'triceps', 'dumbbell', 'weight_reps', 'repdb-seated-dumbbell-tricep-extension.webp', 'repdb-seated-dumbbell-tricep-extension-end.webp', ARRAY['Sit on a bench with a dumbbell held overhead in both hands.', 'Keep your upper arms vertical next to your ears.', 'Lower the dumbbell behind your head by bending your elbows.', 'Extend your arms to press the dumbbell back overhead.', 'Squeeze your triceps at the top.', 'Repeat for the desired number of reps.', 'Tip: Keep your upper arms vertical next to your ears.', 'Tip: Move only your forearms, keeping the elbows still.', 'Tip: Brace your core to avoid arching your lower back.']::text[]),
  ('TRX Triceps Extension', 'triceps', 'bodyweight', 'bodyweight_reps', 'repdb-trx-tricep-extension.webp', 'repdb-trx-tricep-extension-end.webp', ARRAY['Stand facing away from the anchor point, holding the TRX handles with an overhand grip, palms facing down.', 'Lean forward, extending your arms straight out in front of you at shoulder height, creating tension in the straps.', 'Keeping your elbows high and fixed, bend them to lower your body by letting your hands move towards your temples.', 'Extend your elbows forcefully to push your body back to the starting position, squeezing your triceps.', 'Maintain a rigid plank position throughout the movement, engaging your core and glutes.', 'Tip: Adjust your body angle to increase or decrease difficulty; the more horizontal, the harder the exercise.', 'Tip: Keep your elbows pointing forward and high to maximize triceps isolation and minimize shoulder involvement.', 'Tip: Control the eccentric (lowering) phase for better muscle engagement and growth.']::text[]),
  ('Cable Wrist Curl', 'forearms', 'cable', 'weight_reps', 'repdb-cable-wrist-curl.webp', 'repdb-cable-wrist-curl-end.webp', ARRAY['Attach a short straight bar to a low cable pulley and sit on a flat bench facing the pulley, feet flat on the floor.', 'Take the bar with an underhand grip, palms facing up, hands about shoulder-width apart.', 'Rest your forearms on your thighs so that your wrists and hands reach just past your knees.', 'Let the cable pull your wrists down until you feel a stretch in your forearms.', 'Curl the bar up by flexing your wrists, keeping your forearms on your thighs.', 'Lower the bar under control and repeat for the planned repetitions.', 'Tip: Move only at the wrists; keep your forearms pressed against your thighs.', 'Tip: Perform the reps slowly to avoid straining your wrists.', 'Tip: Pause briefly at the top of each rep for a stronger contraction.']::text[]),
  ('Dead Hang', 'forearms', 'bodyweight', 'duration', 'repdb-dead-hang.webp', null, ARRAY['Grip a pull-up bar with palms facing away, shoulder-width apart.', 'Hang with your arms fully extended and feet off the ground.', 'Relax your shoulders and let your body hang.', 'Keep your core lightly engaged.', 'Hold for the desired duration.', 'Tip: Build up your hold time gradually across sessions.', 'Tip: Breathe steadily throughout the hold instead of holding your breath.', 'Tip: Land softly with bent knees when you release the bar.']::text[]),
  ('Dumbbell Reverse Wrist Curl', 'forearms', 'dumbbell', 'weight_reps', 'repdb-db-reverse-wrist-curl.webp', 'repdb-db-reverse-wrist-curl-end.webp', ARRAY['Sit on a bench holding a dumbbell in each hand, forearms resting on your thighs, palms down.', 'Let both wrists drop, lowering the dumbbells toward the floor.', 'Lift the backs of your hands toward the ceiling by extending your wrists.', 'Squeeze at the top, then lower under control.', 'Repeat for the desired number of reps.', 'Tip: Use a much lighter load than for a regular wrist curl.', 'Tip: Move only at the wrist.', 'Tip: Squeeze the back of the forearm at the top.']::text[]),
  ('Dumbbell Wrist Curl', 'forearms', 'dumbbell', 'weight_reps', 'repdb-dumbbell-wrist-curl.webp', 'repdb-dumbbell-wrist-curl-end.webp', ARRAY['Sit on a bench with the forearm resting on the thigh, palm up.', 'Hold a dumbbell with the wrist hanging off the knee.', 'Let the dumbbell roll down to the fingertips.', 'Curl the dumbbell up by flexing the wrist.', 'Lower under control. Complete reps per side.', 'Tip: Move only at the wrist — keep the forearm still.', 'Tip: Roll the dumbbell to the fingertips for full range.', 'Tip: Train both arms with the same load and reps.']::text[]),
  ('EZ-Bar Wrist Curl', 'forearms', 'barbell', 'weight_reps', 'repdb-ez-bar-wrist-curl.webp', 'repdb-ez-bar-wrist-curl-end.webp', ARRAY['Sit on a bench with forearms resting on the thighs, palms up.', 'Grip an EZ-bar on the inner bends with hands shoulder-width.', 'Let the bar roll down to the fingertips.', 'Curl the bar up by flexing the wrists.', 'Lower under control.', 'Tip: The EZ-bar''s angle is gentler on the wrists than a straight bar.', 'Tip: Move only at the wrist — keep the forearms still.', 'Tip: Roll the bar to the fingertips for full range.']::text[]),
  ('Kettlebell Farmer''s Walk', 'forearms', 'kettlebell', 'weight_reps', 'repdb-kettlebell-farmers-walk.webp', null, ARRAY['Stand between two heavy kettlebells.', 'Hinge and grip the handles firmly with a neutral grip.', 'Stand tall with shoulders back and core braced.', 'Walk forward with short, controlled steps.', 'Maintain an upright posture throughout the walk.', 'Set the weights down at the end of the distance.', 'Tip: Keep your shoulders level and avoid leaning to either side.', 'Tip: Breathe steadily rather than holding your breath under load.', 'Tip: If your grip fails, set the weights down away from your feet.']::text[]),
  ('Kettlebell Reverse Wrist Curl', 'forearms', 'kettlebell', 'weight_reps', 'repdb-kettlebell-reverse-wrist-curl.webp', 'repdb-kettlebell-reverse-wrist-curl-end.webp', ARRAY['Sit on a bench with your forearms on your thighs, palms down.', 'Hold one kettlebell by the handle with both hands, with the wrists hanging off the knees.', 'Let the wrists drop, lowering the kettlebell.', 'Lift the backs of the hands by extending the wrists.', 'Lower under control and repeat for the planned reps.', 'Tip: Use a very light kettlebell — extensors fatigue quickly.', 'Tip: Move only at the wrists.', 'Tip: Hold the handle, not the bell.']::text[]),
  ('Kettlebell Wrist Curl', 'forearms', 'kettlebell', 'weight_reps', 'repdb-kettlebell-wrist-curl.webp', 'repdb-kettlebell-wrist-curl-end.webp', ARRAY['Sit on a bench with your forearms on your thighs, palms up.', 'Hold a kettlebell by the handle in each hand, with the wrists hanging off the knees.', 'Let the kettlebells rotate down toward the fingertips.', 'Curl them up by flexing the wrists, controlling the offset weight.', 'Lower under control and repeat for the planned reps.', 'Tip: Hold the handles, not the bells, so the offset weight loads the grip.', 'Tip: Move only at the wrists.', 'Tip: Use a lighter load than you would for a dumbbell.']::text[]),
  ('Ring Dead Hang', 'forearms', 'bodyweight', 'duration', 'repdb-ring-dead-hang.webp', null, ARRAY['Grip a pair of gymnastic rings with a neutral grip, palms facing each other.', 'Hang with your arms fully extended and feet off the ground.', 'Let the rings rotate naturally; do not fight the grip.', 'Keep your shoulders engaged (no shrug to the ears) and core lightly braced.', 'Hold for the desired duration.', 'Tip: Breathe steadily rather than holding your breath.', 'Tip: Build hold duration gradually as your grip strengthens.', 'Tip: Step down under control before your grip fails completely.']::text[]),
  ('Suitcase Carry', 'forearms', 'kettlebell', 'weight_reps', 'repdb-suitcase-carry.webp', null, ARRAY['Stand beside a single kettlebell or dumbbell with your feet under your hips.', 'Hinge at the hips, take the handle in one hand and stand up with the weight hanging at your side.', 'Pull that shoulder down and back, and brace as if you were about to be pushed sideways.', 'Walk forward with normal, even strides, keeping your torso upright and square rather than leaning away from the weight.', 'Keep the free arm relaxed at your side instead of sticking it out as a counterweight.', 'Carry for the desired distance or time, set the weight down under control, then repeat on the other side.', 'Tip: Do the same distance on both sides. The whole value is in the asymmetry, and it only works if you load both directions equally.', 'Tip: If you find yourself tipping toward the weight or hiking the opposite hip, the weight is too heavy — this is a posture drill first.', 'Tip: Grip usually gives out before the trunk does. That is a legitimate training effect, but if it is always the limit, use straps for the heavier sets.']::text[]),
  ('Banded Squat', 'quads', 'band', 'bodyweight_reps', 'repdb-banded-squat.webp', 'repdb-banded-squat-end.webp', ARRAY['Place a loop band just above the knees.', 'Stand with feet shoulder-width apart, toes slightly out.', 'Push the knees out against the band as you squat down.', 'Descend until thighs are parallel or below.', 'Drive through the heels to stand back up.', 'Tip: Push the knees out against the band the whole rep.', 'Tip: Keep the chest up and the back flat.', 'Tip: Do not let the knees collapse inward.']::text[]),
  ('Banded Terminal Knee Extension', 'quads', 'band', 'bodyweight_reps', 'repdb-banded-terminal-knee-extension.webp', 'repdb-banded-terminal-knee-extension-end.webp', ARRAY['Anchor a loop band to a sturdy upright at knee height.', 'Step into the loop so the band sits behind one knee.', 'Step back so the band pulls the knee into a slight bend.', 'Extend the knee fully against the band, contracting the quad.', 'Return slowly. Complete reps per side, then switch.', 'Tip: Squeeze the quadriceps hard at full extension.', 'Tip: Keep the foot flat — do not lift the heel.', 'Tip: Move only at the knee — the hip stays still.']::text[]),
  ('Barbell Bulgarian Split Squat', 'quads', 'barbell', 'weight_reps', 'repdb-barbell-bulgarian-split-squat.webp', 'repdb-barbell-bulgarian-split-squat-end.webp', ARRAY['Set a barbell across the upper back and stand about two feet in front of a flat bench, facing away from it.', 'Place the top of one foot on the bench behind you, with the front foot far enough forward to keep the shin close to vertical when you lower.', 'Brace the trunk and lower the back knee toward the floor by bending the front hip and knee.', 'Descend until the front thigh is about parallel to the floor, keeping the chest up.', 'Drive through the middle of the front foot to return to the start.', 'Complete the repetitions on one leg, then switch.', 'Tip: Keep most of the weight on the front leg; the back foot is only there for balance.', 'Tip: Keep the front knee tracking over the toes and the torso upright.', 'Tip: Use a lighter load than in a regular back squat, and set up the bar and a safe way to drop it before you step into position.']::text[]),
  ('Barbell Reverse Lunge', 'quads', 'barbell', 'weight_reps', 'repdb-barbell-reverse-lunge.webp', 'repdb-barbell-reverse-lunge-end.webp', ARRAY['Place a barbell across your upper back and stand tall.', 'Step one foot backward into a long stride.', 'Lower your back knee toward the ground under control.', 'Drive through your front heel to return to standing.', 'Complete reps on one side, then switch.', 'Tip: Step back far enough to keep your front shin close to vertical.', 'Tip: Lower the back knee straight down rather than leaning forward.', 'Tip: Keep your chest tall and hips square throughout.']::text[]),
  ('Bodyweight Reverse Lunge', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-bodyweight-reverse-lunge.webp', 'repdb-bodyweight-reverse-lunge-end.webp', ARRAY['Stand tall with your feet hip-width apart.', 'Step one leg back and lower your knee toward the floor.', 'Lower until your front thigh is parallel to the floor.', 'Push through your front heel to return to standing.', 'Repeat on both sides.', 'Tip: No weight needed -- focus on balance and a controlled descent.', 'Tip: Keep your torso upright instead of leaning forward.', 'Tip: Step back far enough that your front knee stays behind your toes.']::text[]),
  ('Box Squat', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-box-squat.webp', 'repdb-box-squat-end.webp', ARRAY['Stand in front of a box or bench, feet shoulder-width apart, with your arms extended forward for balance.', 'Push your hips back and bend your knees, sitting back toward the box rather than straight down.', 'Touch the box lightly with your glutes without collapsing onto it.', 'Drive through your feet to stand back up, squeezing your glutes at the top.', 'Repeat for the desired number of reps.', 'Tip: Use a box height that lets your thighs reach about parallel to the floor and lower it as mobility improves.', 'Tip: Keep your weight through the middle of your feet — do not rock onto your toes.', 'Tip: Touch and go: fully relaxing onto the box loses core tension and stresses the spine.']::text[]),
  ('Cossack Squat', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-cossack-squat.webp', 'repdb-cossack-squat-end.webp', ARRAY['Stand in a wide stance with toes turned slightly out.', 'Shift your weight to one side, bending that knee and sinking into a deep squat.', 'Keep the trailing leg straight with the heel down and toes up.', 'Sink as low as your mobility allows, keeping the chest tall.', 'Drive through the bent leg back to center, then repeat to the other side.', 'Tip: Keep the working heel planted -- do not roll onto the toes.', 'Tip: Point the straight leg''s toes up to keep tension in the adductors.', 'Tip: Hold a light weight at your chest for a counterbalance if needed.']::text[]),
  ('Dumbbell Front Squat', 'quads', 'dumbbell', 'weight_reps', 'repdb-dumbbell-front-squat.webp', 'repdb-dumbbell-front-squat-end.webp', ARRAY['Hold a dumbbell in each hand resting on top of your shoulders.', 'Keep your elbows high and torso upright.', 'Lower your hips by bending knees until thighs are parallel to the floor.', 'Drive through your heels to stand back up.', 'Maintain a neutral spine throughout.', 'Repeat for the desired number of reps.', 'Tip: Keep your elbows high so the dumbbells stay racked on your shoulders.', 'Tip: Sit down between your hips rather than folding forward.', 'Tip: Drive through the whole foot and keep your heels down.']::text[]),
  ('Dumbbell Pistol Squat', 'quads', 'dumbbell', 'weight_reps', 'repdb-dumbbell-pistol-squat.webp', 'repdb-dumbbell-pistol-squat-end.webp', ARRAY['Stand tall, holding a dumbbell in each hand with your arms hanging at your sides.', 'Lift one leg straight out in front of you, keeping it extended throughout the movement.', 'Lower your body by bending the knee of your standing leg, keeping your chest up and back straight.', 'Descend until your glutes are close to your heel or your thigh is parallel to the floor, maintaining balance.', 'Push through your heel to return to the starting position, extending your standing leg fully.', 'Complete all reps on one side, then switch legs and repeat for the other side per set.', 'Tip: Start with bodyweight pistol squats to master the movement pattern before adding dumbbells.', 'Tip: Let the dumbbells hang straight down at your sides and keep your chest up to stay balanced over the working foot.', 'Tip: Focus on controlling the eccentric (lowering) phase to improve stability and strength.', 'Tip: Elevate your heel slightly on a small plate if ankle mobility is a limiting factor.']::text[]),
  ('Dumbbell Somersault Squat', 'quads', 'dumbbell', 'weight_reps', 'repdb-db-somersault-squat.webp', 'repdb-db-somersault-squat-end.webp', ARRAY['Stand with feet shoulder-width holding a dumbbell in one hand at the shoulder.', 'Squat down while reaching the dumbbell forward and across the body.', 'Reach the bottom of the squat with the dumbbell extended past the opposite knee.', 'Drive through the heels to stand up, returning the dumbbell to the shoulder.', 'Complete reps per side, then switch.', 'Tip: Move slowly through the rotation to keep the spine controlled.', 'Tip: Use a light dumbbell — the long lever taxes the shoulder.', 'Tip: Push the knees out to keep the squat track stable.']::text[]),
  ('Dumbbell Split Squat', 'quads', 'dumbbell', 'weight_reps', 'repdb-dumbbell-split-squat.webp', 'repdb-dumbbell-split-squat-end.webp', ARRAY['Stand in a split stance holding dumbbells at your sides.', 'Keep your torso upright and core braced.', 'Lower your back knee toward the floor by bending both knees.', 'Stop when your front thigh is parallel to the floor.', 'Drive through your front heel to return to standing.', 'Complete reps on one side, then switch.', 'Tip: Keep most of your weight on your front leg.', 'Tip: Lower your back knee straight down toward the floor.', 'Tip: Track your front knee over your toes without letting it cave inward.']::text[]),
  ('Dumbbell Step-Up to Balance', 'quads', 'dumbbell', 'weight_reps', 'repdb-db-step-up-to-balance.webp', 'repdb-db-step-up-to-balance-end.webp', ARRAY['Stand facing a low, stable step or bench with a dumbbell in each hand, arms hanging at your sides.', 'Place one foot flat on top of the step.', 'Press through the whole of the front foot and straighten that leg to lift your body onto the step.', 'As you rise, drive the other knee up in front of you until the thigh is about hip height.', 'Stand tall on the working leg and hold the knee-up position for a moment without leaning back.', 'Lower the free foot back to the floor under control, then step the working leg down as well and repeat; switch legs after the planned repetitions.', 'Tip: Keep the weights hanging at your sides and still; swinging them or pulling them up with your arms takes the work away from the legs.', 'Tip: Keep your trunk upright and your hips level during the balance hold rather than tilting toward the lifted knee.', 'Tip: Start with light weights and a low step; add load only when you can hold the balance position without wobbling.']::text[]),
  ('Goblet Squat', 'quads', 'kettlebell', 'weight_reps', 'repdb-goblet-squat.webp', 'repdb-goblet-squat-end.webp', ARRAY['Hold a kettlebell at chest height with both hands.', 'Squat down keeping the weight close to your chest.', 'Drive back up.', 'Repeat.', 'Tip: The goblet position naturally encourages an upright torso.', 'Tip: Push knees out at the bottom.']::text[]),
  ('Heel-Elevated Squat', 'quads', 'barbell', 'weight_reps', 'repdb-heel-elevated-squat.webp', 'repdb-heel-elevated-squat-end.webp', ARRAY['Place weight plates or a wedge under your heels, feet shoulder-width apart.', 'Hold a barbell across your upper back or hold dumbbells at your sides.', 'Brace your core and descend into a squat, keeping your torso upright.', 'Squat until thighs are parallel to the floor or lower.', 'Drive through your feet to return to the starting position.', 'Tip: The elevated heels allow a more upright torso and greater knee travel.', 'Tip: Keep your knees tracking over your toes throughout.', 'Tip: Start with a small heel elevation and increase as mobility improves.']::text[]),
  ('High-Foot Leg Press', 'quads', 'machine', 'weight_reps', 'repdb-high-foot-leg-press.webp', 'repdb-high-foot-leg-press-end.webp', ARRAY['Set the back pad and seat so your lower back stays supported and your knees can bend without your pelvis rolling under.', 'Place both feet high on the platform at about shoulder width, with the toes tracking in the same direction as the knees.', 'Lower the sled by bending the hips and knees until you reach a comfortable depth without the lower back lifting from the pad.', 'Press through the whole foot and extend the hips and knees without locking the knees aggressively.', 'Lower the sled under control and repeat for the desired number of repetitions.', 'Tip: Keep the pelvis heavy against the pad; a high foot position does not justify rounding the lower back at the bottom.', 'Tip: Keep the heels and the whole foot planted rather than letting the toes carry the sled.', 'Tip: Use a depth that preserves pelvic position instead of chasing a deeper range with a tucked pelvis.']::text[]),
  ('Horizontal Leg Press', 'quads', 'machine', 'weight_reps', 'repdb-horizontal-leg-press.webp', 'repdb-horizontal-leg-press-end.webp', ARRAY['Sit in a horizontal leg press with your back against the pad and your feet shoulder-width apart on the footplate.', 'Press through your feet to straighten your legs, stopping just short of locking the knees.', 'Bend your knees under control until they come toward your chest.', 'Repeat.', 'Tip: Do not let your lower back lift off the seat.', 'Tip: Avoid locking out the knees completely.']::text[]),
  ('Isometric Split Squat', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-isometric-split-squat.webp', null, ARRAY['Stand with one foot well forward and the other foot back, about a long stride apart, with your hands on your hips.', 'Keep your torso upright and lower straight down by bending both knees.', 'Lower until your front thigh is close to parallel with the floor and your back knee hovers just above the ground.', 'Keep your front heel flat and your front knee tracking over your toes.', 'Hold this position for the planned time, keeping your trunk tall and your weight spread through the front foot.', 'Press up to the top, then repeat on the other leg.', 'Tip: Keep the back knee just off the floor so the front leg keeps working the whole time.', 'Tip: Do not let the front knee cave inward; push it gently over the middle toes.', 'Tip: Hold a lighter position higher up if the bottom is too intense; the quads should burn, not the knee joint.']::text[]),
  ('Kettlebell Bulgarian Split Squat', 'quads', 'kettlebell', 'weight_reps', 'repdb-kettlebell-bulgarian-split-squat.webp', 'repdb-kettlebell-bulgarian-split-squat-end.webp', ARRAY['Stand facing away from a bench, placing one foot on it behind you, laces down. Hold a kettlebell in each hand at your sides.', 'Maintain an upright torso and engage your core.', 'Lower your body by bending both knees, allowing your front knee to track over your toes.', 'Descend until your front thigh is parallel to the floor or slightly below, keeping your rear knee close to the ground.', 'Drive through your front heel to return to the starting position, extending your hips and knees.', 'Complete all reps per side before switching.', 'Tip: Ensure your front foot is far enough from the bench to allow a full range of motion without discomfort.', 'Tip: Keep your torso upright throughout the movement to maximize glute and quad engagement.', 'Tip: Control the eccentric (lowering) phase to build strength and stability.', 'Tip: With only one kettlebell, hold it in the hand opposite the front leg for an extra balance challenge.']::text[]),
  ('Kettlebell Goblet Lunge', 'quads', 'kettlebell', 'weight_reps', 'repdb-kettlebell-goblet-lunge.webp', 'repdb-kettlebell-goblet-lunge-end.webp', ARRAY['Stand tall holding a kettlebell by its horns at chest height, elbows tucked, in the goblet position.', 'Take a controlled step forward with one leg, lowering your hips until both knees are bent at approximately 90 degrees.', 'Ensure your front knee is stacked over your ankle and your rear knee hovers just above the floor.', 'Drive through your front heel to return to the starting position, maintaining balance and core tension.', 'Complete all repetitions on one side before switching, or alternate legs per set.', 'Tip: Keep your chest upright and core braced throughout the movement to protect your spine and maintain stability.', 'Tip: Focus on a controlled descent and a powerful drive up, engaging your glutes and quads.', 'Tip: Avoid letting your front knee collapse inward; keep it aligned with your toes.']::text[]),
  ('Kettlebell Reverse Lunge', 'quads', 'kettlebell', 'weight_reps', 'repdb-kettlebell-reverse-lunge.webp', 'repdb-kettlebell-reverse-lunge-end.webp', ARRAY['Stand tall holding a kettlebell by the horns at your chest, elbows tucked in (goblet hold).', 'Step one leg straight back, lowering your hips until both knees are bent at approximately 90 degrees.', 'Keep your front shin vertical and your chest upright, ensuring your back knee hovers just above the floor.', 'Drive through your front heel to return to the starting position.', 'Complete all reps per side before switching to the other side.', 'Tip: Maintain a stable core throughout the movement to protect your spine.', 'Tip: Focus on a controlled descent and a powerful ascent.', 'Tip: Keep your front foot flat and distribute weight evenly through the heel and midfoot.', 'Tip: Avoid letting your front knee collapse inward; keep it tracking over your toes.']::text[]),
  ('Kettlebell Rotational Lunge', 'quads', 'kettlebell', 'weight_reps', 'repdb-kettlebell-rotational-lunge.webp', 'repdb-kettlebell-rotational-lunge-end.webp', ARRAY['Hold a kettlebell with both hands at your chest.', 'Step back into a lunge, lowering until both knees are bent.', 'Rotate your torso toward the front leg.', 'Move the kettlebell to that side at chest to shoulder height, arms almost straight.', 'Rotate back to the center and push through the front foot to return to standing.', 'Complete reps on one side, then switch.', 'Tip: Keep the front knee over the ankle as you lower into the lunge.', 'Tip: Rotate from your torso and hips, not your knees.', 'Tip: Keep your chest tall as you rotate.']::text[]),
  ('Kettlebell Squat', 'quads', 'kettlebell', 'weight_reps', 'repdb-kettlebell-squat.webp', 'repdb-kettlebell-squat-end.webp', ARRAY['Stand with feet shoulder-width apart, holding a kettlebell with both hands in front of you.', 'Let the kettlebell hang naturally between your legs as you brace your core.', 'Bend your hips and knees to squat down, keeping the kettlebell close to your body.', 'Drive through your feet to stand back up to the starting position.', 'Repeat for the desired number of reps.', 'Tip: Keep your chest up and back flat throughout the movement.', 'Tip: Let the kettlebell act as a counterbalance to help you sit deeper into the squat.', 'Tip: Push your knees out in line with your toes as you descend.']::text[]),
  ('Kettlebell Step-Up to Balance', 'quads', 'kettlebell', 'weight_reps', 'repdb-kb-step-up-to-balance.webp', 'repdb-kb-step-up-to-balance-end.webp', ARRAY['Stand facing a low, stable step or bench with a kettlebell in each hand, arms hanging at your sides.', 'Place one foot flat on top of the step.', 'Press through the whole of the front foot and straighten that leg to lift your body onto the step.', 'As you rise, drive the other knee up in front of you until the thigh is about hip height.', 'Stand tall on the working leg and hold the knee-up position for a moment without leaning back.', 'Lower the free foot back to the floor under control, then step the working leg down as well and repeat; switch legs after the planned repetitions.', 'Tip: Keep the weights hanging at your sides and still; swinging them or pulling them up with your arms takes the work away from the legs.', 'Tip: Keep your trunk upright and your hips level during the balance hold rather than tilting toward the lifted knee.', 'Tip: Start with light weights and a low step; add load only when you can hold the balance position without wobbling.']::text[]),
  ('Lunge', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-lunge.webp', 'repdb-lunge-end.webp', ARRAY['Stand tall with your feet hip-width apart.', 'Step forward with one leg into a long stride.', 'Lower your back knee toward the floor until both knees form 90-degree angles.', 'Drive through your front heel to return to standing.', 'Complete reps on one side, then switch.', 'Tip: Take a stride long enough for both knees to reach about 90 degrees.', 'Tip: Keep your torso upright and eyes forward.', 'Tip: Push through the front heel to return in one strong motion.']::text[]),
  ('One Arm Kettlebell Front Squat', 'quads', 'kettlebell', 'weight_reps', 'repdb-one-arm-kettlebell-front-squat.webp', 'repdb-one-arm-kettlebell-front-squat-end.webp', ARRAY['Hold a kettlebell in the racked position at one shoulder.', 'Stand with feet shoulder-width apart.', 'Squat down by bending your knees and hips.', 'Keep your chest up and torso upright throughout.', 'Drive through your heels to stand back up.', 'Complete reps on one side, then switch.', 'Tip: Keep the rack position tight against your chest and forearm.', 'Tip: Resist twisting or leaning toward the loaded side.', 'Tip: Spread the floor with your feet to keep your knees tracking outward.']::text[]),
  ('Pause Squat', 'quads', 'barbell', 'weight_reps', 'repdb-pause-squat.webp', 'repdb-pause-squat-end.webp', ARRAY['Unrack a barbell and rest it across your upper back.', 'Stand with feet shoulder-width apart.', 'Squat down until your thighs are parallel to the floor.', 'Hold the bottom position for 2-3 seconds.', 'Drive through your heels to stand back up.', 'Repeat for the desired number of reps.', 'Tip: Stay braced and tight during the pause rather than relaxing.', 'Tip: Avoid collapsing forward or rocking as you hold the bottom.', 'Tip: Use lighter loads than your regular squat to maintain crisp form.']::text[]),
  ('Pistol Squat', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-pistol-squat.webp', 'repdb-pistol-squat-end.webp', ARRAY['Stand on one leg with the other extended forward, arms out for balance.', 'Hinge at the hips and bend the standing knee, keeping the chest up.', 'Descend slowly until the back of the thigh touches the calf.', 'Drive through the standing heel to return to standing.', 'Complete reps per side, then switch legs.', 'Tip: Hold a light counterweight at the chest if balance is hard.', 'Tip: Build the strength with box-assisted pistols first.', 'Tip: Keep the working heel flat on the floor.']::text[]),
  ('Plyo Lunge', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-plyo-lunge.webp', 'repdb-plyo-lunge-end.webp', ARRAY['Start in a forward lunge with one foot ahead of the other.', 'Drop into a deep lunge with the back knee almost touching the floor.', 'Drive both feet off the floor, switching legs in mid-air.', 'Land softly in a lunge with the opposite leg forward.', 'Continue alternating without pausing.', 'Tip: Land softly with bent knees to absorb impact.', 'Tip: Switch the leg position fully — do not just hop in place.', 'Tip: Keep the torso upright — do not pitch forward.']::text[]),
  ('Reverse Nordic Curl', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-reverse-nordic-curl.webp', 'repdb-reverse-nordic-curl-end.webp', ARRAY['Kneel on a pad with your knees hip-width apart, shins and the tops of your feet on the floor, and your torso upright.', 'Keep your hips extended and core braced.', 'Slowly lean your torso backward while keeping your body in a straight line.', 'Lower as far as you can control with your quadriceps.', 'Pull yourself back up to the starting position.', 'Repeat for the desired number of reps.', 'Tip: Keep your hips extended throughout — don''t let them fold.', 'Tip: Lower only as far as you can control.', 'Tip: Use a pad under the knees for comfort.']::text[]),
  ('Shrimp Squat', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-shrimp-squat.webp', 'repdb-shrimp-squat-end.webp', ARRAY['Stand on one leg, bend the other knee and hold that foot behind you with the same-side hand.', 'Hold your arms and chest steady and begin to bend the standing knee, sitting your hips down and slightly back.', 'Lower until the back knee lightly touches the floor behind the standing foot.', 'Keep your chest up and your standing heel on the floor throughout the descent.', 'Press through the whole standing foot and straighten that leg to return to standing without letting go of the rear foot.', 'Complete the planned repetitions, then repeat on the other leg.', 'Tip: Touch the floor with the knee lightly and do not drop onto it; control the descent with the standing leg.', 'Tip: Lean the trunk forward a little to keep your balance; the front knee tracks over the toes and the heel stays down.', 'Tip: Learn the movement first by holding a support with your free hand or lowering onto a folded mat.']::text[]),
  ('Side Lunge', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-side-lunge.webp', 'repdb-side-lunge-end.webp', ARRAY['Stand with feet hip-width apart and hands at your chest.', 'Step one leg wide to the side, keeping the other leg straight.', 'Bend the stepping knee and push your hips back into a lateral squat.', 'Keep your chest up and the working heel planted.', 'Drive through the bent leg to return to standing.', 'Complete reps on one side, then switch.', 'Tip: Push your hips back as you bend the stepping knee.', 'Tip: Keep your trailing leg straight and both heels planted.', 'Tip: Keep your chest up rather than rounding forward.']::text[]),
  ('Single Leg Press', 'quads', 'machine', 'weight_reps', 'repdb-single-leg-press.webp', 'repdb-single-leg-press-end.webp', ARRAY['Sit in a leg press machine with one foot placed on the platform.', 'Keep the other leg off the platform, resting to the side.', 'Release the safeties and lower the platform by bending your knee.', 'Stop when your knee is near a 90-degree angle.', 'Drive through the heel to press the platform back up.', 'Complete reps on one side, then switch.', 'Tip: Keep your foot flat and centered on the platform.', 'Tip: Avoid letting your knee cave inward.', 'Tip: Don''t lock out the knee forcefully at the top.']::text[]),
  ('Single-Leg Box Squat', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-single-leg-box-squat.webp', 'repdb-single-leg-box-squat-end.webp', ARRAY['Stand in front of a sturdy box or bench that is about knee height, with your back to it.', 'Shift your weight onto one leg and lift the other leg out in front of you, with your arms stretched forward for balance.', 'Push your hips back and bend the standing knee, lowering yourself under control toward the box.', 'Sit lightly on the box without dropping onto it, keeping your chest up and the free leg off the floor.', 'Press through the whole standing foot and straighten that leg to stand up again.', 'Complete the planned repetitions, then repeat on the other leg.', 'Tip: Choose a higher box to start; lower it as your strength and control improve.', 'Tip: Keep the knee of the standing leg tracking over your toes and your heel on the floor.', 'Tip: Touch the box with your hips rather than relaxing onto it, and use the arms as a counterweight.']::text[]),
  ('Smith Machine Bulgarian Split Squat', 'quads', 'machine', 'weight_reps', 'repdb-smith-machine-bulgarian-split.webp', 'repdb-smith-machine-bulgarian-split-end.webp', ARRAY['Set up a bench behind the Smith machine. Rest the bar on your traps.', 'Place the rear foot on the bench and front foot forward.', 'Lower your back knee toward the floor.', 'Push through the front heel to return.', 'Repeat on both sides.', 'Tip: The Smith machine guides the bar path.', 'Tip: Focus on keeping front knee tracking over toes.']::text[]),
  ('Smith Machine Front Squat', 'quads', 'machine', 'weight_reps', 'repdb-smith-machine-front-squat.webp', 'repdb-smith-machine-front-squat-end.webp', ARRAY['Set the bar at upper-chest height and step under it so it rests across the front of your shoulders, against your collarbones.', 'Cross your arms over the bar or take an open front-rack grip, and drive your elbows up until your upper arms are close to parallel with the floor.', 'Unrack the bar and stand with your feet about shoulder-width apart and slightly forward of it.', 'Sit straight down, keeping your elbows high and your torso upright, until your thighs are at least parallel to the floor.', 'Drive through the middle of your feet to stand back up, and repeat for the desired number of repetitions.', 'Tip: High elbows are the whole exercise. As soon as they drop, the bar rolls off your shoulders onto your hands and the rack position collapses.', 'Tip: Set the safety stops just below your deepest squat position before you unrack anything -- on a front squat the fastest way out of a failed rep is to let the bar go.', 'Tip: Standing slightly ahead of the bar lets you keep your torso vertical. Under a fixed path, a stance directly beneath the bar forces you to lean and pushes the bar off the front rack.']::text[]),
  ('Smith Machine Reverse Lunge', 'quads', 'machine', 'weight_reps', 'repdb-smith-machine-reverse-lunge.webp', 'repdb-smith-machine-reverse-lunge-end.webp', ARRAY['Set the bar so it sits across your upper traps when you stand, then unrack it with your feet under your hips.', 'Step one foot straight back and lower the rear knee toward the floor, keeping the front shin vertical and most of your weight on the front foot.', 'Stop when the rear knee is just short of the floor and the front thigh is roughly parallel to it.', 'Push through the front heel and bring the rear foot back to standing under the bar.', 'Complete all the repetitions on one side, then switch legs, or alternate legs on every repetition.', 'Tip: Step back far enough. A short step puts the front knee well past the toes, which the fixed bar path will not let you correct once you are loaded.', 'Tip: The stepping foot does the travelling; the front foot does not move at all. If it shifts between reps, your step is too long or too short.', 'Tip: The rack removes the balance, not the load -- keep the trunk braced and stand up out of the bottom rather than leaning back into the bar.']::text[]),
  ('Split Squat', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-split-squat.webp', 'repdb-split-squat-end.webp', ARRAY['Stand in a split stance with one foot forward and one back.', 'Keep your torso upright and core braced.', 'Lower your hips straight down by bending both knees.', 'Stop when the back knee is just above the floor.', 'Drive through the front heel to return to the start.', 'Complete reps on one side, then switch.', 'Tip: Lower straight down rather than lunging forward.', 'Tip: Keep most of your weight over the front foot.', 'Tip: Keep the front heel planted throughout the rep.']::text[]),
  ('Squat Pulse', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-squat-pulse.webp', 'repdb-squat-pulse-end.webp', ARRAY['Stand with the feet about shoulder-width apart and the toes turned slightly out, arms reaching forward for balance.', 'Squat down until the thighs are at least parallel to the floor, keeping the chest up and the heels down.', 'From the bottom, rise only a short way, a few inches, then sink back down.', 'Keep pulsing in the lower range without locking out or resting at the top.', 'Stand up fully when the set is finished.', 'Tip: Keep the knees tracking over the toes; do not let them cave inward.', 'Tip: Stay in the bottom half of the squat; standing up between pulses removes the tension this move is for.', 'Tip: Keep the pulses small and quick but controlled; do not bounce off the bottom.']::text[]),
  ('Step Ups', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-step-ups.webp', 'repdb-step-ups-end.webp', ARRAY['Stand facing a sturdy box or bench.', 'Place one foot fully on the box surface.', 'Drive through that heel to lift your body onto the box.', 'Bring your trailing foot up to stand fully on the box.', 'Step back down leading with the same foot.', 'Alternate legs or complete all reps on one side before switching.', 'Tip: Push through the lead heel rather than springing off the back leg.', 'Tip: Keep your torso upright and avoid leaning forward excessively.', 'Tip: Control the descent instead of dropping off the box.']::text[]),
  ('Step-Up to Balance', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-step-up-to-balance.webp', 'repdb-step-up-to-balance-end.webp', ARRAY['Stand facing a low, stable step or bench and place one foot flat on top of it.', 'Press through the whole of the front foot and straighten that leg to lift your body onto the step.', 'As you rise, drive the other knee up in front of you until the thigh is about hip height.', 'Stand tall on the working leg and hold the knee-up position for a moment without leaning back.', 'Lower the free foot back to the floor under control, then step the working leg down as well.', 'Complete the planned repetitions on one leg, then switch to the other.', 'Tip: Keep the whole foot on the step and push through it; pushing off the floor leg takes the work away from the front leg.', 'Tip: Keep the trunk upright and your hips level during the balance hold rather than tilting toward the lifted knee.', 'Tip: Choose a step low enough to stand up on without hopping; use a hand on a wall to start if balance is a limit.']::text[]),
  ('Sumo Squat', 'quads', 'barbell', 'weight_reps', 'repdb-sumo-squat.webp', 'repdb-sumo-squat-end.webp', ARRAY['Stand with feet wider than shoulder-width and toes turned out.', 'Hold a barbell across your upper back.', 'Brace your core and keep your chest up.', 'Bend at the hips and knees to lower into a deep squat.', 'Drive through your heels to stand back up.', 'Repeat for the desired number of reps.', 'Tip: Push your knees outward in line with your toes.', 'Tip: Keep the bar path vertical over the middle of your feet.', 'Tip: Avoid letting your lower back round at the bottom of the squat.']::text[]),
  ('TRX Lunge', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-trx-lunge.webp', 'repdb-trx-lunge-end.webp', ARRAY['Stand facing away from the anchor point with the suspension trainer straps behind you, hands on your hips or free for balance.', 'Place the top of one foot in the foot cradles and extend that leg behind you.', 'Brace your core and lower your body by bending the front knee, keeping your torso upright.', 'Descend until your front thigh is parallel to the floor or just below, maintaining tension on the suspension trainer.', 'Drive through your front heel to return to the starting position, extending the front leg.', 'Complete all reps on one side, then switch legs and repeat per side.', 'Tip: Keep your front knee tracking over your toes, avoiding inward collapse.', 'Tip: Maintain a neutral spine throughout the movement, preventing excessive arching or rounding.', 'Tip: Control the eccentric (lowering) phase to maximize muscle engagement.', 'Tip: Adjust your distance from the anchor point to modify difficulty.']::text[]),
  ('TRX Pistol Squat', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-trx-pistol-squat.webp', 'repdb-trx-pistol-squat-end.webp', ARRAY['Anchor the suspension trainer and hold the handles with both hands, arms extended.', 'Stand tall, lift one leg straight out in front of you, keeping it off the ground.', 'Initiate the squat by pushing your hips back and bending the standing knee, lowering your body as deep as possible.', 'Keep your chest up, back straight, and use the TRX for balance and support as needed.', 'Drive through your heel to return to the starting position, extending the standing leg fully.', 'Complete all reps on one side before switching to the other.', 'Tip: Maintain tension on the TRX straps throughout the movement for stability.', 'Tip: Focus on controlled descent and powerful ascent.', 'Tip: Keep the non-working leg extended and elevated to engage the hip flexors.', 'Tip: Adjust your grip on the TRX to modify the level of assistance.']::text[]),
  ('TRX Squat', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-trx-squat.webp', 'repdb-trx-squat-end.webp', ARRAY['Stand facing the anchor point, holding the handles with palms facing each other, arms extended.', 'Lean back slightly, keeping your body straight and core engaged, with feet shoulder-width apart.', 'Initiate the squat by pushing your hips back and bending your knees, lowering your body as if sitting in a chair.', 'Descend until your thighs are parallel to the floor or as deep as comfortable, maintaining tension on the straps.', 'Drive through your heels to return to the starting position, extending your hips and knees fully.', 'Tip: Keep your chest up and gaze forward throughout the movement to maintain a neutral spine.', 'Tip: Use the suspension trainer for assistance to control your descent and ascent, especially if new to squats.', 'Tip: Focus on pushing your knees out slightly to engage your glutes more effectively.']::text[]),
  ('Walking Lunge', 'quads', 'bodyweight', 'bodyweight_reps', 'repdb-walking-lunge.webp', 'repdb-walking-lunge-end.webp', ARRAY['Stand tall with feet hip-width apart and hands on hips.', 'Step one foot forward into a long lunge.', 'Lower until both knees are around 90 degrees.', 'Drive through the front heel and step the back foot forward.', 'Continue alternating legs as you walk forward.', 'Repeat for the desired number of reps.', 'Tip: Lower until both knees reach about 90 degrees.', 'Tip: Keep your torso upright as you step.', 'Tip: Drive through your front heel to step forward smoothly.']::text[]),
  ('Wide-Stance Leg Press', 'quads', 'machine', 'weight_reps', 'repdb-wide-stance-leg-press.webp', 'repdb-wide-stance-leg-press-end.webp', ARRAY['Set the back pad and seat so your lower back remains supported at the bottom of the repetition.', 'Place your feet wide on the platform with the toes turned out only as far as the knees can follow comfortably.', 'Lower the sled by bending the hips and knees while keeping the knees aligned with the toes and the feet flat.', 'Press through the whole foot and extend the hips and knees without forcing the knees into lockout.', 'Lower the sled under control and repeat for the desired number of repetitions.', 'Tip: Use a width and toe angle that your hips can control; wider is not automatically better.', 'Tip: Keep the knees moving in the same direction as the toes rather than letting them collapse inward.', 'Tip: Stop the descent before the pelvis rolls under and the lower back loses contact with the pad.']::text[]),
  ('Banded Romanian Deadlift', 'hamstrings', 'band', 'bodyweight_reps', 'repdb-banded-romanian-deadlift.webp', 'repdb-banded-romanian-deadlift-end.webp', ARRAY['Stand on a loop band with both feet and grip the top of the band.', 'Set feet hip-width with a soft bend in the knees.', 'Hinge at the hips, sliding the hands down the legs.', 'Lower until you feel a stretch in the hamstrings.', 'Drive the hips forward to return to standing.', 'Tip: Keep the band close to the legs throughout.', 'Tip: Stop at the bottom of your clean range — no rounded back.', 'Tip: The movement is a hinge, not a squat — knees barely bend.']::text[]),
  ('Banded Standing Leg Curl', 'hamstrings', 'band', 'bodyweight_reps', 'repdb-banded-standing-curl.webp', 'repdb-banded-standing-curl-end.webp', ARRAY['Loop a resistance band around one ankle and anchor the other end under your standing foot or a fixed point in front of you.', 'Stand tall, holding onto something for balance if needed, with a slight bend in the standing knee.', 'Curl the banded heel up and back toward your glute, keeping the thigh still.', 'Squeeze the hamstring at the top, then lower under control to a full stretch.', 'Complete all reps on one side, then switch legs.', 'Tip: Keep the thigh stationary — only the lower leg should move.', 'Tip: Avoid swinging the hips to generate momentum.', 'Tip: Use a lighter band if you can''t control the descent.']::text[]),
  ('EZ-Bar Romanian Deadlift', 'hamstrings', 'barbell', 'weight_reps', 'repdb-ez-bar-romanian-deadlift.webp', 'repdb-ez-bar-romanian-deadlift-end.webp', ARRAY['Stand holding an EZ-bar at mid-thigh with an overhand grip on the inner bends.', 'Feet hip-width, soft bend in the knees, chest up, lats engaged.', 'Push the hips back while letting the bar slide down the front of the legs.', 'Go until you feel a deep hamstring stretch without rounding the lower back.', 'Drive the hips forward to return to standing, keeping the bar close to the body.', 'Repeat for the recommended number of repetitions.', 'Tip: The movement is a hip hinge, not a squat — knees barely bend.', 'Tip: The EZ-bar is shorter than a barbell; grip the inner bends for a neutral-ish wrist.', 'Tip: Stop at the bottom of your clean ROM — no round-back stretch.']::text[]),
  ('Inchworm', 'hamstrings', 'bodyweight', 'bodyweight_reps', 'repdb-inchworm.webp', 'repdb-inchworm-end.webp', ARRAY['Stand tall with your feet about hip-width apart.', 'Hinge forward at the hips and place your hands on the floor in front of your feet, bending the knees slightly if you need to.', 'Walk your hands forward one at a time, keeping your legs as straight as you comfortably can, until your body is in a straight line close to the floor.', 'Bend your elbows so your chest hovers just above the floor, as at the bottom of a push-up, and pause briefly with your trunk braced.', 'Walk your hands back toward your feet in small steps, raising your hips, until you are back in the forward fold.', 'Stand up, or go straight into the next repetition.', 'Tip: Keep the knees as straight as you can so the hamstrings and calves get the stretch; a slight bend is fine if your hands do not reach the floor.', 'Tip: Brace the trunk in the low plank so the hips do not sag or pike up. For an easier version, stop in a straight-arm plank and skip the lowering.', 'Tip: Take small, controlled steps; walking out too far, too fast makes you collapse onto the floor.']::text[]),
  ('One-Arm Single-Leg Dumbbell Romanian Deadlift', 'hamstrings', 'dumbbell', 'weight_reps', 'repdb-one-arm-single-leg-dumbbell-romanian-deadlift.webp', 'repdb-one-arm-single-leg-dumbbell-romanian-deadlift-end.webp', ARRAY['Stand on one leg holding a dumbbell in the opposite hand.', 'Free arm out to the side for balance, free leg hovering just off the floor.', 'Hinge at the standing hip, pushing it back while the free leg extends behind to counterbalance.', 'Keep the hips square to the floor — do not open them to the side.', 'Lower the dumbbell toward the foot of the standing leg, feeling a deep hamstring stretch.', 'Drive the hip forward to return to standing under control.', 'Complete all reps on one side, then switch.', 'Tip: Start lighter than you think — balance and anti-rotation demands are the limit, not hamstring strength.', 'Tip: If you rotate open, pause and reset; a shorter clean ROM beats a full ROM with rotation.', 'Tip: Eyes on a fixed spot on the floor a few feet in front helps balance.']::text[]),
  ('One-Arm Single-Leg Kettlebell Romanian Deadlift', 'hamstrings', 'kettlebell', 'weight_reps', 'repdb-one-arm-single-leg-kettlebell-romanian-deadlift.webp', 'repdb-one-arm-single-leg-kettlebell-romanian-deadlift-end.webp', ARRAY['Stand on one leg holding a kettlebell in the opposite hand by the handle.', 'Free arm out to the side for balance, free leg hovering behind.', 'Hinge at the standing hip, pushing it back while the free leg extends to counterbalance.', 'Keep hips square to the floor; the kettlebell tracks straight down the shin.', 'Feel a deep hamstring stretch on the standing leg at the bottom.', 'Drive the hip forward to return to standing.', 'Complete all reps on one side, then switch.', 'Tip: The kettlebell hangs lower than a dumbbell — shorten the ROM slightly to keep the back flat.', 'Tip: If the bell swings, you are moving too fast. Slow the eccentric.', 'Tip: Build up from the two-arm (dumbbell) single-leg RDL first.']::text[]),
  ('Single Leg Lying Leg Curl', 'hamstrings', 'machine', 'weight_reps', 'repdb-single-leg-lying-leg-curl.webp', 'repdb-single-leg-lying-leg-curl-end.webp', ARRAY['Lie face down on a lying leg curl machine.', 'Position one ankle under the pad, keeping the other foot off the machine.', 'Curl the working leg by bringing your heel toward your glute.', 'Squeeze the hamstring at the top.', 'Lower the leg back down under control.', 'Complete reps on one side, then switch.', 'Tip: Keep your hips pressed into the bench throughout the curl.', 'Tip: Avoid jerking the pad up with momentum.', 'Tip: Start with the weaker leg and match its reps on the other side.']::text[]),
  ('Single Leg Romanian Deadlift', 'hamstrings', 'dumbbell', 'weight_reps', 'repdb-single-leg-romanian-deadlift.webp', 'repdb-single-leg-romanian-deadlift-end.webp', ARRAY['Stand on one leg holding a dumbbell in each hand in front of your thighs.', 'Keep a slight bend in the standing knee.', 'Hinge at the hip while extending the free leg behind you.', 'Lower the dumbbells along your standing leg until you feel a hamstring stretch.', 'Drive through the heel to return to upright.', 'Complete reps on one side, then switch.', 'Tip: Keep your hips square to the floor as you hinge.', 'Tip: Fix your eyes on a spot ahead to help balance.', 'Tip: Reach the rear heel straight back rather than letting the leg swing wide.']::text[]),
  ('TRX Hamstring Curl', 'hamstrings', 'bodyweight', 'bodyweight_reps', 'repdb-trx-hamstring-curl.webp', 'repdb-trx-hamstring-curl-end.webp', ARRAY['Lie on your back with heels in the suspension trainer cradles, knees bent at 90 degrees.', 'Lift your hips off the floor, creating a straight line from knees to shoulders.', 'Extend your legs forward, maintaining hip elevation and core tension.', 'Pull your heels back towards your glutes, contracting your hamstrings forcefully.', 'Control the movement, avoiding any drop in hip height throughout the set.', 'Tip: Keep your core braced to prevent your hips from sagging.', 'Tip: Focus on a strong hamstring contraction at the peak of the curl.', 'Tip: Control the eccentric phase by slowly extending your legs.']::text[]),
  ('Banded Clamshell', 'glutes', 'band', 'bodyweight_reps', 'repdb-banded-clamshell.webp', 'repdb-banded-clamshell-end.webp', ARRAY['Lie on your side with hips and knees bent to roughly 45 degrees, feet stacked.', 'Place a loop band around both legs above the knees.', 'Keep the feet pressed together and the pelvis stable — do not roll back as you move.', 'Open the top knee upward against the band, like a clamshell opening, until you feel the glute fire.', 'Pause briefly at the top, then lower under control to the start.', 'Complete all reps on one side, then switch.', 'Tip: The pelvis stays stacked — the moment you start rocking back, the glute disengages.', 'Tip: Slow controlled tempo beats heavy band; this is a stability drill, not a strength PR.', 'Tip: If you cramp in the side of the hip, that is exactly the right muscle. Shorten the set.']::text[]),
  ('Banded Fire Hydrant', 'glutes', 'band', 'bodyweight_reps', 'repdb-banded-fire-hydrant.webp', 'repdb-banded-fire-hydrant-end.webp', ARRAY['Place a loop band just above your knees and assume a quadruped position with hands under shoulders and knees under hips.', 'Keep your core engaged and back flat, maintaining a neutral spine throughout the movement.', 'Slowly lift one knee out to the side, keeping the knee bent at 90 degrees, until your thigh is parallel to the floor.', 'Hold briefly at the top, squeezing your glute, then slowly lower your leg back to the starting position with control.', 'Complete all repetitions on one side before switching to the other side.', 'Tip: Focus on controlled movement; avoid using momentum to lift your leg.', 'Tip: Keep your hips stable and prevent your torso from rotating or leaning.', 'Tip: Ensure the band stays taut throughout the entire range of motion.']::text[]),
  ('Banded Glute Bridge', 'glutes', 'band', 'bodyweight_reps', 'repdb-banded-glute-bridge.webp', 'repdb-banded-glute-bridge-end.webp', ARRAY['Lie on your back with the knees bent and feet flat on the floor, shoulder-width apart.', 'Place a loop band around both legs just above the knees.', 'Press the lower back into the floor and brace the core.', 'Drive through the heels and squeeze the glutes to lift the hips into a bridge — keep the band tension by pushing the knees outward.', 'At the top, the body forms a straight line from shoulders to knees. Pause briefly.', 'Lower under control to the start and repeat for the recommended number of repetitions.', 'Tip: The knees want to cave inward — that is the band telling you to push them out.', 'Tip: Stop the lift when your hips are level with your shoulders and knees; do not hyperextend the lower back.', 'Tip: Squeeze hard at the top — a fast, half-rep bridge feels easy because it is.']::text[]),
  ('Banded Good Morning', 'glutes', 'band', 'bodyweight_reps', 'repdb-banded-good-morning.webp', 'repdb-banded-good-morning-end.webp', ARRAY['Stand on a loop band with both feet and pass it over the back of your neck.', 'Set feet hip-width with a soft bend in the knees.', 'Hinge at the hips, pushing them back with a flat back.', 'Lower until you feel a stretch in the hamstrings.', 'Drive the hips forward to return to standing.', 'Tip: Move from the hips, not the lower back.', 'Tip: Keep the chest up and the back flat throughout.', 'Tip: Use a band light enough to allow full range of motion.']::text[]),
  ('Banded Hip Thrust', 'glutes', 'band', 'bodyweight_reps', 'repdb-banded-hip-thrust.webp', 'repdb-banded-hip-thrust-end.webp', ARRAY['Place a loop band just above your knees and sit on the floor with your upper back against a bench.', 'Bend your knees, plant your feet hip-width apart, and position the band to create tension.', 'Drive through your heels, extend your hips, and lift your glutes off the floor until your body forms a straight line from shoulders to knees.', 'Squeeze your glutes forcefully at the top, ensuring your knees are pushed out against the band.', 'Slowly lower your hips back to the starting position with control.', 'Tip: Maintain constant tension on the band throughout the movement.', 'Tip: Focus on a strong glute contraction at the peak of the thrust.', 'Tip: Keep your chin tucked and gaze forward to maintain a neutral spine.', 'Tip: Ensure your shins are vertical at the top of the movement.']::text[]),
  ('Banded Kneeling Hip Thrust', 'glutes', 'band', 'bodyweight_reps', 'repdb-banded-kneeling-hip-thrust.webp', 'repdb-banded-kneeling-hip-thrust-end.webp', ARRAY['Anchor a band low on a sturdy post, at the height of your hips when kneeling, and loop it around your hips. Kneel facing away from the post, torso upright and knees hip-width apart, far enough forward that the band is taut.', 'Sit your hips back toward your heels, leaning slightly forward with your back straight and core braced.', 'Initiate the movement by squeezing your glutes, driving your hips forward until your torso is upright.', 'Squeeze your glutes hard at the top, maintaining tension on the band.', 'Slowly reverse the movement, controlling the band''s resistance as you return to the starting position.', 'Tip: Focus on a strong glute contraction at the top of the movement.', 'Tip: Keep your core engaged throughout to prevent arching your lower back.', 'Tip: Kneel far enough from the post that the band stays taut even at the bottom.']::text[]),
  ('Banded Lateral Walk', 'glutes', 'band', 'bodyweight_reps', 'repdb-banded-lateral-walk.webp', 'repdb-banded-lateral-walk-end.webp', ARRAY['Place a loop band around the legs above the knees (or around the ankles for a harder version).', 'Stand in a quarter-squat: feet shoulder-width, hips back, chest up, knees tracking over the toes.', 'Step one foot directly out to the side against the band tension.', 'Bring the trailing foot in toward the lead — keep tension on the band the entire time, do not let the feet snap together.', 'Continue side-stepping in one direction for the prescribed reps or distance, then reverse.', 'Stay low throughout; do not pop up between steps.', 'Tip: Keep the toes pointing straight forward — do not let the lead foot turn out.', 'Tip: Hips stay level; do not rock side-to-side as you step.', 'Tip: If the knees cave inward, the band is too strong — drop to a lighter one.']::text[]),
  ('Banded Seated Hip Abduction', 'glutes', 'band', 'bodyweight_reps', 'repdb-banded-seated-hip-abduction.webp', 'repdb-banded-seated-hip-abduction-end.webp', ARRAY['Sit on a bench or chair with a loop band around your knees.', 'Keep your feet flat on the floor, hip-width apart, and maintain an upright posture.', 'Push your knees outwards against the band, engaging your glutes.', 'Hold the peak contraction briefly, then slowly return your knees to the starting position.', 'Control the movement throughout the entire range of motion.', 'Tip: Focus on squeezing your glutes to initiate the movement.', 'Tip: Avoid leaning back or using momentum; keep your torso stable.', 'Tip: Choose a band resistance that allows for controlled movement.', 'Tip: Maintain tension on the band even in the starting position.']::text[]),
  ('Banded Standing Hip Abduction', 'glutes', 'band', 'bodyweight_reps', 'repdb-banded-standing-hip-abduction.webp', 'repdb-banded-standing-hip-abduction-end.webp', ARRAY['Place a loop band around your ankles or just above your knees.', 'Stand tall with a slight bend in your knees and brace your core.', 'Shift your weight onto one leg, maintaining a stable torso.', 'Slowly abduct the free leg out to the side, feeling the glute contract.', 'Control the movement as you return the leg to the starting position.', 'Complete all reps per side before switching.', 'Tip: Keep your torso upright and avoid leaning to the side.', 'Tip: Focus on a controlled movement, not momentum.', 'Tip: Ensure the band maintains tension throughout the entire range of motion.', 'Tip: Initiate the movement from your hip, not your foot.']::text[]),
  ('Banded Standing Hip Adduction', 'glutes', 'band', 'bodyweight_reps', 'repdb-banded-standing-hip-adduction.webp', 'repdb-banded-standing-hip-adduction-end.webp', ARRAY['Anchor a loop band to a sturdy upright at ankle height.', 'Step into the loop with the working leg facing the anchor side.', 'Stand a few feet away so the band has tension.', 'Sweep the working leg across the body toward the standing leg.', 'Return slowly to the start. Complete reps per side, then switch.', 'Tip: Keep the standing leg slightly bent for stability.', 'Tip: Move only the working leg — torso stays still.', 'Tip: Control the eccentric for full adductor stretch.']::text[]),
  ('Banded Sumo Walk', 'glutes', 'band', 'bodyweight_reps', 'repdb-banded-sumo-walk.webp', 'repdb-banded-sumo-walk-end.webp', ARRAY['Place a loop band around your lower legs, just above the ankles.', 'Drop into a quarter squat with feet wider than shoulder-width.', 'Step sideways in a wide stance, keeping tension on the band.', 'Bring the trailing foot in only partway so the band stays taut, and keep stepping for the prescribed distance before leading with the other leg.', 'Stay low throughout — do not stand up between steps.', 'Tip: Keep tension on the band the entire set.', 'Tip: Stay in a quarter-squat — do not stand tall between steps.', 'Tip: Take small, controlled steps with toes pointed slightly out.']::text[]),
  ('Bent-Knee Copenhagen Raises', 'glutes', 'bodyweight', 'bodyweight_reps', 'repdb-bent-knee-copenhagen-raises.webp', 'repdb-bent-knee-copenhagen-raises-end.webp', ARRAY['Lie on your side next to a flat bench and place the inside of your top leg or foot on it, with the top knee slightly bent or straight.', 'Prop yourself up on the elbow of your lower arm, directly under your shoulder.', 'Lift your hips so that your body forms a straight line from your head to your top leg, and bend the knee of your lower leg under you.', 'Raise the bent lower knee up toward the bench, keeping your hips high.', 'Lower the knee slowly without letting your hips drop, and repeat for the planned repetitions.', 'Rest, then switch sides.', 'Tip: Use this version to build up to the straight-leg Copenhagen raise; the bent knee shortens the lever and lowers the load.', 'Tip: Keep your hips high and your body in one line; dropping the hips takes the load off the inner thighs.', 'Tip: Move slowly and stop if you feel a sharp pull in the groin; the adductors need a gentle build-up.']::text[]),
  ('Clamshells', 'glutes', 'bodyweight', 'bodyweight_reps', 'repdb-clamshells.webp', 'repdb-clamshells-end.webp', ARRAY['Lie on your side with knees bent and stacked on top of each other.', 'Keep your feet together and hips stacked.', 'Open your top knee toward the ceiling without rotating your hips.', 'Squeeze your outer glute at the top.', 'Lower under control. Complete reps on one side, then switch.', 'Tip: Place a hand on your top hip to check for unwanted rolling.', 'Tip: Keep the movement small and controlled rather than forcing the knee high.', 'Tip: Rest your head on your lower arm to keep your spine neutral.']::text[]),
  ('Copenhagen Plank', 'glutes', 'bodyweight', 'duration', 'repdb-copenhagen-plank.webp', null, ARRAY['Lie on your side next to a flat bench and place your top leg on it, with the inside of the foot or the lower part of the leg resting on the bench.', 'Prop yourself up on the elbow of your lower arm, directly under your shoulder.', 'Lift your hips so that your body forms a straight line from your head to your top foot, and let the lower leg hang or lift it toward the bench.', 'Keep your hips high and your trunk steady, and breathe evenly.', 'Hold for the planned time, then lower your hips back to the floor.', 'Rest, then switch sides.', 'Tip: Start with the top knee on the bench and a short lever; move the foot of the top leg onto the bench only when the hold feels easy.', 'Tip: Press your forearm into the floor and keep your shoulder away from your ear.', 'Tip: Stop if you feel a sharp pull in the groin; the adductors need a gentle build-up.']::text[]),
  ('Copenhagen Plank Raises', 'glutes', 'bodyweight', 'bodyweight_reps', 'repdb-copenhagen-plank-raises.webp', 'repdb-copenhagen-plank-raises-end.webp', ARRAY['Lie on your side next to a flat bench and place your top leg on it, with the knee or the inner foot resting on the bench.', 'Prop yourself up on the elbow of your lower arm, directly under the shoulder.', 'Lift your hips so that your body forms a straight line from your head to your top foot, with the lower leg hanging underneath.', 'Raise the lower leg up toward the bench until it nearly touches the top leg, keeping your hips high.', 'Lower the lower leg slowly without letting your hips drop, and repeat for the planned repetitions.', 'Rest, then switch sides.', 'Tip: Start with the top knee on the bench and a short lever; move the foot of the top leg onto the bench only when the raises feel easy.', 'Tip: Keep your hips high and your body in one line; dropping the hips takes the load off the inner thighs.', 'Tip: Move slowly and stop if you feel a sharp pull in the groin; the adductors need a gentle build-up.']::text[]),
  ('Double Dumbbell Kickstand Deadlift', 'glutes', 'dumbbell', 'weight_reps', 'repdb-double-db-kickstand-deadlift.webp', 'repdb-double-db-kickstand-deadlift-end.webp', ARRAY['Step one foot back so only the toes touch the floor, and hinge at the hips with a flat back.', 'Hold a dumbbell in each hand, low on either side of the front shin.', 'Drive through the front heel and extend the hips to stand tall, the dumbbells at your sides.', 'Keep most of your weight on the front foot throughout.', 'Hinge back down, lowering both dumbbells toward the floor with a flat back. Switch sides after all reps.', 'Tip: Keep the dumbbells close to the legs throughout the movement.', 'Tip: Stop when you feel a stretch in the front hamstring.', 'Tip: Complete all reps on one side before switching.']::text[]),
  ('Double Kettlebell Clean', 'glutes', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-clean.webp', 'repdb-double-kettlebell-clean-end.webp', ARRAY['Stand with two kettlebells on the floor between your feet, handles angled slightly inward.', 'Hinge at the hips, grip the handles, and hike the kettlebells back between the legs.', 'Explosively extend the hips to drive the kettlebells up along the body.', 'As they reach chest height, spear your hands through the handles to catch them at the rack position on the shoulders.', 'Lower back to the hang by hinging at the hips and guiding the bells between the legs.', 'Repeat for the recommended number of repetitions.', 'Tip: Spear the hands through — don''t let the kettlebells flip over and bang the wrists.', 'Tip: Drive with the hips; the arms only guide the path.']::text[]),
  ('Double Kettlebell Dead Clean', 'glutes', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-dead-clean.webp', 'repdb-double-kettlebell-dead-clean-end.webp', ARRAY['Set two kettlebells on the floor between your feet.', 'Hinge down and grip both handles.', 'Drive explosively through your legs and hips.', 'Pull the kettlebells up and rotate them to the rack position.', 'Lower them back to the floor and repeat.', 'Tip: Guide the bells close to your body as they travel up.', 'Tip: Keep your wrists straight as the bells settle into the rack.', 'Tip: Reset a tight hinge position before every rep.']::text[]),
  ('Double Kettlebell Swing Snatch', 'glutes', 'kettlebell', 'weight_reps', 'repdb-double-kettlebell-swing-snatch.webp', 'repdb-double-kettlebell-swing-snatch-end.webp', ARRAY['Stand with feet shoulder-width apart holding two kettlebells.', 'Hinge at the hips to swing the bells between your legs.', 'Explosively drive your hips forward to swing the bells up.', 'Punch through to catch both kettlebells overhead with locked arms.', 'Lower under control and repeat.', 'Tip: Keep your arms relaxed and let your hips generate the power.', 'Tip: Let the bells roll smoothly around your wrists rather than flipping over.', 'Tip: Maintain a flat back during every backswing.']::text[]),
  ('Dumbbell Hip Thrust', 'glutes', 'dumbbell', 'weight_reps', 'repdb-dumbbell-hip-thrust.webp', 'repdb-dumbbell-hip-thrust-end.webp', ARRAY['Sit on the floor with your upper back against a bench, knees bent, feet flat, and a dumbbell across your hips.', 'Brace your core and drive through your heels, lifting your hips off the floor until your body forms a straight line from shoulders to knees.', 'Squeeze your glutes powerfully at the top of the movement, ensuring full hip extension.', 'Slowly lower your hips back down to the starting position with control, maintaining tension.', 'Repeat for the desired number of repetitions.', 'Tip: Keep your chin tucked towards your chest to maintain a neutral spine throughout the movement.', 'Tip: Focus on driving through your heels to maximize glute activation.', 'Tip: Control the eccentric (lowering) phase to enhance muscle growth.', 'Tip: Use a pad or towel under the dumbbell for comfort.']::text[]),
  ('Dumbbell Kickstand Deadlift', 'glutes', 'dumbbell', 'weight_reps', 'repdb-db-kickstand-deadlift.webp', 'repdb-db-kickstand-deadlift-end.webp', ARRAY['Step one foot back so only the toes lightly touch the floor, and hinge at the hips with a flat back.', 'Hold a dumbbell in one hand, low beside the front foot.', 'Drive through the front heel and extend the hips to stand tall, the dumbbell at your side.', 'Keep most of your weight on the front foot throughout.', 'Hinge back down, lowering the dumbbell toward the floor with a flat back. Complete all reps, then switch sides.', 'Tip: Keep the dumbbell close to the shin on the descent.', 'Tip: Stop when you feel a stretch in the front hamstring.', 'Tip: Complete all reps on one side before switching.']::text[]),
  ('Fire Hydrant', 'glutes', 'bodyweight', 'bodyweight_reps', 'repdb-fire-hydrant.webp', 'repdb-fire-hydrant-end.webp', ARRAY['Set up on hands and knees with the hands under the shoulders, the knees under the hips and the back flat.', 'Brace the trunk so the hips stay level and square to the floor.', 'Keeping the knee bent at about 90 degrees, lift one knee out to the side until the thigh is roughly parallel to the floor.', 'Pause briefly at the top without rotating the pelvis or leaning away from the working side.', 'Lower the knee back to the starting position under control.', 'Complete the repetitions on one side, then switch legs.', 'Tip: Move only at the hip; if the lower back twists or the torso tips, the range is too big.', 'Tip: Keep the knee bent at the same angle for the whole set.', 'Tip: Press the supporting hand and knee into the floor so the standing side does not sag.']::text[]),
  ('Hang Power Clean', 'glutes', 'barbell', 'weight_reps', 'repdb-hang-power-clean.webp', 'repdb-hang-power-clean-end.webp', ARRAY['Stand with feet hip-width apart holding a barbell at your thighs.', 'Hinge at the hips to lower the bar to just above the knees.', 'Drive through your hips and legs explosively.', 'Pull the bar up and catch it on your front shoulders in a partial squat.', 'Stand tall with the bar racked on your shoulders.', 'Lower the bar back to the hang position.', 'Tip: Drive through your hips and legs before the arms pull.', 'Tip: Receive the bar with your thighs above parallel.', 'Tip: Keep your back flat as you hinge to the start position.']::text[]),
  ('Hang Snatch', 'glutes', 'barbell', 'weight_reps', 'repdb-hang-snatch.webp', 'repdb-hang-snatch-end.webp', ARRAY['Stand with a wide snatch grip on a barbell held at the thighs and the feet about hip-width apart.', 'Hinge at the hips to lower the bar to just above the knees, keeping the back flat and the shoulders over the bar.', 'Explosively extend the hips, knees and ankles, shrugging as the bar rises.', 'Pull yourself under the bar and catch it overhead with locked arms in a squat.', 'Stand up fully with the bar overhead and stable.', 'Lower the bar under control back to the thighs and reset.', 'Tip: Keep the bar close to the body throughout the pull.', 'Tip: Finish the pull with full extension before dropping under the bar.', 'Tip: Learn the movement with a light bar or a dowel; the wide overhead catch needs good shoulder and hip mobility.']::text[]),
  ('Kettlebell Hip Thrust', 'glutes', 'kettlebell', 'weight_reps', 'repdb-kettlebell-hip-thrust.webp', 'repdb-kettlebell-hip-thrust-end.webp', ARRAY['Sit on the floor with your upper back against a bench, knees bent, and feet flat.', 'Place a kettlebell across your hips, holding it securely with both hands.', 'Drive through your heels, lifting your hips off the floor until your body forms a straight line from shoulders to knees.', 'Squeeze your glutes forcefully at the top of the movement.', 'Slowly lower your hips back down to the starting position with control.', 'Tip: Keep your chin tucked towards your chest to maintain a neutral spine.', 'Tip: Focus on pushing through your heels to maximize glute activation.', 'Tip: Ensure your knees track in line with your toes throughout the movement.', 'Tip: Control the eccentric phase, resisting the weight as you lower your hips.']::text[]),
  ('Kettlebell Kickstand Deadlift', 'glutes', 'kettlebell', 'weight_reps', 'repdb-kettlebell-kickstand-deadlift.webp', 'repdb-kettlebell-kickstand-deadlift-end.webp', ARRAY['Set a kettlebell on the floor beside the front foot and step the other foot back so only its toes touch the floor.', 'Hinge at the hips with a flat back and grip the kettlebell handle with one hand.', 'Drive through the front heel and extend the hips to stand tall, the kettlebell at your side.', 'Keep most of your weight on the front foot throughout.', 'Hinge back down, lowering the kettlebell toward the floor with a flat back. Switch sides after all reps.', 'Tip: Keep the kettlebell close to the shin on the descent.', 'Tip: Stop at the point of hamstring stretch in the front leg.', 'Tip: Complete all reps on one side before switching.']::text[]),
  ('Kettlebell Sumo Deadlift', 'glutes', 'kettlebell', 'weight_reps', 'repdb-kettlebell-sumo-deadlift.webp', 'repdb-kettlebell-sumo-deadlift-end.webp', ARRAY['Stand in a wide stance with toes pointed slightly out, a kettlebell on the floor between the feet.', 'Hinge down with a flat back, knees tracking over the toes, and grip the handle with both hands.', 'Drive through the floor and extend the hips and knees together to stand up.', 'Squeeze the glutes at the top.', 'Lower the bell under control back to the floor by pushing the hips back.', 'Repeat for the recommended number of repetitions.', 'Tip: Knees track out over the toes — do not let them cave in.', 'Tip: Shoulders stay above the hips at the bottom; if the shoulders drop, narrow the stance.', 'Tip: Keep the bell close to the body throughout the lift.']::text[]),
  ('Kettlebell Sumo High Pull', 'glutes', 'kettlebell', 'weight_reps', 'repdb-kettlebell-sumo-high-pull.webp', 'repdb-kettlebell-sumo-high-pull-end.webp', ARRAY['Stand with feet wider than shoulder-width, toes slightly turned out, a kettlebell on the floor between the feet.', 'Hinge down and grip the handle with both hands.', 'Drive through the feet and extend the hips explosively to pull the kettlebell up.', 'As it rises, pull the elbows up and out until the handle reaches chin height.', 'Lower the kettlebell back between the legs under control.', 'Repeat for the recommended number of repetitions.', 'Tip: Drive with the hips first; the arms finish the movement.', 'Tip: Keep the elbows higher than the hands at the top — think wide and high, not narrow.']::text[]),
  ('Kettlebell Swing Clean', 'glutes', 'kettlebell', 'weight_reps', 'repdb-kettlebell-swing-clean.webp', 'repdb-kettlebell-swing-clean-end.webp', ARRAY['Stand with feet shoulder-width apart, kettlebell between your feet.', 'Hinge at the hips and grip the handle with one hand.', 'Swing the kettlebell back between your legs.', 'Drive your hips forward to pull the kettlebell up to your shoulder.', 'Catch the kettlebell in the rack position on your shoulder.', 'Complete reps on one side, then switch.', 'Tip: Keep the kettlebell close to your body on the way up.', 'Tip: Let the kettlebell roll around your wrist rather than flipping over it.', 'Tip: Relax your grip slightly at the top for a soft catch.']::text[]),
  ('One Arm Kettlebell Floor Glute Bridge Press', 'glutes', 'kettlebell', 'weight_reps', 'repdb-one-arm-kettlebell-floor-glute-bridge-press.webp', 'repdb-one-arm-kettlebell-floor-glute-bridge-press-end.webp', ARRAY['Lie on your back with knees bent and feet flat on the floor.', 'Hold a kettlebell in one hand at your shoulder.', 'Drive your hips up into a glute bridge.', 'Press the kettlebell straight up toward the ceiling.', 'Lower the kettlebell and your hips with control.', 'Complete reps on one side, then switch.', 'Tip: Hold the bridge steady at the top while pressing.', 'Tip: Keep your wrist straight and stacked under the kettlebell.', 'Tip: Extend your free arm along the floor for extra stability.']::text[]),
  ('One Arm Kettlebell Swing', 'glutes', 'kettlebell', 'weight_reps', 'repdb-one-arm-kettlebell-swing.webp', 'repdb-one-arm-kettlebell-swing-end.webp', ARRAY['Stand with feet shoulder-width apart and a kettlebell on the floor in front of you.', 'Hinge at the hips and grip the kettlebell with one hand.', 'Hike the kettlebell back between your legs.', 'Drive your hips forward to swing the kettlebell to chest height.', 'Let gravity bring the kettlebell back between your legs.', 'Complete reps on one side, then switch.', 'Tip: Keep your shoulders square as the offset load tries to rotate you.', 'Tip: Power the movement with your hips, not by lifting with your arm.', 'Tip: Hinge with a flat back rather than squatting the swing.']::text[]),
  ('One-Arm Dumbbell Swing', 'glutes', 'dumbbell', 'weight_reps', 'repdb-one-arm-dumbbell-swing.webp', 'repdb-one-arm-dumbbell-swing-end.webp', ARRAY['Stand with feet shoulder-width apart, a dumbbell on the floor slightly in front of you.', 'Hinge at your hips, keeping a flat back, and grasp the dumbbell with one hand.', 'Hike the dumbbell back between your legs, then explosively drive your hips forward.', 'Swing the dumbbell up to chest height, keeping your arm relaxed and straight.', 'Allow the dumbbell to swing back down, hinging at the hips as it descends.', 'Repeat for desired reps per side, maintaining control.', 'Tip: Focus on driving with your hips, not pulling with your arm.', 'Tip: Keep your core braced throughout the movement for stability.', 'Tip: Maintain a neutral spine; avoid rounding your back.', 'Tip: Control the eccentric phase as the dumbbell swings down.']::text[]),
  ('Plate-Loaded Glute Drive', 'glutes', 'machine', 'weight_reps', 'repdb-plate-loaded-glute-drive.webp', 'repdb-plate-loaded-glute-drive-end.webp', ARRAY['Load the plate horns evenly and sit into the machine with your upper back against the pad and your feet flat on the platform.', 'Pull the hip pad or lap bar across your hips and adjust it so it sits on the crease of the hips, not on your stomach.', 'Set your feet so that your shins will be roughly vertical when your hips are at the top, and take hold of the handles.', 'Drive your hips up by squeezing the glutes until your thighs are level with your torso, and hold briefly at the top.', 'Lower under control until your hips are just short of the bottom of the range, and repeat for the desired number of repetitions.', 'Tip: Get the pad on the hip crease. Sitting it up on the stomach is the only genuinely uncomfortable thing this machine does, and it is fixed by moving the pad, not by adding padding.', 'Tip: Finish with the hips, not the lower back. If the ribs flare at the top you have run out of hip extension and started arching, which is where the machine stops training the glutes.', 'Tip: This is the hip thrust to reach for when the bench and barbell are taken -- the back pad and platform are part of the frame, so there is no setup to get wrong.']::text[]),
  ('Reverse Tabletop Hip Pulses', 'glutes', 'bodyweight', 'bodyweight_reps', 'repdb-reverse-tabletop-hip-pulses.webp', 'repdb-reverse-tabletop-hip-pulses-end.webp', ARRAY['Sit with the knees bent, the feet flat and the hands on the floor behind you.', 'Press into the hands and feet and lift the hips until the trunk is level with the knees.', 'Keeping the elbows straight, lower the hips a few centimetres.', 'Squeeze the glutes to lift them back to level.', 'Pulse for the desired number of repetitions and lower down.', 'Tip: Keep the arms locked: bending the elbows turns this into a dip.', 'Tip: Drive the lift from the heels and the glutes, not from the lower back.', 'Tip: Keep the chest open and the shoulders down away from the ears.']::text[]),
  ('Sandbag Carry', 'glutes', 'other', 'weight_reps', 'repdb-sandbag-carry.webp', null, ARRAY['Stand over a sandbag, squat down and wrap both arms around it, with your hands or forearms locked together underneath it.', 'Lift the sandbag by standing up, and hold it tight against your chest.', 'Brace your trunk and keep your chest tall, with the bag high enough that it does not pull your shoulders forward.', 'Walk forward with short, controlled steps for the planned distance or time.', 'Keep squeezing the bag throughout the walk.', 'Lower the bag to the floor with a straight back by squatting down.', 'Tip: Hold the bag high on your chest; if it slides down, your lower back takes the load.', 'Tip: Take short steps and keep your hips level rather than swaying with the bag.', 'Tip: Start with a lighter bag until you can walk the full distance with a tall posture.']::text[]),
  ('Side Lying Hip Adduction', 'glutes', 'bodyweight', 'bodyweight_reps', 'repdb-side-lying-hip-adduction.webp', 'repdb-side-lying-hip-adduction-end.webp', ARRAY['Lie on your side with your bottom leg straight.', 'Bend your top leg and place its foot flat in front of the bottom thigh.', 'Support your head with your bottom arm.', 'Lift the bottom leg upward toward the ceiling.', 'Lower the leg back down under control.', 'Complete reps on one side, then switch.', 'Tip: Keep your hips stacked vertically to avoid rolling backward.', 'Tip: Keep the movement slow and deliberate through the short range of motion.', 'Tip: Pause briefly at the top of each lift.']::text[]),
  ('Side Plank with Leg Lift', 'glutes', 'bodyweight', 'bodyweight_reps', 'repdb-side-plank-leg-lift.webp', 'repdb-side-plank-leg-lift-end.webp', ARRAY['Lie on your side with the forearm on the floor, elbow under the shoulder.', 'Stack the feet and lift the hips into a side plank.', 'From this stable side plank, raise the top leg straight up toward the ceiling.', 'Lower the leg back down with control without dropping the hips.', 'Complete reps on one side, then switch.', 'Tip: Keep the hips lifted the entire set — do not let them sag.', 'Tip: Lead the leg lift with the heel, not the toes.', 'Tip: Keep the body in one straight line from head to bottom foot.']::text[]),
  ('Side-Lying Hip Abduction', 'glutes', 'bodyweight', 'bodyweight_reps', 'repdb-side-lying-hip-abduction.webp', 'repdb-side-lying-hip-abduction-end.webp', ARRAY['Lie on your side with legs stacked.', 'Keep the bottom leg slightly bent.', 'Raise the top leg toward the ceiling.', 'Lower under control.', 'Repeat on both sides.', 'Tip: Keep hips stacked throughout.', 'Tip: Avoid tilting the pelvis.']::text[]),
  ('Single-Leg Hip Thrust', 'glutes', 'bodyweight', 'bodyweight_reps', 'repdb-single-leg-hip-thrust.webp', 'repdb-single-leg-hip-thrust-end.webp', ARRAY['Sit on the floor with your back to a flat bench and rest your upper back against its edge, just below your shoulder blades.', 'Plant both feet flat on the floor with your knees bent, then lift one knee toward your chest and keep it there.', 'Keep your chin tucked toward your chest and your arms resting along the bench.', 'Drive through the heel of the planted foot and push your hips up until your body is level from your shoulders to your knee.', 'Squeeze your glute at the top without arching your lower back, then lower your hips under control.', 'Complete the planned repetitions, then switch legs.', 'Tip: Keep the planted shin close to vertical at the top so the glute, rather than the hamstring, does most of the work.', 'Tip: Do not let your hips twist toward the lifted leg; keep your pelvis level throughout.', 'Tip: Anchor the bench against a wall so it cannot slide, and start with the two-leg hip thrust until the movement is smooth.']::text[]),
  ('Smith Machine Hip Thrust', 'glutes', 'machine', 'weight_reps', 'repdb-smith-machine-hip-thrust.webp', 'repdb-smith-machine-hip-thrust-end.webp', ARRAY['Set a flat bench inside the Smith machine, parallel to the bar and positioned so the bar will sit over your hip crease.', 'Set the bar low enough that you can get under it while seated on the floor, then sit with your upper back against the bench.', 'Slide your hips under the bar so it sits over your hip crease, pad it if you need to, and unhook it with your feet flat and about hip-width apart.', 'Drive through your heels and extend your hips until your thighs and torso form a straight line, squeezing the glutes at the top.', 'Lower your hips under control until they are just off the floor, and repeat for the desired number of repetitions.', 'Tip: Line the bench up before you load the bar. The bar can only move straight up and down, so if the bench is out of place the bar lands on your stomach or your thighs and there is no adjusting mid-set.', 'Tip: Set the safety stops where the bar sits at the bottom of your range. Getting out from under a loaded Smith bar on the floor is awkward, and the stops make it a non-event.', 'Tip: Look at a point in front of you rather than at the ceiling. Keeping the chin tucked stops the movement turning into a lower-back arch at lockout.']::text[]),
  ('Standing Hip Abduction', 'glutes', 'bodyweight', 'bodyweight_reps', 'repdb-standing-hip-abduction.webp', 'repdb-standing-hip-abduction-end.webp', ARRAY['Stand tall with your hands on your hips and your feet close together.', 'Shift your weight onto one leg and keep that knee slightly bent.', 'Lift the other leg straight out to the side, keeping the toes pointing forward and your trunk upright.', 'Raise the leg only as high as you can without leaning your upper body away from it.', 'Lower the leg slowly back next to the standing foot.', 'Complete the planned repetitions, then repeat on the other leg.', 'Tip: Keep your hips square and your trunk still; leaning away from the lifted leg takes the work away from the hip.', 'Tip: Move with control on the way down as well; do not let the leg swing.', 'Tip: Hold on to a wall or a chair if you cannot stay balanced; add a loop band around your thighs once the movement is easy.']::text[]),
  ('Wall Ball', 'glutes', 'other', 'weight_reps', 'repdb-wall-ball.webp', null, ARRAY['Stand facing a wall about an arm''s length away, feet shoulder-width apart, holding the ball at your chest with both hands.', 'Keep your elbows under the ball and your chest up.', 'Squat down until your hips are at or below knee height, keeping your heels on the floor.', 'Drive up hard through your legs and hips and, as you rise, throw the ball up to the target with both arms.', 'Catch the ball at chest height as it comes down, letting your arms absorb it.', 'Go straight into the next squat with the catch and repeat for the planned repetitions.', 'Tip: Let the legs throw the ball: the push from the squat should carry it most of the way, the arms only finish the movement.', 'Tip: Keep your chest up and the ball close to your body in the squat so your back stays neutral.', 'Tip: Catch and squat in one movement; resting with the ball at the top breaks the rhythm and tires the shoulders.']::text[]),
  ('Wall Sit', 'glutes', 'bodyweight', 'duration', 'repdb-wall-sit.webp', null, ARRAY['Stand with back against a wall.', 'Slide down until thighs are parallel to the floor.', 'Hold the position.', 'Stand back up when done.', 'Tip: Keep knees at 90 degrees.', 'Tip: Press your back flat against the wall.']::text[]),
  ('Bodyweight Calf Raise', 'calves', 'bodyweight', 'bodyweight_reps', 'repdb-bodyweight-calf-raise.webp', 'repdb-bodyweight-calf-raise-end.webp', ARRAY['Stand with feet hip-width apart on a flat surface.', 'Push up onto the balls of your feet as high as possible.', 'Squeeze your calves at the top.', 'Lower your heels back to the floor under control.', 'Repeat for the desired number of reps.', 'Tip: Use light fingertip support for balance if needed.', 'Tip: Control the lowering phase instead of dropping your heels quickly.', 'Tip: Keep your ankles from rolling outward as you rise.']::text[]),
  ('Hack Squat Calf Raise', 'calves', 'machine', 'weight_reps', 'repdb-hack-squat-calf-raise.webp', 'repdb-hack-squat-calf-raise-end.webp', ARRAY['Load yourself into a hack squat machine with shoulders under the pads.', 'Place the balls of your feet on the platform with heels hanging off.', 'Keep your legs straight with a slight knee bend.', 'Press through the balls of your feet to raise your heels.', 'Lower your heels back below the platform for a stretch.', 'Repeat for the desired number of reps.', 'Tip: Rise as high onto the balls of your feet as possible.', 'Tip: Pause in the bottom stretch instead of bouncing out of it.', 'Tip: Keep your knees straight but not locked to keep tension on the calves.']::text[]),
  ('Kettlebell Tibialis Raise', 'calves', 'kettlebell', 'weight_reps', 'repdb-kettlebell-tibialis-raise.webp', 'repdb-kettlebell-tibialis-raise-end.webp', ARRAY['Sit at the end of a flat bench with one leg extended and the heel resting on the floor.', 'Hang a kettlebell by its handle from the front of the foot, over the toes.', 'Pull the toes up toward the shin as far as is comfortable while the heel stays on the floor.', 'Hold briefly at the top.', 'Lower the foot slowly until the toes point toward the floor.', 'Complete the repetitions, then switch legs.', 'Tip: Keep the movement at the ankle; the knee and thigh stay still.', 'Tip: Start with a light kettlebell and increase gradually; the shin muscles tire quickly.', 'Tip: Lower slowly rather than letting the weight drop.']::text[]),
  ('Machine Calf Raise', 'calves', 'machine', 'weight_reps', 'repdb-machine-calf-raise.webp', 'repdb-machine-calf-raise-end.webp', ARRAY['Stand in the calf raise machine with the balls of your feet on the platform.', 'Position the shoulder pads firmly.', 'Lower your heels below the platform for a full stretch.', 'Push through the balls of your feet to rise onto your toes.', 'Squeeze your calves at the top.', 'Lower with control and repeat.', 'Tip: Keep your knees straight but not locked throughout the movement.', 'Tip: Pause briefly in the stretched position instead of bouncing.', 'Tip: Avoid cutting the range of motion short as fatigue sets in.']::text[]),
  ('Plate-Loaded Donkey Calf Raise', 'calves', 'machine', 'weight_reps', 'repdb-plate-loaded-donkey-calf-raise.webp', 'repdb-plate-loaded-donkey-calf-raise-end.webp', ARRAY['Load the plate horns and step onto the platform with the balls of your feet on the edge and your heels hanging free.', 'Bend forward at the hips and settle the pad across your hips, then rest your forearms on the support in front of you.', 'Keep your knees straight and your back flat, with your torso close to parallel to the floor.', 'Push through the balls of your feet and raise your heels as high as you can, pausing briefly at the top.', 'Lower your heels below the platform until you feel a strong calf stretch, and repeat for the desired number of repetitions.', 'Tip: The forward hinge is the exercise. Standing up straight turns this into an ordinary standing calf raise and gives away the extra stretch you came for.', 'Tip: Keep the knees straight throughout. Bending them shifts the work from the gastrocnemius to the soleus, which is the seated calf raise, not this one.', 'Tip: Let the heels drop all the way below the platform edge. The bottom of the range is where this machine earns its place, and cutting it short wastes the setup.']::text[]),
  ('Single Leg Calf Raise', 'calves', 'bodyweight', 'bodyweight_reps', 'repdb-single-leg-calf-raise.webp', 'repdb-single-leg-calf-raise-end.webp', ARRAY['Stand on one foot on the floor and lift the other foot off the ground, knee bent.', 'Keep the arms relaxed at your sides and brace your core to hold your balance.', 'Drive up onto the ball of the foot as high as possible.', 'Lower the heel back to the floor under control.', 'Complete all reps on one side, then switch.', 'Tip: Pause at the top to maximize the contraction.', 'Tip: Lower slowly instead of dropping onto the heel.', 'Tip: Hold a dumbbell on the working side once bodyweight is too easy.']::text[]),
  ('Bench Leg Pull-In', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-bench-leg-pull-in.webp', 'repdb-bench-leg-pull-in-end.webp', ARRAY['Sit on a flat bench, grip its edges beside or just behind your hips and lean your torso back slightly.', 'Extend your legs out in front of you with your feet off the floor.', 'Pull your knees toward your chest, bringing the torso slightly forward to meet them.', 'Extend the legs back out under control without letting your feet touch the floor.', 'Repeat for the desired number of repetitions.', 'Tip: Keep your chest lifted and your back straight; do not round forward.', 'Tip: Control the eccentric; do not let gravity drop the legs.', 'Tip: Squeeze the abs at the top of each rep for a stronger contraction.']::text[]),
  ('Captain''s Chair Leg Raise', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-captains-chair-leg-raise.webp', 'repdb-captains-chair-leg-raise-end.webp', ARRAY['Position yourself in the captain''s chair with your back flat against the pad and forearms on the armrests.', 'Let your legs hang straight down.', 'Keeping your legs straight, raise them until parallel with the floor or higher.', 'Hold briefly at the top, then lower slowly.', 'Repeat for the desired reps.', 'Tip: Keep your legs as straight as possible throughout.', 'Tip: Avoid swinging — control the movement with your core.', 'Tip: For less difficulty, bend the knees slightly.']::text[]),
  ('Cocoons', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-cocoons.webp', 'repdb-cocoons-end.webp', ARRAY['Lie face-up on the floor with arms extended overhead and legs extended, hovering slightly off the floor.', 'Simultaneously tuck the knees toward the chest and sweep the arms forward into a crunch.', 'Try to touch the hands to the shins at the top.', 'Reverse the motion smoothly, re-extending arms and legs back to the hover.', 'Repeat for the recommended number of repetitions.', 'Tip: Feet and hands never touch the floor between reps — that''s the whole drill.', 'Tip: Exhale sharply at the top of the tuck.']::text[]),
  ('Cross-Body Crunch', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-cross-body-crunch.webp', 'repdb-cross-body-crunch-end.webp', ARRAY['Lie face-up on the floor with knees bent and hands lightly behind the ears.', 'Crunch up and rotate, bringing the right elbow toward the left knee as the knee draws up.', 'Return to the starting position under control.', 'Repeat on the other side, alternating every rep.', 'Tip: Twist from the ribcage, not the arms; the elbows follow the shoulders.', 'Tip: Lower back stays on the floor throughout.']::text[]),
  ('Dragon Flag', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-dragon-flag.webp', 'repdb-dragon-flag-end.webp', ARRAY['Lie on a bench and grip it firmly behind your head.', 'Raise your body up so only your upper back stays on the bench.', 'Keep your body rigid in a straight line.', 'Lower your body under control until nearly horizontal.', 'Raise back up and repeat.', 'Tip: Keep your body rigid from shoulders to toes and move only at the shoulders.', 'Tip: Lower as slowly as you can — the eccentric is the exercise.', 'Tip: Start with tucked or single-leg progressions before the full flag.']::text[]),
  ('Extended Side Angle Pose', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-extended-side-angle.webp', null, ARRAY['Stand wide with the front foot turned out and the back foot angled slightly in.', 'Bend the front knee until it stacks over the ankle and keep the back leg straight.', 'Rest the front forearm on the thigh, or the hand on the floor or a block, and reach the top arm over the ear.', 'Hold the position for the prescribed time, turning the chest towards the ceiling.', 'Straighten the front leg to come up and repeat on the other side.', 'Tip: Press the outer edge of the back foot down; the pose loses its base as soon as that heel lifts.', 'Tip: Keep the front knee pointing at the middle toes rather than drifting inwards.', 'Tip: Take the forearm on the thigh instead of the hand on the floor to keep the chest open.']::text[]),
  ('Hanging Knee Raise', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-hanging-knee-raise.webp', 'repdb-hanging-knee-raise-end.webp', ARRAY['Hang from a pull-up bar with an overhand grip, arms fully extended.', 'Engage your core and raise your knees toward your chest.', 'Hold briefly at the top.', 'Lower your legs slowly back to the starting position.', 'Repeat for the desired reps.', 'Tip: Avoid swinging — initiate the movement from your core.', 'Tip: Exhale as you raise your knees.', 'Tip: Progress to straight-leg raises when this feels easy.']::text[]),
  ('Hanging L-Sit', 'core', 'bodyweight', 'duration', 'repdb-hanging-l-sit.webp', null, ARRAY['Hang from a pull-up bar with an overhand grip, arms straight and the shoulders pulled down.', 'Brace the abdominals and lift the straight legs until they are parallel to the floor.', 'Keep the knees locked and the toes pointed, with the legs together.', 'Hold the position without swinging, breathing steadily.', 'Lower the legs under control to a dead hang.', 'Tip: If the legs drop below parallel, bend the knees (a tuck hold) and build up from there.', 'Tip: Keep the shoulders active; do not hang passively from the joints.', 'Tip: Squeeze the legs together and point the toes to keep the line tight.']::text[]),
  ('Hanging Pike', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-hanging-pike.webp', 'repdb-hanging-pike-end.webp', ARRAY['Hang from a pull-up bar with a shoulder-width overhand grip.', 'Engage the lats and brace the core to create a hollow body.', 'Keeping the legs perfectly straight, lift them in a smooth arc up to the bar.', 'Aim to touch the toes to the bar between the hands.', 'Lower the legs slowly back to the hanging position and repeat.', 'Tip: No swinging — every rep starts from a dead hang with a braced trunk.', 'Tip: If full range is too hard, raise only to horizontal and build up.']::text[]),
  ('Heel Touches', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-heel-touches.webp', 'repdb-heel-touches-end.webp', ARRAY['Lie on your back with the knees bent and the feet flat on the floor, about hip-width apart.', 'Lift the head and shoulders slightly off the floor and reach the arms down along your sides.', 'Crunch to one side and reach that hand toward the heel on the same side.', 'Return to the center and reach toward the opposite heel.', 'Keep alternating sides in a smooth rhythm while the lower back stays on the floor.', 'Continue for the desired number of repetitions.', 'Tip: Keep the neck long and the chin off the chest; lead with the ribcage, not the head.', 'Tip: Keep each reach small and controlled; the shoulder blades only just clear the floor.', 'Tip: Keep the feet planted and the lower back pressed into the floor throughout.']::text[]),
  ('High Plank', 'core', 'bodyweight', 'duration', 'repdb-high-plank.webp', null, ARRAY['Start in a push-up position with arms fully extended.', 'Keep your body in a straight line from head to heels.', 'Brace your core and hold the position.', 'Breathe steadily throughout.', 'Tip: Stack your shoulders directly above your wrists.', 'Tip: Squeeze your glutes to keep your hips from sagging.', 'Tip: Push the floor away to avoid sinking between your shoulder blades.']::text[]),
  ('Hollow Body Hold', 'core', 'bodyweight', 'duration', 'repdb-hollow-body-hold.webp', null, ARRAY['Lie on your back with arms extended overhead and legs straight.', 'Press the lower back firmly into the floor.', 'Lift the shoulders, head, and legs slightly off the floor.', 'Hold the position with arms and legs extended, body in a shallow banana shape.', 'Hold for the prescribed time.', 'Tip: Keep the lower back glued to the floor — if it lifts, raise the legs higher.', 'Tip: Tuck the chin slightly to engage the upper abs.', 'Tip: Bend the knees to scale if the position breaks.']::text[]),
  ('Jackknife Sit-Up', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-jackknife-sit-up.webp', 'repdb-jackknife-sit-up-end.webp', ARRAY['Lie face-up on the floor with arms extended overhead and legs extended straight.', 'Simultaneously lift the torso and the straight legs off the floor.', 'Reach the hands up toward the feet as the feet rise — meet above the hips.', 'Lower the torso and legs back to the floor under control.', 'Repeat for the recommended number of repetitions.', 'Tip: Arms and legs move at the same speed — avoid a kick-first cheat.', 'Tip: If the lower back arches on the return, slow down and don''t fully touch the floor.']::text[]),
  ('Kettlebell Russian Twist', 'core', 'kettlebell', 'weight_reps', 'repdb-kettlebell-russian-twist.webp', 'repdb-kettlebell-russian-twist-end.webp', ARRAY['Sit on the floor with your knees bent and feet lifted off the ground.', 'Hold a kettlebell with both hands in front of your chest.', 'Lean back slightly to engage your core.', 'Rotate your torso to one side, bringing the kettlebell next to your hip.', 'Rotate to the opposite side in a controlled motion.', 'Repeat for the desired number of reps.', 'Tip: Rotate your whole torso, not just your arms.', 'Tip: Keep your spine tall instead of slumping as you twist.', 'Tip: Keep your legs still as your torso moves side to side.']::text[]),
  ('L Sit', 'core', 'bodyweight', 'duration', 'repdb-l-sit.webp', null, ARRAY['Sit on the floor or press up on parallel bars with arms straight.', 'Lock your elbows and depress your shoulders.', 'Lift your legs straight out in front of you parallel to the floor.', 'Form an L shape with your body.', 'Hold the position for the prescribed duration.', 'Lower your legs with control to exit.', 'Tip: Bend your knees into a tuck position if the full hold is too hard.', 'Tip: Point your toes and squeeze your quads to keep legs straight.', 'Tip: Breathe steadily during the hold rather than holding your breath.']::text[]),
  ('Medicine Ball Side Throw', 'core', 'other', 'weight_reps', 'repdb-medicine-ball-side-throw.webp', 'repdb-medicine-ball-side-throw-end.webp', ARRAY['Stand with your feet a little wider than shoulder-width, holding a medicine ball with both hands in front of your torso.', 'Turn your torso and the ball toward your back hip, bending your knees slightly and keeping your chest up.', 'Start the throw by turning your back hip forward and pivoting on the ball of your back foot.', 'Let your torso and arms follow, throwing the ball out to the side with both hands.', 'Finish facing the direction of the throw with your arms extended.', 'Retrieve the ball, reset, and repeat for the planned repetitions, then switch sides.', 'Tip: Start the throw from the hips, not the arms; the trunk and arms should follow the hip turn.', 'Tip: Throw explosively, but keep your back neutral as you rotate rather than bending sideways.', 'Tip: Use a ball light enough to throw fast; a heavy ball slows the rotation and turns it into a push.']::text[]),
  ('Plank Knee Tuck', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-plank-knee-tuck.webp', 'repdb-plank-knee-tuck-end.webp', ARRAY['Set up in a high plank with the hands under the shoulders and the body in a straight line from head to heels.', 'Press the floor away and brace the trunk so the hips neither sag nor pike.', 'Draw one knee in towards the chest without letting the hips rise.', 'Extend the leg back to the starting position under control.', 'Repeat with the other leg and keep alternating for the desired number of repetitions.', 'Tip: Keep the hips level with the shoulders; letting them lift turns this into a pike.', 'Tip: Pull the knee in with the abdominals rather than by hopping off the supporting foot.', 'Tip: Keep the shoulders stacked over the wrists and push the floor away so the upper body does not sink.']::text[]),
  ('Ring L-Sit', 'core', 'bodyweight', 'duration', 'repdb-ring-l-sit.webp', null, ARRAY['Set the rings at about hip height and grip them with the arms straight beside the body.', 'Press down on the rings and lift the body into the support position, with the shoulders pushed down and away from the ears.', 'Turn the rings out slightly, brace the abdominals and raise the straight legs until they are parallel to the floor.', 'Hold the position, keeping the rings steady and the knees locked.', 'Lower the legs, then the body, under control.', 'Tip: Keep the arms locked and the shoulders pushed down; do not sag between the rings.', 'Tip: Build up from tucked holds, and from parallettes or a dip station, before moving to rings.', 'Tip: Point the toes and squeeze the legs together.']::text[]),
  ('Ring Plank', 'core', 'bodyweight', 'duration', 'repdb-ring-plank.webp', null, ARRAY['Set the rings at about knee height and take hold of them with the arms straight under the shoulders.', 'Step the feet back into a plank, with the body in a straight line from head to heels.', 'Brace the abdominals and glutes and press the rings down and slightly out to keep them steady.', 'Hold the position without letting the hips sag or the rings drift apart.', 'Step the feet in and stand up to finish.', 'Tip: Keep the rings directly under the shoulders; if they swing, place the feet wider.', 'Tip: Push the floor away through the rings so the shoulder blades stay wide.', 'Tip: Raise the rings to make the hold easier and lower them to make it harder.']::text[]),
  ('Scissor Kicks', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-scissor-kicks.webp', 'repdb-scissor-kicks-end.webp', ARRAY['Lie flat on your back with your hands under your glutes.', 'Lift both legs a few inches off the floor.', 'Alternate crossing one leg over the other in a scissor motion.', 'Keep your lower back pressed into the floor.', 'Maintain a steady rhythm throughout.', 'Repeat for the desired number of reps.', 'Tip: Press your lower back into the floor throughout.', 'Tip: Keep your legs straight and close to the ground.', 'Tip: Move with control rather than speed.']::text[]),
  ('Single-Arm Plank', 'core', 'bodyweight', 'duration', 'repdb-single-arm-plank.webp', null, ARRAY['Set up in a high plank with your hands under your shoulders and your feet a little wider than hip-width.', 'Brace your trunk and squeeze your glutes to keep your body in one straight line.', 'Shift your weight onto one arm and lift the other hand off the floor, resting it on your hip or behind your back.', 'Keep your hips and shoulders level and square to the floor.', 'Hold for the planned time, then replace the hand and rest.', 'Repeat on the other arm.', 'Tip: Place your feet wider than usual to give yourself a more stable base.', 'Tip: Stop the hips from twisting toward the lifted arm; the body should stay as flat as in a normal plank.', 'Tip: Progress by shortening the lift time first, then lengthen it as the trunk gets stronger.']::text[]),
  ('Supine Windshield Wipers', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-supine-windshield-wipers.webp', 'repdb-supine-windshield-wipers-end.webp', ARRAY['Lie on your back with the arms out to the sides and the knees bent over the hips.', 'Brace the trunk so the lower back does not lift off the floor.', 'Lower both legs together towards one side as far as the shoulders stay down.', 'Bring them back through the centre and lower to the other side.', 'Keep alternating for the desired number of repetitions.', 'Tip: Both shoulders stay on the floor; the range is defined by them, not by the legs.', 'Tip: Keep the knees together so the pelvis moves as one unit.', 'Tip: Straighten the legs for a much harder version once the control is there.']::text[]),
  ('Toes to Bar', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-toes-to-bar.webp', 'repdb-toes-to-bar-end.webp', ARRAY['Hang from a pull-up bar with an overhand grip, arms fully extended and body still.', 'Engage your lats and core to prevent swinging.', 'Raise your legs with straight knees, reaching your toes up toward the bar.', 'Touch the bar with your toes, then lower your legs under control.', 'Repeat for the desired reps.', 'Tip: Initiate the movement from your core, not by kicking with momentum.', 'Tip: Exhale forcefully as you raise your legs to increase intra-abdominal pressure.', 'Tip: If you cannot reach the bar yet, build up with hanging leg raises first; they are the easier step towards it.']::text[]),
  ('TRX Plank', 'core', 'bodyweight', 'duration', 'repdb-trx-plank.webp', null, ARRAY['Place both feet in the TRX foot cradles.', 'Assume a forearm or high plank position on the floor.', 'Keep your body in a straight line from head to heels.', 'Brace your core and squeeze your glutes.', 'Hold the position for the desired time.', 'Lower your knees to exit safely.', 'Tip: Do not let your hips sag toward the floor or pike upward.', 'Tip: Stack your shoulders directly over your elbows or hands.', 'Tip: Minimize strap sway by pressing your feet gently into the cradles.']::text[]),
  ('TRX Side Plank', 'core', 'bodyweight', 'duration', 'repdb-trx-side-plank.webp', null, ARRAY['Place both feet in the TRX foot cradles and lie on your side.', 'Prop up on your bottom forearm with your elbow under your shoulder.', 'Lift your hips so your body forms a straight line.', 'Stack your top foot over the bottom foot.', 'Hold the position while breathing steadily.', 'Lower and switch sides after the set.', 'Tip: Brace your obliques before lifting your hips off the floor.', 'Tip: Do not let your hips drop toward the floor.', 'Tip: Press the forearm into the floor to keep the shoulder active.']::text[]),
  ('V Ups', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-v-ups.webp', 'repdb-v-ups-end.webp', ARRAY['Lie flat on your back with arms extended overhead and legs straight.', 'Simultaneously raise your legs and upper body toward each other.', 'Reach your hands toward your feet at the top, forming a V shape.', 'Keep your legs straight throughout the movement.', 'Lower both ends under control back to the floor.', 'Repeat for the desired number of reps.', 'Tip: Keep your legs straight as you lift them.', 'Tip: Reach your hands toward your feet at the top.', 'Tip: Lower both ends under control rather than dropping flat.']::text[]),
  ('V-Sit', 'core', 'bodyweight', 'bodyweight_reps', 'repdb-v-sit.webp', null, ARRAY['Sit on the floor with your legs extended in front of you.', 'Lean back slightly and lift your legs off the floor.', 'Reach your arms forward so your body forms a V shape.', 'Balance on your sit bones with core tight.', 'Hold the position while breathing steadily.', 'Lower your legs and torso to exit.', 'Tip: Keep your chest lifted and spine long rather than rounding the back.', 'Tip: Bend the knees if you cannot hold straight legs yet.']::text[]),
  ('Weighted Wall Crunch', 'core', 'other', 'weight_reps', 'repdb-weighted-wall-crunch.webp', 'repdb-weighted-wall-crunch-end.webp', ARRAY['Lie on your back and park your legs so your hips cannot help: brace your feet against a wall or a box, or hold your legs up with the knees bent.', 'Hold a weight against your chest with both hands -- a plate, a dumbbell, or a kettlebell all work.', 'Crunch up, lifting your shoulder blades off the floor.', 'Lower with control.', 'Repeat.', 'Tip: Exhale as you crunch up and inhale on the way down.', 'Tip: Keep your neck relaxed instead of pulling your head forward.', 'Tip: Press your lower back into the floor throughout the movement.']::text[]),
  ('Air Bike', 'cardio', 'machine', 'duration', 'repdb-air-bike.webp', null, ARRAY['Sit on the air bike and grip the moving handles.', 'Place your feet on the pedals and brace your core.', 'Push and pull the handles while pedaling at a steady pace.', 'Drive with both arms and legs to maintain power output.', 'Continue for the desired duration or distance.', 'Tip: Keep your torso upright and avoid slumping over the handles.', 'Tip: Breathe rhythmically to sustain effort over longer intervals.', 'Tip: Pull the handles with your back, not just your arms.']::text[]),
  ('Battle Rope Double Slam', 'cardio', 'other', 'duration', 'repdb-battle-rope-double-slam.webp', 'repdb-battle-rope-double-slam-end.webp', ARRAY['Take one rope end in each hand and face the anchor, standing far enough back that the ropes have a slight slack.', 'Set your feet slightly wider than your hips and sit into a quarter squat with your chest up.', 'Swing both arms up together, letting the ropes rise in front of you as you extend through the hips.', 'Slam both ends down to the floor at the same time, hinging at the hips and driving through your lats.', 'Ride the rebound straight back into the next slam, keeping both arms moving in unison rather than alternating.', 'Keep slamming for the desired time or number of reps.', 'Tip: Both arms move together — the moment they start alternating you are doing the standard wave drill, which is a different exercise.', 'Tip: Drive the slam with your hips and lats rather than your arms, or your shoulders will burn out long before your lungs do.', 'Tip: Stand at the right distance from the anchor: too close and the rope goes slack, too far and you cannot get a wave into it at all.']::text[]),
  ('Burpees', 'cardio', 'bodyweight', 'duration', 'repdb-burpees.webp', null, ARRAY['Stand with feet shoulder-width apart.', 'Squat down and place the hands on the floor in front of you.', 'Jump or step the feet back into a plank, then perform a push-up.', 'Jump or step the feet forward to the hands.', 'Stand up and jump explosively, reaching the arms overhead.', 'Tip: Keep the back flat in the plank — do not let the hips sag.', 'Tip: Land softly from the jump.', 'Tip: Scale by stepping the feet back instead of jumping.']::text[]),
  ('Heel Flicks', 'cardio', 'bodyweight', 'duration', 'repdb-heel-flicks.webp', null, ARRAY['Stand tall with the feet under the hips and the arms bent as for running.', 'Begin jogging lightly in place.', 'Flick one heel up towards the same-side glute without driving the knee forward.', 'Switch feet quickly and continue alternating at an even rhythm.', 'Stay light on the forefeet and keep the torso upright for the full interval.', 'Tip: Aim for quick relaxed contacts rather than forcing the heel into the glute.', 'Tip: Keep the knees pointing down instead of lifting them like high knees.', 'Tip: Start slowly and increase cadence only after the rhythm feels smooth.']::text[]),
  ('High Knees', 'cardio', 'bodyweight', 'duration', 'repdb-high-knees.webp', null, ARRAY['Stand tall with feet hip-width apart.', 'Drive one knee up toward the chest while pumping the opposite arm.', 'Quickly switch legs, mirroring the arm action.', 'Continue alternating at a fast pace.', 'Continue for the prescribed work interval.', 'Tip: Drive the knees up to at least hip height.', 'Tip: Stay light on the balls of the feet.', 'Tip: Keep the torso upright — do not lean back.']::text[]),
  ('Incline Treadmill Walk', 'cardio', 'machine', 'duration', 'repdb-incline-treadmill-walk.webp', null, ARRAY['Start the belt at a slow walking speed and step on, then raise the incline to your target gradient.', 'Walk with a long, deliberate stride, rolling from heel to toe and pushing the belt away behind you with each step.', 'Stand tall and lean from the ankles with the hill rather than folding forward at the waist.', 'Keep at least one foot on the belt at all times — walk the hill, do not break into a jog.', 'Let your arms swing naturally, or rest them lightly on the rails for balance without carrying your weight on them.', 'Hold the gradient for the desired time, then lower the incline and walk level for a few minutes to finish.', 'Tip: Pick a speed you can still walk at. As soon as you need a flight phase to keep up, drop the speed or the incline — it is a walk, not a run.', 'Tip: Hanging your bodyweight off the handrails removes most of the work the hill is there to create; touch them for balance only.', 'Tip: The steep grade is what moves the effort from the quads into the glutes and hamstrings, so raise the incline before you raise the speed.']::text[]),
  ('Jumping Jacks', 'cardio', 'bodyweight', 'duration', 'repdb-jumping-jacks.webp', 'repdb-jumping-jacks-end.webp', ARRAY['Stand tall with feet together and arms at your sides.', 'Simultaneously jump your feet out wide and raise your arms overhead.', 'Ensure your arms meet or nearly meet above your head.', 'Jump your feet back together while lowering your arms to your sides.', 'Maintain a continuous, rhythmic motion.', 'Tip: Land softly on the balls of your feet to absorb impact.', 'Tip: Keep your core engaged throughout the movement.', 'Tip: Control your breathing; inhale as you jump out, exhale as you jump in.', 'Tip: Increase speed for a greater cardiovascular challenge.']::text[]),
  ('SkiErg', 'cardio', 'machine', 'duration', 'repdb-ski-erg.webp', 'repdb-ski-erg-end.webp', ARRAY['Stand facing the SkiErg with the handles overhead and the feet about hip-width apart.', 'Brace the trunk and drive the handles down by pulling with the lats while hinging slightly at the hips.', 'Finish with the hands beside the thighs and the knees softly bent.', 'Let the cords retract as you return the arms overhead and stand tall.', 'Repeat smoothly while keeping the heels planted and the torso controlled.', 'Tip: Lead the pull with the lats instead of turning it into an arm-only movement.', 'Tip: Keep the hinge compact; do not collapse into a deep squat.', 'Tip: Allow the handles to return under control so the cords stay taut.']::text[]),
  ('Walking', 'cardio', 'bodyweight', 'duration', 'repdb-walking.webp', null, ARRAY['Stand tall with your weight over the middle of your feet and your shoulders relaxed, not pulled back.', 'Step forward and land on your heel, then roll through the foot and push off the ball and toes.', 'Keep at least one foot on the ground at all times — as soon as both leave the floor you are running, not walking.', 'Let your arms swing naturally from the shoulder, opposite arm to opposite leg, with the elbows softly bent.', 'Look ahead rather than down at your feet, and breathe through a steady, repeatable rhythm.', 'Continue for the desired time or distance, picking a pace at which you could still hold a conversation.', 'Tip: Pace is the whole variable here. A stroll and a brisk walk are different training stimuli, so pick one deliberately instead of drifting.', 'Tip: Lengthen the push behind you rather than reaching further in front — overstriding lands you on a straight leg and brakes every step.', 'Tip: This is the one piece of conditioning you can do daily without needing to recover from it, which is what makes it worth programming rather than leaving to chance.']::text[])
) as v (name, muscle_group, equipment, kind, image_path, image_path_end, instructions)
where not exists (select 1 from exercises e where e.user_id is null and e.name = v.name);
